window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-hepato-hep-2"]={"block":"medcurso:medcurso-hepato-hep-2","label":"Medcurso · HEP 2","count":455,"questions":[{"id":"medcurso-hepato-hep-2-343838","number":"343838","sourceNumber":"343838","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente masculino de 60 anos, cirrótico por vírus C, tratando encefalopatia\nhepática persistente, já com correção dos fatores\ndesencadeantes, em uso de lactulose via oral,\n30ml 6/6h. Mantém encefalopatia grau II, com 4 evacuações/dia. Qual a melhor conduta:","options":{"A":"Aumentar a dose de lactulose.","B":"Associar metronidazol.","C":"Associar neomicina.","D":"Associar rifaximina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-281164","number":"281164","sourceNumber":"281164","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O manejo de uma hemorragia digestiva de origem varicosa possui algumas diferenças\nimportantes em relação a não varicosa. Em relação a hemorragia varicosa analise as assertivas\nabaixo: I) - Uma rápida correção da deficiência de fluidos e da pressão arterial aumenta o risco de\nnovo sangramento das varizes. II) - Os defeitos na coagulação são frequentes nestes pacientes e\nprecisam ser corrigidos rigorosamente. III) - Estes pacientes devem receber um curso empírico de\nantibiótico de largo espectro e esta terapia deve ser iniciada no momento da alta hospitalar. IV) -\nAgentes vasoativos que induzem a vasoconstricção esplâncnica resultam em controle temporário\ndo sangramento e seu uso deve ser continuado após a alta hospitalar. Estão corretas as\nafirmativas:","options":{"A":"I e II apenas.","B":"II e IV apenas.","C":"I, III e IV apenas.","D":"I, II e III apenas.","E":"todas estão corretas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-251865","number":"251865","sourceNumber":"251865","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 61 anos, com diagnóstico de cirrose alcoólica, é submetido à endoscopia\ndigestiva alta na qual se verifica a presença\nde varizes esofágicas de médio e grande calibre. Não\ntem história de sangramento digestivo. A albumina sérica é de 3,5 g/dl (VR 3,5 a 4,5g/dl) e o tempo\nde protrombina é de 10 segundos/85% de atividade. Qual das condutas abaixo é a mais adequada\npara a profilaxia do sangramento?","options":{"A":"Indicar o uso de betabloqueador.","B":"Indicar o uso de ocreotida.","C":"Realizar shunt portossistêmico.","D":"Realizar escleroterapia profilática."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217659","number":"217659","sourceNumber":"217659","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A cirrose hepática, eventualmente, cursa com quadros sindrômicos que comprometem\ncérebro, pulmão, coração e rins. A platipneia\ne ortodeoxia são manifestações clínicas de:","options":{"A":"Hipertensão portopulmonar.","B":"Cardiomiopatia cirrótica.","C":"Síndrome hepatopulmonar.","D":"Síndrome hepatorrenal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217727","number":"217727","sourceNumber":"217727","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 57 anos, portador de cirrose hepática, evolui com ascite e edema de MMII, o\nGASA foi maior que 1,1, a citometria do líquido ascítico revelou leucometria total de 780\nleucócitos/ml, com 57% de polimorfonucleares, a cultura do líquido ascítico foi negativa. O\ndiagnóstico e manejo corretos desse paciente são:","options":{"A":"PBE (peritonite bacteriana espontânea) / Antibioticoprofilaxia.","B":"PBE / Antibioticoterapia e albumina humana.","C":"Bacterascite / Antibioticoterapia e albumina humana.","D":"Bacterascite / Antibioticoprofilaxia."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217674","number":"217674","sourceNumber":"217674","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente sexo masculino, 55 anos, cirrótico, Child B, foi submetido a uma ressecção do\nsegmento lll do fígado. Qual a complicação NÃO infecciosa mais comum?","options":{"A":"Trombose venosa profunda.","B":"Arritmia cardíaca.","C":"Ascite.","D":"Insuficiência renal aguda."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-182654","number":"182654","sourceNumber":"182654","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente portador de cirrose hepática por VHB e VHD é trazido ao serviço de urgência\ne emergência devido a um quadro de desorientação\ne alterações no sono. O paciente está em uso\nde diuréticos e outros medicamentos prescritos pelo hepatologista. Após anamnese e exame físico,\na principal hipótese diagnóstica foi Encefalopatia Hepática (EH). Com relação a esse caso, pode-se\nafirmar que se deve:","options":{"A":"Identificar o fator desencadeante da EH visando o manejo adequado.","B":"Manter os diuréticos para evitar o surgimento de ascite e edema de MMII.","C":"Iniciar antibioticoterapia endovenosa para reduzir a proliferação bacteriana.","D":"Indicar benzodiazepínico para evitar quadro de agitação e melhorar o padrão de sono."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-182671","number":"182671","sourceNumber":"182671","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma das principais causas de óbitos em pacientes com cirrose hepática é o\nrompimento de varizes de esôfago que leva à\nhemorragia digestiva alta (HDA). Para manejo dessa\ncondição, a melhor indicação é iniciar imediatamente a administração de:","options":{"A":"Vasoconstritor.","B":"Betabloqueador.","C":"Vasodilatador.","D":"Antibiótico."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-159128","number":"159128","sourceNumber":"159128","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O uso de medicamentos em pacientes com cirrose hepática deverá ser feito com\ncautela. Há inclusive algumas drogas que são contraindicadas em tais pacientes pelo risco de\ncausar descompensação do quadro, dentre as quais se pode citar:","options":{"A":"Tramadol.","B":"AAS em pacientes com elevado risco cardiovascular.","C":"Anti-inflamatório esteroidal.","D":"Anti-inflamatório não esteroidal."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369491","number":"369491","sourceNumber":"369491","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Identifique o tratamento farmacológico de urgência de primeira linha para esse\npaciente:","options":{"A":"Betabloqueadores.","B":"Terlipressina ou octreotida.","C":"Inibidores da bomba de prótons (IBP).","D":"Vonoprazana."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369523","number":"369523","sourceNumber":"369523","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 62 anos de idade, com histórico de cirrose hepática devido a hepatite C\ncrônica, é admitido na emergência com\nhematêmese. Relata vômitos de sangue vermelho vivo e\napresenta melena. O paciente está consciente, mas pálido e letárgico. Seus sinais vitais são: PA:\n90x60 mmHg, FC: 110 bpm e PR: 22ipm. Ao exame físico apresenta ainda ascite moderada,\ncirculação colateral abdominal visível e esplenomegalia. Uma endoscopia prévia, realizada há um\nano, mostrou várias varizes esofágicas de grande calibre sem sinais de hemorragia naquela\nocasião. Indique, entre as seguintes, a medida recomendada para a profilaxia de peritonite\nbacteriana espontânea (PBE) neste paciente","options":{"A":"Administração de albumina intravenosa.","B":"Administração de lactulose.","C":"Profilaxia antibiótica com ciprofloxacina.","D":"Administração de fatores de coagulação."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-372049","number":"372049","sourceNumber":"372049","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O sangramento das varizes esofagogástricas é a complicação da hipertensão portal\nmais ameaçadora à vida, sendo responsável por\naproximadamente um terço de todos os óbitos de\npacientes com cirrose. Sobre o tema, assinale a correta.","options":{"A":"Os pacientes com obstrução venosa portal extra?hepática e função hepática normal tem pior\nprognóstico quando comparados aos pacientes com cirrose já instalada.","B":"Os pacientes com cirrose descompensada (Child-Pugh C) têm maior chance de óbito quando\ncomparados aos pacientes sem cirrose instalada.","C":"Tratamentos cirúrgicos são geralmente de primeira linha, uma vez que estes pacientes têm risco\nelevado para endoscopia digestiva alta em decorrência da função hepática descompensada.","D":"A ligadura elástica é a única opção disponível para o controle de hemorragia varicosa aguda."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-372050","number":"372050","sourceNumber":"372050","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A figura abaixo represente um shunt ou desvio do sistema portal para a drenagem da V.\ncava inferior. Das patologias abaixo, em qual patologia pode-se utilizar tal terapia?","options":{"A":"Hipertensão portal.","B":"Pancreatite aguda.","C":"Pancreatite crônica.","D":"Obstrução duodenal."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/372050.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-280411","number":"280411","sourceNumber":"280411","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa correta sobre o tratamento indicado para pacientes com falência\nhepática aguda devido à síndrome de Budd-Chiari.","options":{"A":"Pulsoterapia com corticoides.","B":"N-acetilcisteína.","C":"Transplante hepático.","D":"Colocação de um stent portossistemico intra-hepático por via transjugular."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-278646","number":"278646","sourceNumber":"278646","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Os patógenos mais comuns em adultos com peritonite bacteriana espontânea são:","options":{"A":"Escherichia coli e Klebsiella pneumoniae.","B":"Staphylococcus aureus e o Streptococcus pneumoniae.","C":"Proteus sp. e Acinetobacter baumannii.","D":"Candida albicans e Escherichia coli."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-231353","number":"231353","sourceNumber":"231353","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na ascite relacionada à cirrose hepática, conforme critérios do Clube Internacional de\nascite qual a afirmativa correta:","options":{"A":"Pacientes com ascite grau III, com necessidade de paracentese, são considerados como\nportadores de ascite refratária.","B":"A Paracentese terapêutica, seguida de expansão plasmática com albumina (8g/litro) é o\ntratamento da ascite grau III, se forem retirados mais do que 5 litros.","C":"A abordagem farmacológica da ascite requer o uso inicial de diurético de alça associado à\nespironolactona","D":"O TIPS é o tratamento de escolha nos casos de ascite refratária.","E":"O GASA < 1.1 deve ser considerado no diagnóstico de PBE na hipertensão portal da cirrose\nhepática."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249188","number":"249188","sourceNumber":"249188","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"As manifestações clínicas da Doença de Wilson devem-se, principalmente, ao\nacometimento hepático e do sistema nervoso\ncentral (SNC) (2,3), sendo extremamente variáveis.\nAs manifestações clínicas do SNC podem, em algumas situações, ser a forma de apresentação da\ndoença. Podemos aceitar que:","options":{"A":"Os sinais e sintomas raros são anormalidades motoras similares às da doença de Parkinson,\nincluindo distonia, hipertonia, rigidez, tremores e Disartria.","B":"Os sinais e sintomas mais frequentes são anormalidades motoras similares às da doença de\nParkinson, incluindo distonia, hipertonia, rigidez, tremores e Disartria.","C":"Os sinais e sintomas mais frequentes são anormalidades sensitivas similares às da doença de\nParkinson, incluindo distonia, hipertonia, rigidez, tremores e Disartria.","D":"Os sinais e sintomas mais frequentes são anormalidades motoras similares às da doença de\nParkinson, incluindo distonia, hipotonia, flacidez e Disartria."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-231354","number":"231354","sourceNumber":"231354","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 45 anos, cirrótico em tratamento de ascite de difícil controle há 2 meses,\napresenta-se com quadro de alteração do ciclo sono-vigília, confusão mental. O exame físico\nevidencia desidratação (++/4), hipocorado (+/4), FC: 90 bpm, PA: 100x60 mmHg, desorientado no\ntempo e espaço com flapping presente. Ascite grau II, indolor à palpação e sem edema em\nmembros inferiores. Os exames laboratoriais evidenciaram: Hb: 10,3,Hct: 32 Leuc: 5.000,\nplaquetas: 72.000, Ur: 80, Cr: 1,4, Na: 125, K: 3,0. Na abordagem inicial para o quadro de\nEncefalopatia Hepática deve ser considerado:","options":{"A":"Tratar inicialmente para Encefalopatia com lactulose 30 ml a cada 8 horas, até atingir 2-3\nevacuações pastosas.","B":"Correção do fator precipitante que poderia ser a desidratação associada à correção da\nhipocalemia e provável alcalose metabólica,\ndevido a uso excessivo de diuréticos e diminuição na\nexcreção renal de íons de hidrogênio.","C":"Correção do fator precipitante que poderia ser a desidratação provavelmente de origem\nhipovolêmica, hidratação vigorosa com soro fisiológico associada a lactulose de 8/8 horas.","D":"Tratar inicialmente da IRA, com expansão volume com albumina 1 g/ kg/peso e em seguida a\nEncefalopatia.","E":"Tratar o fator precipitante, suspendendo o uso de diurético, associado à expansão de volume\ncom albumina1g/kg para IRA e lactulose 30 ml de hora em hora, até evacuação."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249195","number":"249195","sourceNumber":"249195","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"As opções terapêuticas na Doença de Wilson são diversas, incluem o tratamento\nmedicamentoso e o transplante hepático. Sendo assim, indique o item com erro:","options":{"A":"Dieta com baixa quantidade de cobre, principalmente nas fases iniciais da doença, também deve\nser adotada.","B":"Os alimentos com quantidade mais elevada de cobre são frutos do mar, chocolate, amêndoas,\ncafé, feijão, fígado, cogumelos e soja.","C":"A dieta isoladamente é suficiente para o tratamento.","D":"O transplante deve ser reservado para pacientes com doença hepática terminal refratária ou\nfulminante."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249197","number":"249197","sourceNumber":"249197","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na Doença de Wilson, o produto do gene ATP7B está presente no sistema de Golgi e é\nfundamental para o transporte de cobre através das membranas das organelas intracelulares. A\nalternativa adequada é:","options":{"A":"A ausência ou função diminuída do ATP7B reduz a excreção hepática de cobre e causa acúmulo\ndo metal na DW.","B":"A função aumentada da ATP7B reduz a excreção hepática de cobre e causa acúmulo do metal\nna DW.","C":"A ausência ou função diminuída do ATP7B aumenta a excreção hepática de cobre e causa\nacúmulo do metal na DW.","D":"A ausência ou função diminuída do ATP7B reduz a excreção hepática de cobre e causa redução\ndo metal na DW."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249414","number":"249414","sourceNumber":"249414","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual o valor do gradiente albumina soro-ascite (GASA) indica a etiologia da ascite\ncomo hipertensão portal?","options":{"A":"> 1","B":"> 1,1","C":"< 1","D":"< 1,1"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249231","number":"249231","sourceNumber":"249231","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A doença de Dupuytren acomete mais homens, na sétima década de vida e é\ncaracterizada classicamente por:","options":{"A":"Granulomas caseosos em articulações metacarpo-falangianas.","B":"Compressão do nervo mediano na passagem do túnel do carpo da mão.","C":"Fibrodisplasia da fáscia palmar, geralmente bilateral, com espessamento e formação de nódulos.","D":"Cisto sinovial com evolução para osteomielite em pacientes diabéticos."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212211","number":"212211","sourceNumber":"212211","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação ao transplante hepático, é correto afirmar:","options":{"A":"a colecistite aguda é a condição inflamatória mais temida no paciente transplantado.","B":"a trombose da veia porta no receptor é uma contraindicação absoluta ao transplante hepático.","C":"os distúrbios genéticos do metabolismo são a principal causa de transplante hepático em\ncrianças.","D":"a estenose da anastomose de via biliar é a complicação aguda mais temida no transplante\nhepático.","E":"nos pacientes transplantados, a incidência de câncer aumenta com o tempo de evolução e a\nmaioria é de pele."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212144","number":"212144","sourceNumber":"212144","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente foi atendida no hospital de emergência por quadro de dor em hipocôndrio\ndireito de forte intensidade, náuseas e\nvômitos após ingestão de alimentos gordurosos. Foi\nrealizada uma ultrassonografia de abdome superior que evidenciou colelitíase. Depois a paciente\nfoi encaminhada para consulta com um cirurgião digestivo, que optou agendar de forma eletiva a\ncolecistectomia. Durante a cirurgia para retirada da vesícula, visualizou-se um fígado de aspecto\nnodular e realizou-se uma biópsia hepática. Um mês após a cirurgia, saiu o resultado da biópsia\nhepática, que confirmou cirrose hepática. Em relação aos escores de prognóstico da cirrose\nhepática, assinale a alternativa correta.","options":{"A":"O MELD é calculado através de uma fórmula matemática que utiliza bilirrubina, ureia e INR.","B":"O escore de Child-Pugh utiliza 5 parâmetros, 1 parâmetro clínico e 4 parâmetros laboratoriais.","C":"A inclusão do potássio sérico no cálculo do MELD poderia aumentar o valor prognóstico desse\nescore.","D":"O escore de Child-Pugh divide-se em três grupos distintos (A, B ou C) em ordem decrescente de\ngravidade.","E":"O MELD tem sido adotado como critério de alocação de órgãos para o transplante de fígado em\ntodo o mundo."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216317","number":"216317","sourceNumber":"216317","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual é a primeira linha na terapêutica da encefalopatia hepática?","options":{"A":"Antibióticos.","B":"Transplante hepático.","C":"Diálise peritoneal.","D":"Lactulose."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212213","number":"212213","sourceNumber":"212213","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Ascite, encefalopatia hepática, síndrome hepatorrenal e complicações hemorrágicas\nsão consequências temidas de hipertensão portal.\nDiferentes condições patológicas em várias\nlocalizações (pré-hepática, hepática e pós-hepática) no sistema\n\nportal são capazes de produzir Síndrome de Hipertensão Portal. Assinale a alternativa que\ncontempla uma causa de síndrome de hipertensão portal pós-hepática.","options":{"A":"Cirrose hepática.","B":"Esquistossomose.","C":"Doença veno-oclusiva.","D":"Trombose de veias hepáticas.","E":"Trombose do eixo esplenoportal."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-201780","number":"201780","sourceNumber":"201780","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na definição de IRA em pacientes com cirrose, conforme revisão do Clube Internacional\nde Ascite (2015), deve ser considerada\nINCORRETA a seguinte afirmação:","options":{"A":"É considerado IRA um aumento absoluto igual ou superior a 0,3 mg/dl na creatinina sérica.","B":"O valor fixo de 1,5 mg/dl não é mais utilizado.","C":"Os estádios de gravidade de IRA foram definidos de acordo com os níveis de elevação de\ncreatinina sérica.","D":"O débito urinário ainda deve ser considerado para definição de IRA.","E":"A síndrome hepatorrenal deve ser considerada quando forem excluídos fatores precipitantes e\nresposta insatisfatória a expansão com albumina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-201785","number":"201785","sourceNumber":"201785","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na abordagem terapêutica da ascite volumosa podemos considerar as seguintes\npossibilidades:","options":{"A":"Paracentese de grande volume com expansão de volume com albumina EV;","B":"Uso de diuréticos combinados ? Furosemida 80 mg + espironolactona 100 mg","C":"Proteína no líquido ascítico < a 1,0 g justifica a profilaxia de peritonite bacteriana espontânea\ncom o uso de quinololonas;","D":"Apenas duas alternativas estão corretas;","E":"Na hemorragia digestiva alta está indicada a profilaxia primária para peritonite bacteriana\nespontânea por sete dias."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216283","number":"216283","sourceNumber":"216283","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação às complicações no pós-operatório do\ntransplante hepático ortotópico.","options":{"A":"No pós-operatório imediato, o paciente pode sofrer aumento expressivo do volume extracelular\npela administração excessiva de líquidos, o que pode\nprovocar sobrecarga cardíaca e edema\npulmonar.","B":"A hipertensão arterial é uma complicação frequente no pós-operatório imediato, e a maior\nincidência ocorre entre o quinto e o oitavo dias.","C":"Existe alta incidência de derrame pleural, principalmente à direita, o que parece ter íntima\nrelação com a manipulação cirúrgica do diafragma e o pinçamento da veia cava.","D":"Atelectasia pulmonar também é frequente e ocorre mais à direita."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-219879","number":"219879","sourceNumber":"219879","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 45 anos apresenta níveis das aminotransferases hepáticas ? ALT e AST ?\ncerca de duas vezes o valor de referência, há aproximadamente cinco anos. É completamente\nassintomático e não apresenta passado mórbido de importância. Possui quatro irmãos mais velhos,\ntodos hígidos; uma irmã tinha história de anemia resolvida após menopausa. Nega etilismo, uso de\nmedicamentos, uso de drogas ilícitas e hemotransfusão. Ao exame físico, o fígado estava\ndiscretamente aumentado. Na investigação laboratorial observou-se Índice de Saturação\nTransferrina (IST) de 95% e ferritina de 1.900 µgL. Sorologia para hepatites B e C era negativa. Em\nrelação ao caso apresentado, assinale a afirmativa INCORRETA.","options":{"A":"Biópsia hepática é necessária para se confirmar o diagnóstico mesmo em portadores da\nmutação C282Y em homozigose.","B":"Depósito progressivo de ferro no fígado pode explicar a hepatomegalia e a elevação das\naminotransferases observadas.","C":"Hepatocarcinoma é uma das complicações mais graves e causa comum de mortes nos\npacientes com essa afecção.","D":"O diagnóstico mais provável é hemocromatose hereditária, mesmo sendo a história familiar\nnegativa."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181373","number":"181373","sourceNumber":"181373","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, portadora de cirrose hepática secundária a álcool, foi encaminhada para o\nambulatório de hepatologia para acompanhamento. Etilista crônica, ingestão maior que 80 g de\nálcool por dia, durante 40 anos. Realizou uma endoscopia digestiva alta que evidenciou três\ncordões varicosos de médio calibre com sinal da cor vermelha. Nega história de hemorragia\ndigestiva alta. Foi orientada pelo seu médico assistente a iniciar um betabloqueador não seletivo\n(BBNS) como profilaxia primária de sangramento. Assinale a alternativa que contém uma condição\nclínica que não impede o uso do BBNS.","options":{"A":"Hipotensão arterial.","B":"Bradicardia acentuada.","C":"Bloqueios atrioventriculares.","D":"Doença pulmonar crônica obstrutiva.","E":"Diabéticos não insulino dependentes."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183042","number":"183042","sourceNumber":"183042","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa que correponde à doença com maior indicação de transplante no\nmundo ocidental.","options":{"A":"Cirrose Biliar Primária.","B":"Cirrose alcoólica.","C":"Atresia Biliar.","D":"Cirrose por Hepatite C."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183058","number":"183058","sourceNumber":"183058","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre as complicações iniciais do transplante de fígado, assinale a alternativa\nINCORRETA.","options":{"A":"Os primeiros sinais que o fígado recém-implantado está funcionando são melhora da acidose\nmetabólica, normalização dos parâmetros da coagulação e a produção de bile.","B":"A trombose da artéria hepática ocorre em 10% dos procedimentos de transplante em adultos, e\nem crianças a incidência é de três vezes menor.","C":"A disfunção primária refere-se a uma condição rara e fatal em que o fígado transplantado não\nfunciona.","D":"A trombectomia da artéria hepática é necessária na maioria dos pacientes com trombose da\nartéria hepática."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183064","number":"183064","sourceNumber":"183064","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Os componentes da pontuação MELD foram escolhidos porque representam critérios\nobjetivos que podem ser revisados e são facilmente aplicáveis. Fazem parte dessa pontuação:","options":{"A":"Albumina, creatinina e bilirrubina.","B":"INR, albumina e creatinina.","C":"Transaminase glutâmico-oxalacética, bilirrubina e INR.","D":"Creatinina, bilirrubina e INR."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183566","number":"183566","sourceNumber":"183566","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 45 anos desenvolve ginecomastia. A provável patologia causadora desse\ntranstorno é","options":{"A":"porfiria aguda.","B":"cirrose hepática.","C":"pancreatite necro-hemorrágica.","D":"ulcera péptica."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187863","number":"187863","sourceNumber":"187863","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com 68 anos, sexo masculino, caquético, portador de cirrose hepática, evoluiu\ncom alteração do nível de consciência, sendo este quadro diagnosticado como encefalopatia\nhepática. Assinale entre as drogas abaixo relacionadas aquela que NÃO é potencialmente benéfica\npara a terapia de encefalopatia:","options":{"A":"L-ornitina-l-aspartato.","B":"Metronidazol.","C":"Propranolol.","D":"Rifaximina."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187869","number":"187869","sourceNumber":"187869","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com 59 anos, apresenta perda de peso de 10kg em 6 meses, ascite volumosa\ne queixa de astenia acompanhada de anorexia.\nFoi coletado líquido ascítico para estudo\nlaboratorial. Resultados: coloração âmbar, gradiente albumina sérica líquido ascítico (GASA) 0,8g/dl\ne contagem total de células de 400mm³ com predomínio de linfócitos. Assinale a alternativa\nCORRETA para o diagnóstico MAIS PROVÁVEL para este caso:","options":{"A":"Mixedema","B":"Síndrome de Budd-Chiari","C":"Trombose da veia porta","D":"Tuberculose"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158747","number":"158747","sourceNumber":"158747","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual dos itens seguintes é uma das variáveis analisadas no MELD Score de\nhepatopatas?","options":{"A":"Idade.","B":"Creatinina.","C":"Índice nutricional.","D":"Grau de encefalopatia.","E":"Causa da falência hepática."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158744","number":"158744","sourceNumber":"158744","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação às peritonites, é correto afirmar:","options":{"A":"Leucometria inferior a 2000 infere bom prognóstico.","B":"A anestesia desses pacientes deve ser combinada (geral e bloqueio) sempre que possível.","C":"Todo paciente com peritonite aguda difusa deve ser operado a menos que haja contraindicação\nclínica.","D":"A profilaxia da trombose venosa deve ser postergada, pois pode haver necessidade de nova\nabordagem cirúrgica.","E":"Exsudatos e debris devem ser removidos por irrigação com solução salina e instilação de\nmedicamentos na cavidade."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158807","number":"158807","sourceNumber":"158807","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dadas as indicações de transplante hepático, I. Colangite esclerosante primária; II.\nCirrose hepática autoimune; III. Doença de Wilson. Verifica-se que está (ão) CORRETAS (S):","options":{"A":"I, II e III.","B":"II e III, apenas.","C":"I e II, apenas.","D":"III, apenas.","E":"II, apenas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-152650","number":"152650","sourceNumber":"152650","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Utilizando o GASA como diagnóstico diferencial da ascite, é verdadeiro afirmar:","options":{"A":"GASA > ou = 1,1 é compatível com hipertensão portal.","B":"GASA > ou = 1,1 é compatível com síndrome nefrótica.","C":"GASA < ou = 1,1 é compatível com carcinomatose.","D":"GASA < ou = 1,1 é compatível com pancreatite crônica.","E":"Todas as alternativas estão corretas."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158742","number":"158742","sourceNumber":"158742","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O desenvolvimento da ascite na cirrose indica um mau prognóstico. A mortalidade é de\naproximadamente 40% após 1 ano e 50% em 2 anos. Constitui fator de mau prognóstico no\npaciente cirrótico com ascite: I. Hiponatremia; II. Pressão arterial baixa; III. Creatinina\nelevada; IV.\nSódio urinário baixo. Dos itens, verifica-se que está(ão) correto(s):","options":{"A":"II, apenas.","B":"I e II, apenas.","C":"III e IV, apenas.","D":"I, III e IV, apenas.","E":"I, II, III e IV."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-152660","number":"152660","sourceNumber":"152660","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na abordagem farmacológica de 1ª escolha da ascite do hepatopata crônico, deve ser\nconsiderado:","options":{"A":"Espironolactona.","B":"Espironolactona + furosemida.","C":"Furosemida.","D":"Duas alternativas estão corretas.","E":"Todas as alternativas são incorretas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158766","number":"158766","sourceNumber":"158766","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"JBC, sexo masculino, 75 anos, é admitido na enfermaria com ascite que se iniciou há 1\nmês. Relata perda ponderal de 8 Kg no período, nega uso de tatuagens, piercing, etilismo,\ntabagismo e passado de hepatites. Ao exame físico, não apresenta eritema palmar, telangiectasias\nou ginecomastia. No hospital, o residente realiza uma paracentese diagnóstica que mostra um\ngradiente albumina soro-ascite (GASA) de 0,8 g/dl. Qual o diagnóstico mais provável para o caso\nacima?","options":{"A":"Ascite cardíaca.","B":"Cirrose descompensada.","C":"Carcinomatose peritoneal.","D":"Esteatohepatite não alcoólica.","E":"Esquistossomose hepatoesplênica descompensada."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158405","number":"158405","sourceNumber":"158405","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com 53 anos e antecedente de cirrose hepática secundaria ao álcool, com\nclassificação quando estável Child B. Voltou a fazer ingestão de destilados há 1 semana e vem ao\nserviço com quadro de dor abdominal, anorexia, náuseas e sensação de mal-estar há 1 dia, além\nde sonolência maior que habitual. Ao exame: hipohidratado +/4+, ictérico ++/4+, acianótico,\nflapping\n\n+ PA: 110 x 68 mmHg; FC: 85 bpm abdome ascítico, com dor difusa á palpação, descompressão\nbrusca negativa Exames laboratoriais: Hb = 9,8,\ncom VCM de 104; leucócitos de 17.200 com 10%\nde bastonetes e 75% de segmentados. Ureia: 96; creatinina: 2,1; Na: 130 ; K: 4,8. Glicemia de 103\nmg/dl. bilirubima total: 18 (bilirubina direta 16,1). Tempo de protrombina de 18 segundos (normal\naté 13 segundos). TGO: 296; TGP: 98; albumina: 2,9. Fosfatase alcalina: 108; gama glutamil\ntransferase: 102. Qual a principal hipótese diagnóstica?","options":{"A":"Hepatite alcóolica aguda.","B":"Leptospirose.","C":"Síndrome hepatorrenal.","D":"Trombose de veias supra hepáticas.","E":"Hepatite viral aguda."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-49622","number":"49622","sourceNumber":"49622","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A dosagem de ceruloplasmina é utilizada para diagnóstico de:","options":{"A":"Hepatite autoimune.","B":"Cirrose biliar primária.","C":"Deficiência de alfa-1-antitripsina.","D":"Hemocromatose.","E":"Doença de Wilson."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-13145","number":"13145","sourceNumber":"13145","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Entre as substâncias a seguir, aquela que pode ser considerada o marcador sorológico\nmais relacionado à hepatite autoimune é:","options":{"A":"Anticorpo antimúsculo liso.","B":"P-ANCA.","C":"Anticorpo antimitocondrial.","D":"Reticulócitos.","E":"C-ANCA."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-327222","number":"327222","sourceNumber":"327222","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Ao avaliar um paciente com esteatose hepática, o que fazer em um primeiro momento?","options":{"A":"Investigar as possíveis causas etiológicas.","B":"Tranquilizar o paciente, pois tal doença não oferece riscos.","C":"Fazer avaliação bioquímica e elastografia hepática.","D":"Solicitar biópsia hepática."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-327243","number":"327243","sourceNumber":"327243","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, natural de Lábrea, dá entrada no pronto\natendimento com quadro de hematêmese volumosa e\nsinais de choque hipovolêmico, sendo\nencaminhado imediatamente a sala de reanimação. Ao exame físico, o paciente se encontra\nemagrecido, com nível de consciência rebaixado, pálido, ictérico ++/4, taquicárdico, taquipneico e\nhipotenso, com edema de membros inferiores. Seu abdome é ascítico, com evidente circulação\ncolateral periumbilical. A família não sabe referir sobre doenças de tratamento crônico ou\nacompanhamento médico. Você intuba o paciente e inicia reposição volêmica com ringer lactato\ncomo medidas iniciais. Sobre o caso acima, assinale a alternativa INCORRETA.","options":{"A":"O tratamento clínico de suporte pode incluir drogas como o octreotide e a vasopressina.","B":"O uso de sonda de Sangstaken-Blakemore pode ser indicado para a compressão mecânica do\nsítio de sangramento enquanto se compensa o paciente para o tratamento definitivo.","C":"No caso de falha do tratamento endoscópico, a anastomose porto-sistêmica intra-hepática\ntransjugular provavelmente terá maior chance de\nsucesso que o tratamento cirúrgico convencional.","D":"A melhor opção terapêutica para o caso é a endoscopia digestiva alta para esclerose de úlcera\npéptica."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252208","number":"252208","sourceNumber":"252208","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a utilização de antibióticos profiláticos nos pacientes cirróticos atendidos por\nhemorragia digestiva alta por varizes de esôfago, assinale a CORRETA:","options":{"A":"Está indicada para todos os pacientes independentemente da gravidade da doença de base.","B":"Está indicada apenas se alguma intervenção endoscópica for realizada.","C":"Foi associada à diminuição das taxas de infecções, mas sem impacto na sobrevida.","D":"Como o objetivo é a descontaminação intestinal, a via parenteral é menos eficaz e deve ser\nevitada."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252209","number":"252209","sourceNumber":"252209","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Ao avaliar um paciente com esteatose hepática, o que fazer em um primeiro momento?","options":{"A":"Tranquilizar o paciente, pois tal doença não oferece riscos.","B":"Investigar as possíveis causas etiológicas.","C":"Solicitar biópsia hepática.","D":"Tratar com pioglitazona e vitamina E."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-80925","number":"80925","sourceNumber":"80925","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 43 anos, alcoolista crônico foi encontrado com rebaixamento do estado de\nconsciência e levado ao Pronto-Socorro pelo Resgate. Ainda na ambulância, recebeu 50 ml de\nglicose a 50% endovenoso, com melhora do quadro, persistindo alguma confusão. Como se\nencontrava febril, foi necessário internação para investigação melhor do quadro. No dia seguinte, o\npaciente agravou o estado de confusão mental, agora com nistagmo multidirecional, paralisia do VI\npar craniano à esquerda e ataxia cerebelar. Assinale a alternativa CORRETA:","options":{"A":"Provável quadro de hematoma subdural crônico.","B":"O quadro pode ter agravado por se tratar de Meningite bacteriana.","C":"O agravo se deve à Síndrome de Wernicke, decorrente da deficiência de tiamina.","D":"É quadro típico de demência alcoólica.","E":"A causa do agravo pode ser devida à mielinóllise pontina central."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-81981","number":"81981","sourceNumber":"81981","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual a complicação do paracetamol em altas doses em lactentes?","options":{"A":"Doença de Kawasaki.","B":"Encefalopatia hepática de Reye.","C":"Lesão renal grave.","D":"Choque hipovolêmico.","E":"Insuficiência hepática fulminante."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-61585","number":"61585","sourceNumber":"61585","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher de 60 anos evolui com astenia e icterícia há 3 semanas. Há anos que ela\nsabe ter discreta alteração dos testes de lesão hepática, porém sem investigação diagnóstica. Ao\nexame físico, evidencia-se um bom estado geral, icterícia 2+/4, múltiplas telangiectasias e\nesplenomegalia leve. Exames laboratoriais: ALT = 1.206 U/L (42); bilirrubina total = 4,2 mg/dl;\nbilirrubina direta = 2,6; TAP = 65%; plaquetas = 83.000/L e aumento de gamaglobulina. Fosfatase\nalcalina, saturação de ferro, HBsAG, anti-HCV e anti-HAV eram negativos ou normais.\n\nUltrassonografia mostrou alterações arquiteturais hepáticas compatíveis com hepatopatia crônica e\nleve esplenomegalia, sem ascite. Qual dos seguintes é o mais CORRETO?","options":{"A":"O anticorpo antinúcleo (FAN) deve estar positivo.","B":"O nível de ceruloplasmina deve ser determinado.","C":"A paciente deve ser esplenectomizada para diagnóstico e tratamento.","D":"Esse achado clínico é compatível com hepatite aguda alcoólica.","E":"Colangiorressonância deve ser realizada para investigar a icterícia."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-284565","number":"284565","sourceNumber":"284565","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 56 anos de idade, dá entrada no pronto-socorro com quadro de aumento do\nvolume abdominal, acompanhado de dor. Relata etilismo de destilados diariamente, há muitos\nanos. Não faz uso de medicações. Ao exame físico, apresenta-se em regular estado geral,\nlentificado, com asterixis, ictérico 2+/4, com PA: 110 x 70 mmHg, T: 37,8ºC, FC: 90 bpm. Presença\nde telangiectasias em tronco, rarefação de pelos e ginecomastia. Ausculta sem alterações. Abdome\ngloboso, com piparote presente e dor à palpação difusa. Em relação ao quadro clínico, é\nCORRETO afirmar:","options":{"A":"A presença de ? 250 polimorfonucleares por mm³ no líquido ascítico indica o diagnóstico de\nbacterascite.","B":"A ascite neutrofílica só deve ser tratada como peritonite bacteriana espontânea na presença de\nfebre.","C":"A cultura do líquido ascítico positiva, isoladamente, exige o tratamento como peritonite\nbacteriana espontânea.","D":"O diagnóstico de peritonite bacteriana espontânea exige a positividade da cultura do líquido\nascítico."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-284566","number":"284566","sourceNumber":"284566","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 56 anos de idade, dá entrada no Pronto Socorro com quadro de aumento do\nvolume abdominal, acompanhado de dor. Relata etilismo de destilados diariamente, há muitos\nanos. Não faz uso de medicações. Ao exame físico, apresenta-se em regular estado geral,\nlentificado, com asterix, ictérico 2+/4, com PA: 110x70mmHg, T: 37,8ºC, FC: 90bpm. Presença de\ntelangiectasias em tronco, rarefação de pelos e ginecomastia. Ausculta sem alterações. Abdome\ngloboso, com piparote presente e dor à palpação difusa. Em relação aos achados do exame físico,\né correto afirmar.","options":{"A":"A presença de telangiectasias indica o aumento da pressão na veia porta acima de 10mmHg.","B":"A ginecomastia é decorrente do hipoandrogenismo associado a hiperestrogenismo.","C":"A manobra do piparote é a mais sensível para avaliar se o paciente apresenta ascite.","D":"A graduação da icterícia em cruzes tem uma boa acurácia em definir a faixa de nível sérico das\nbilirrubinas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-284567","number":"284567","sourceNumber":"284567","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 56 anos de idade, dá entrada no Pronto Socorro com quadro de aumento do\nvolume abdominal, acompanhado de dor. Relata etilismo de destilados diariamente, há muitos\nanos. Não faz uso de medicações. Ao exame físico, apresenta-se em regular estado geral,\nlentificado, com asterix, ictérico 2+/4, com PA: 110x70mmHg, T: 37,8ºC, FC: 90bpm. Presença de\ntelangiectasias em tronco, rarefação de pelos e ginecomastia. Ausculta sem alterações. Abdome\ngloboso, com piparote presente e dor à palpação difusa. Considerando a hipótese diagnóstica\nprincipal, indique o item que deve constar na prescrição desse paciente.","options":{"A":"Espironolactona via oral.","B":"Furosemida intravenosa.","C":"Albumina intravenosa.","D":"Vancomicina intravenosa."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-62846","number":"62846","sourceNumber":"62846","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A lesão hepática causada pelo excesso de vitamina A é:","options":{"A":"esteato-hepatite.","B":"síndrome colestática.","C":"doença veno-oclusiva.","D":"fibrose.","E":"hemangioma."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-62854","number":"62854","sourceNumber":"62854","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, com quadro de astenia e prurido há um\nmês. Nega icterícia. Avaliação laboratorial\nevidenciou elevação de fosfatase alcalina (quatro vezes\nacima do valor normal) e hipercolesterolemia. A principal suspeita diagnóstica é de:","options":{"A":"Cirrose biliar.","B":"Hemocromatose.","C":"Hepatite autoimune.","D":"Esteato-hepatite não alcoólica.","E":"Doença de Wilson."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-62794","number":"62794","sourceNumber":"62794","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, com quadro de astenia e prurido há um\nmês. Nega icterícia. Avaliação laboratorial\nevidenciou elevação de fosfatase alcalina (quatro vezes\nacima do valor normal) e hipercolesterolemia. A melhor estratégia diagnóstica é verificar:","options":{"A":"Saturação de transferrina.","B":"Anticorpo antimitocôndria.","C":"Ultrassonografia do fígado.","D":"Ceruloplasmina sérica.","E":"Anticorpo antinúcleo."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-62839","number":"62839","sourceNumber":"62839","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente etilista crônico, ictérico, admitido em unidade hospitalar com quadro de dor\nabdominal intensa. Realizado TC de abdome, que não evidenciou alterações. Lipase normal e\nsangue oculto nas fezes negativo. Hemograma com anemia macrocítica e colesterol elevado. A\nprincipal suspeita diagnóstica é de:","options":{"A":"Pancreatite aguda.","B":"Úlcera péptica.","C":"Anemia megaloblástica.","D":"Anemia sideroblástica.","E":"Síndrome de Zieve."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-49279","number":"49279","sourceNumber":"49279","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher, 45 anos de idade, assintomática, em consulta de rotina, apresenta-se com IMC:\n30, PA: 130 x 80 mmHg e circunferência abdominal: 100 cm. Exame de abdome: fígado a 4 cm do\nrebordo costal direito. Nega etilismo. Traz glicemia: 108 mg/dl e ultrassonografia de abdome\nsuperior, que mostra esteatose hepática. A melhor forma de laboratorialmente avaliar o risco\nhepático dessa paciente é através das dosagens de:","options":{"A":"gamaglutamiltransferase e índice de homeostase de glicose.","B":"aminotransferases e índice de homeostase de glicose.","C":"ferro sérico, ferritina e índice de saturação de transferrina.","D":"Anticorpo anti-HBc, alfafetoproteína e índice MELD.","E":"gamaglutamiltransferase e índice de saturação de transferrina."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-49400","number":"49400","sourceNumber":"49400","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente recentemente submetida a uma colecistectomia videolaparoscópica por\nsuspeita clínica de colecistite aguda litiásica e com resultado do laudo anatomopatológico da\nvesícula biliar de adenocarcinoma, invadindo até a camada muscular. A paciente evoluiu com\nbilioma no pós-operatório. O bilioma foi tratado com sucesso. Os exames de imagem não\ndemonstraram doença a distância ou linfonodal. Paciente em performance status 80% de\nKarnofsky. O tratamento, conforme o estadiamento demonstrado, é:","options":{"A":"Hepatectomia direita.","B":"Hepatectomia esquerda.","C":"Bissegmentectomia 4b e 5 + linfadenectomia dos níveis 8 e 12.","D":"Hepatectomia direita + linfadenectomia dos níveis 8 e 12.","E":"Trissegmentectomia direita + linfadenectomia dos níveis 8 e 12."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-49434","number":"49434","sourceNumber":"49434","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, recentemente submetida a uma colecistectomia videolaparoscópica por\nsuspeita clínica de colecistite aguda\nlitiásica e com resultado do laudo anatomopatológico da\nvesícula biliar de adenocarcinoma, invadindo até a camada muscular. A paciente evoluiu com\nbilioma no pós-operatório. A paciente cursou com progressão da doença oncológica em atividade,\nresultando no aparecimento de icterícia obstrutiva e obstrução comprovada da via biliar\n\nextra-hepática na bifurcação dos ductos hepáticos à colangiorressonância, ascite e sintomas de\noclusão intestinal. Performance status, ECOG:3. A conduta mais correta, nesse caso, é:","options":{"A":"Descompressão biliar por CPRE, sondagem nasogástrica com quimioterapia paliativa.","B":"Descompressão biliar transparieto-hepática, sondagem nasogástrica e quimioterapia paliativa.","C":"Descompressão biliar por CPRE, gastrostomia paliativa, quimioterapia paliativa.","D":"Gastrodudenopancreatectomia cefálica e quimioterapia adjuvante.","E":"Trissegmentectomia direita, linfadenectomia dos níveis 8 e 12 e quimioterapia adjuvante."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-18070","number":"18070","sourceNumber":"18070","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente hepatopata, com bilirrubina no soro de 1,8 mg/100 ml, albulmina 3,6 g/100 ml,\nSNC normal, sem ascite, com boa nutrição. A classificação de Child-Pugh, de risco pré-operatório:","options":{"A":"A.","B":"B.","C":"C.","D":"D.","E":"E."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-281880","number":"281880","sourceNumber":"281880","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite quilosa corresponde a uma coleção de linfa na cavidade peritoneal e pode\nresultar de vários fatores etiológicos. Em adultos, a causa mais comum de ascite quilosa é um\ntumor intra-abdominal produzindo obstrução dos canais linfáticos na base do mesentério ou no\nretroperitônio. A neoplasia mais comum associada à ascite quilosa é:","options":{"A":"Adenocarcinoma de próstata.","B":"Linfoma.","C":"Adenocarcinoma colorretal.","D":"Rabdomiossarcoma."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-134774","number":"134774","sourceNumber":"134774","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Rodrigo, 12 anos, com história de um episódio de icterícia há 6 meses, apresenta dor\nabdominal. Há aumento sérico de fosfatase alcalina e de gama-GT. Demais provas de função\nhepática normais. A ultrassonografia abdominal mostra massa cística no hilo hepático. Esse quadro\nsugere:","options":{"A":"Cisto de colédoco.","B":"Doença de Alagille.","C":"Pseudocisto de pâncreas.","D":"Deficiência de alfa-1-antitripsina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-321287","number":"321287","sourceNumber":"321287","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 53 anos está hospitalizada devido a quadro de pancreatite aguda biliar\nmoderada. Está no 25° dia de internamento,\nhouve regressão do quadro da pancreatite e uma\ntomografia de controle foi solicitada para planejar a colecistectomia. Achados: pâncreas aumentado\nde tamanho, edema da gordura peripancreática e sinais de trombo em veia esplênica. Qual das\nseguintes complicações está associada a este achado?","options":{"A":"Embolia esplênica.","B":"Isquemia do figado.","C":"Hemorragia digestiva.","D":"Trombose mesentérica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-321305","number":"321305","sourceNumber":"321305","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 45 anos, etilista com consumo diário de cerca 0,5 L de cachaça há\n15 anos, procurou emergência por hematêmese\nvolumosa há 2 horas. Ao exame, PA 80 x 60\nmmHg, FC 112 bpm, estado geral ruim, alerta, ictérico 1+ em 4, com presença de ginecomastia e\ntelangiectasias em tórax e ascite. Diante da apresentação, além de hidratação, assinale a conduta\nmais adequada no momento.","options":{"A":"Endoscopia digestiva alta.","B":"Inibidor de bomba de prótons e betabloqueadores.","C":"Passagem de balão esofágico devido sangramento massivo.","D":"Inibidor de bomba de prótons, análogo da somatostatina e antibioticoprofilaxia."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-292820","number":"292820","sourceNumber":"292820","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 45 anos, dá entrada na emergência com hematêmese volumosa,\ninédita, associada à lipotimia. O mesmo\nencontra-se em acompanhamento por cirrose de etiologia\nalcoólica e coronariopatia, mas não vem em uso de medicações. A equipe de plantão iniciou\nressuscitação volêmica e foi realizada endoscopia que mostrou varizes de médio calibre\nsangrantes. Qual das opções abaixo descreve a medida mais adequada a ser realizada nesse\nmomento?","options":{"A":"Realizar escleroterapia e prescrever carvedilol.","B":"Realizar ligadura de varizes e associar octreotide.","C":"Iniciar betabloqueador e administrar somatostatina.","D":"Administrar plasma fresco congelado e terlipressina."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-259703","number":"259703","sourceNumber":"259703","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de 57 anos, portador de cirrose hepática por vírus C,\naguardando transplante de fígado, foi transferido a um serviço de emergência de hospital terciário\ncom quadro de hematêmese volumosa com instabilidade hemodinâmica. Realizou endoscopia\ndigestiva alta com ligadura elástica de varizes de esôfago, com bom resultado imediato, e ficou em\nuso de terlipressina, no entanto, voltou a sangrar em 24 horas, sem sucesso em parar o\nsangramento na segunda endoscopia. Qual a melhor opção terapêutica?","options":{"A":"Shunt cirúrgico portocava.","B":"Uso do balão de Sengstaken-Blakemore.","C":"Shunt parcial esplenorenal seletivo distal.","D":"Shunt transjugular intra-hepático portossistêmico."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-259723","number":"259723","sourceNumber":"259723","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 74 anos, portador de cirrose por vírus B, comparece à consulta de rotina no\nserviço de transplante hepático. Familiar relata que o paciente não evacua há 3 dias. Desde ontem\nencontra-se confuso, sonolento durante o dia e insone à noite, e apresentando episódios\nintermitentes de agitação psicomotora. Nega febre, dor abdominal ou queixas urinárias. Ao exame:\nafebril, pulso cheio, PA 130 x 70 mmHg, palidez cutâneo-mucosa 1+/4+, icterícia 2+/4+, auscultas\ncardíaca e pulmonar normais, abdome ascítico e indolor. Flapping presente. Ausência de lesões\ncutâneas. O que está recomendado no tratamento inicial da provável causa básica do quadro\ndescrito?","options":{"A":"Lactulose.","B":"Risperidona.","C":"Clonazepam.","D":"Norfloxacino."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-234033","number":"234033","sourceNumber":"234033","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, 56 anos, masculino, etilista importante, há 6 meses vem apresentando\naumento do volume abdominal e edema de membros\ninferiores. Procurou emergência por ter\nevoluído com 2 episódios de hematêmese nas últimas 12 horas, além de melena. O paciente\nencontra-se estável hemodinamicamente e exames de urgência mostram Hb = 9,8 mg/dl (VR:\n13?16). A endoscopia revela varizes esofágicas de médio calibre com sangramento ativo.\n\nLEGENDA: VR: Valor de Referência. Qual a conduta mais indicada, dentre as opções abaixo, para\neste cenário clínico?","options":{"A":"Realizar ligadura de varizes e administrar somatostatina.","B":"Administrar octreotide e prescrever omeprazol por via oral.","C":"Prescrever terlipressina e transfundir concentrado de hemácias.","D":"Iniciar antibioticoterapia e administrar omeprazol em infusão contínua."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-199745","number":"199745","sourceNumber":"199745","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher, 42 anos, admitida na emergência com quadro de aumento do volume\nabdominal e febre há cerca de 3 dias.\nAssociado a este quadro, as fezes apresentam cor de ?borra\nde café? há 4 dias. Refere que há 2 dias a evacuação está normal. Portadora de ''problema no\nfígado'', em uso de prednisona 5 mg/dl. Ao exame físico, observa-se icterícia (++/4+) e hipocorada\n(+/4+). Pressão arterial e pulsos normais, abdome globoso, doloroso difusamente à palpação\nprofunda, principalmente à descompressão, sinal da macicez móvel positiva, piparote negativo.\n\nQual a medida inicial mais adequada para a paciente?","options":{"A":"Laparoscopia, pelo risco de abdome agudo.","B":"Antibioticoterapia empírica, pelo uso de corticoide.","C":"Ressuscitação volêmica, pelo quadro de hemorragia digestiva alta.","D":"Punção de líquido ascítico, pelo risco de peritonite bacteriana espontânea."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-81263","number":"81263","sourceNumber":"81263","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 25 anos está em tratamento para acne com um retinoide (isotretinoína).\nRelata atividade sexual com 6 parceiros nos\núltimos 6 meses, sem preservativos. Não tem\nquaisquer sintomas. Ao exame físico apresenta ? além de acne de face e tronco ? telangiectasias\nesparsas, fígado palpável 3 cm abaixo do rebordo costal e discreta icterícia. Apresenta os\nseguintes exames: TGO = 950 U/L (normal até 40 U/L); TGP = 1.100 U/L (normal até 30 U/L);\nfosfatase alcalina = 80 (normal até 140 U/L); gamaglutamiltransferase = 30 (normal < 36 U/L);\nproteína total = 10 g/dl; albumina = 3,5 g/dl; alfa-1-globulina = 0,3 g/dl; alfa-2-globulina = 0,6\ng/dl;\nbetaglobulina = 1,2 g/dl; gamaglobulina = 4,4 g/dl (normal até 1,6 g/dl); fator antinuclear positivo\n1:320 (padrão pontilhado fino); anti-Sm, anti-Ro, anti-DNA, anti-La, antimúsculo liso negativos;\nbilirrubina total = 2,5 mg/dl (normal até 1,2 mg/dl); bilirrubina direta = 1,8 mg/dl; anti-HCV e\nRIBA\n(Recombinant Immunoblot Assay) para HCV positivos; PCR para detecção de HCV negativo.\n\nHBsAG e anti-HBc total negativos. Após isso, foi solicitada biópsia hepática que evidenciou hepatite\nde interface. Qual o diagnóstico dessa paciente?","options":{"A":"Hepatite autoimune.","B":"Hepatite medicamentosa.","C":"Hepatite crônica por vírus C.","D":"Lúpus eritematoso sistêmico."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-65757","number":"65757","sourceNumber":"65757","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 54 anos procura ambulatório de cirurgia geral com quadro de dor abdominal\nno quadrante superior direito, anorexia, náuseas,\nletargia e perda de peso. A TC revela nódulo de 4\ncm de diâmetro, localizado no segmento III do fígado, hipervascularizado, com realce na fase\narterial e clareamento na fase portal. Qual o diagnóstico mais provável e o tratamento ideal para\neste caso?","options":{"A":"Hepatocarcinoma e ablação por radiofrequência.","B":"Hepatocarcinoma e transplante hepático.","C":"Hepatocarcinoma e hepatectomia direita.","D":"Adenoma e tratamento conservador.","E":"Adenoma e hepatectomia esquerda."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-51180","number":"51180","sourceNumber":"51180","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 35 anos, com hemocromatose hereditária há 8 anos (controlada com\nsangrias), procura atendimento por dor nos\njoelhos. Refere que a dor iniciou-se há cerca de 1 ano,\ncom piora após atividade física, alternando com períodos de remissão de semanas. Há 3 meses, a\ndor adquiriu caráter contínuo, sendo aliviada com repouso, o que tem prejudicado as atividades\ndiárias do paciente. Exame físico: joelhos moderadamente aquecidos, com leve perda da amplitude\nde movimento e crepitações à mobilização passiva. Qual terapêutica farmacológica deve ser\nprimeiramente iniciada nesta paciente?","options":{"A":"Ibuprofeno.","B":"Colchicina.","C":"Metilprednisolona.","D":"Condroitina/glicosamina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-7298","number":"7298","sourceNumber":"7298","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente de 55 anos apresenta prurido generalizado, principalmente nas regiões\nplantar e palmar há dois anos, há um ano, notou xantelasma bilateralmente. Durante exames\nlaboratoriais, a positividade de anticorpos antimitocondriais favorece a hipótese de:","options":{"A":"hepatite crônica persistente.","B":"amiloidose hepática.","C":"cirrose biliar primária.","D":"carcinoma hepático.","E":"N.R.A."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-8862","number":"8862","sourceNumber":"8862","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quais dos exames abaixo são mais indicados para avaliar função hepática?","options":{"A":"Aspartato aminotransferase e alanina aminotransferase, ALT.","B":"Fosfatase alcalina e albumina.","C":"Tempo de protrombina e aspartato aminotransferase.","D":"Tempo parcial de tromboplastina e albumina.","E":"Leucina aminopeptidase e alanina aminotransferase."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-17826","number":"17826","sourceNumber":"17826","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente é portador de icterícia obstrutiva de longa evolução. Apresenta tempo de\nprotrombina bastante alargado (INR = 3) e que não melhora após reposição de vitamina K\nintramuscular por período de 3 dias. Assinale a alternativa correta.","options":{"A":"Paciente deverá ter administração de vitamina K IV para reverter coagulopatia","B":"Paciente deverá repor fatores de coagulação IX e X, pois estes não dependem de vitamina K,\natravés da administração de crioprecipitado.","C":"Paciente apresenta provável disfunção hepática (cirrose biliar secundária) e a coagulação só\nserá normalizada com a administração de plasma fresco.","D":"A reposição de vitamina K deverá ser mais prolongada pela longa evolução da icterícia.","E":"Paciente é provavelmente portador de Doença de von Willebrand."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-349737","number":"349737","sourceNumber":"349737","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 46 anos, hipertenso e etilista, comparece à emergência médica após\nhematêmese e confusão mental aguda.\nApresenta-se, ao exame físico, ictérico, confuso,\ndesorientado, sarcopênico e hipotenso. Após estabilização clínica inicial, foi submetido a exames\nlaboratoriais que evidenciaram: INR 3.2; Albumina 1.8 g/dL; Bilirrubinas totais 9.5 mg/dL e\nCreatinina de 4.2 mg/dL. Assinale a alternativa que NÃO contribui, dentro do caso apresentado,\npara a classificação de Child-Pugh do paciente.","options":{"A":"INR.","B":"Albumina.","C":"Bilirrubinas.","D":"Creatinina.","E":"Grau de Encefalopatia."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-365616","number":"365616","sourceNumber":"365616","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 45 anos de idade, portador de cirrose hepática por causa da hepatite C\ncrônica, foi submetido a avaliação multidisciplinar, indicado como candidato a transplante hepático\ne inserido na lista de espera por um órgão compatível. Na admissão, os sinais vitais apresentavam\nPA = 120 mmHg x 80 mmHg, FC = 75 bpm, FR = 19 irpm e temperatura = 36,8 °C. Ele realizou\nexames laboratoriais, os quais revelaram os seguintes resultados: bilirrubina total = 2,5 mg/dL,\nalbumina = 3,0 g/dL, INR = 2,2 e creatinina = 1,0 mg/dL. Tendo em vista o caso clínico\napresentado, assinale a alternativa que corresponde à principal indicação para transplante hepático\nem pacientes com cirrose hepática.","options":{"A":"Diagnóstico de carcinoma hepatocelular","B":"Ascite não responsiva ao tratamento médico","C":"Peritonite bacteriana espontânea recorrente","D":"Insuficiência cardíaca refratária"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-365633","number":"365633","sourceNumber":"365633","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 52 anos de idade, etilista diário há 23 anos, procurou o pronto-socorro\ncom queixa de aumento importante do volume\nabdominal e discreto edema em membros inferiores.\nAo exame físico, observou-se sinal do piparote positivo, sendo realizada paracentese e exames\nlaboratoriais, com os seguintes resultados: plaquetopenia = 100 mil/mm³; albumina sérica = 2,0\ng/dL; INR = 2,1, líquido ascítico com proteína = 0,6 g/dL; celularidade com 300 cél/mm³; e 54% de\npolimorfonucleares. Tendo em vista esses resultados associados à história clínica, é correto afirmar\nque se trata de um caso de","options":{"A":"ascite por cirrose hepática.","B":"peritonite bacteriana espontânea.","C":"ascite de provável origem neoplásica.","D":"peritonite bacteriana secundária."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-349750","number":"349750","sourceNumber":"349750","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O médico de um paciente cirrótico está verificando a possibilidade de uma cirurgia\nhepática para esse paciente, porém, para isso,\nquer primeiro verificar qual seu escore Child-Pugh,\njá que este possui correlação com a sobrevida do paciente. Nesse sentido, o paciente apresenta os\nseguintes exames: bilirrubina de 2,5 mg/dL; albumina de 2,6 g/dL; tempo de protrombina de 2\nsegundos; nenhuma ascite ou encefalopatia. Diante desses resultados, qual é a classificação de\nChild-Pugh desse paciente e sua chance de sobrevida?","options":{"A":"Child-Pugh A / Sobrevida alta.","B":"Child-Pugh B / Sobrevida intermediária.","C":"Child-Pugh C / Sobrevida baixa.","D":"Child-Pugh D / Sobrevida alta.","E":"Child-Pugh C / Sobrevida intermediária."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-365634","number":"365634","sourceNumber":"365634","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 52 anos de idade, etilista diário há 23 anos, procurou o pronto-socorro\ncom queixa de aumento importante do volume\nabdominal e discreto edema em membros inferiores.\nAo exame físico, observou-se sinal do piparote positivo, sendo realizada paracentese e exames\nlaboratoriais, com os seguintes resultados: plaquetopenia = 100 mil/mm³; albumina sérica = 2,0\ng/dL; INR = 2,1, líquido ascítico com proteína = 0,6 g/dL; celularidade com 300 cél/mm³; e 54% de\npolimorfonucleares. Qual é a prescrição indicada para o referido caso clínico?","options":{"A":"Ciprofloxacino e espironolactona","B":"Espironolactona","C":"Norfloxacino e furosemida","D":"Furosemida"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274356","number":"274356","sourceNumber":"274356","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dentre os tratamentos para hipertensão porta e potenciais consequências da hepatite B\ne C / cirrose, está a chamada TIPS, um\ntipo de derivação utilizada para descompressão do sistema\nporta, sem intervenção cirúrgica, que cria um desvio entre quais das seguintes estruturas?","options":{"A":"Veia porta e artéria hepática comum.","B":"Veia gástrica e veia hepática/veia cava inferior.","C":"Veia esplênica e veia hepática.","D":"Veia renal e veia esplênica.","E":"Veia porta e veia hepática/veia cava inferior."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274357","number":"274357","sourceNumber":"274357","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação às doenças e lesões relacionadas à via biliar, assinale a alternativa\nINCORRETA.","options":{"A":"Lesão parcial, única, pequena e lateral do ducto biliar pode ser tratada com a colocação de tubo\nem T (Kehr).","B":"A cirrose é um fator de risco para o desenvolvimento da colangite esclerosante primária.","C":"O cisto de colédoco é uma condição incomum que geralmente necessita de tratamento cirúrgico.","D":"As estenoses biliares, após transplante hepático, podem ser tratadas com stents transepáticos.","E":"O colangiocarcinoma que se estende somente para o ducto intra-hepático direito é do tipo IIIA,\nconforme a classificação de Bismuth."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274361","number":"274361","sourceNumber":"274361","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 35 anos, etilista diário de 1 litro de destilado, sem outras\ncomorbidades conhecidas, foi admitido para\ninternamento devido a quadro de confusão mental,\nrebaixamento do nível de consciência e palidez, sendo todos os sintomas decorrentes de cirrose\nhepática descompensada. Sobre esse quadro, assinale a alternativa CORRETA.","options":{"A":"É indicado que o paciente seja submetido à biópsia hepática imediata para diagnóstico etiológico\nda hepatopatia.","B":"A encefalopatia hepática decorrente da cirrose hepática está relacionada com o metabolismo da\namônia.","C":"A encefalopatia hepática piora o prognóstico da doença somente quando associada a outra\ncomplicação, como ascite ou icterícia.","D":"O tratamento indicado no momento é plasmaférese.","E":"O escore de Child-Pugh é a melhor ferramenta de análise do prognóstico do paciente, porém\nnão tem utilidade na indicação do tratamento."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-261249","number":"261249","sourceNumber":"261249","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nEssa patologia não cursa com cirrose hepática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-261250","number":"261250","sourceNumber":"261250","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O\nmelhor tratamento para essa patologia é silimarina em estudos clínicos randomizados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-261251","number":"261251","sourceNumber":"261251","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nPerda de peso deve ser estimulada para essa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-250094","number":"250094","sourceNumber":"250094","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 45 anos de idade, com diagnóstico prévio de cirrose hepática,\napresenta, há três dias, febre alta, dor\nabdominal e confusão mental. Ao exame físico, observa-se\nabdome globoso, ascítico e com dor à descompressão brusca. Com base nesse caso hipotético e\nnos conceitos médicos a ele relacionados, julgue o item a seguir. A deficiência de complemento\nsérico e opsoninas nos pacientes cirróticos facilita o aparecimento da peritonite bacteriana\nespontânea.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-250095","number":"250095","sourceNumber":"250095","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 45 anos de idade, com diagnóstico prévio de cirrose hepática,\napresenta, há três dias, febre alta, dor\nabdominal e confusão mental. Ao exame físico, observa-se\nabdome globoso, ascítico e com dor à descompressão brusca. Com base nesse caso hipotético e\nnos conceitos médicos a ele relacionados, julgue o item a seguir. A presença de gradiente de\nproteína do líquido ascítico/plasmática (GASA) < 1,1 g/dl define ascite por hipertensão portal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-250096","number":"250096","sourceNumber":"250096","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 45 anos de idade, com diagnóstico prévio de cirrose hepática,\napresenta, há três dias, febre alta, dor\nabdominal e confusão mental. Ao exame físico, observa-se\nabdome globoso, ascítico e com dor à descompressão brusca. Com base nesse caso hipotético e\nnos conceitos médicos a ele relacionados, julgue o item a seguir. Os agentes etiológicos mais\ncomuns de peritonite bacteriana espontânea são as bactérias anaeróbias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-250097","number":"250097","sourceNumber":"250097","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 45 anos de idade, com diagnóstico prévio de cirrose hepática,\napresenta, há três dias, febre alta, dor\nabdominal e confusão mental. Ao exame físico, observa-se\nabdome globoso, ascítico e com dor à descompressão brusca. Com base nesse caso hipotético e\nnos conceitos médicos a ele relacionados, julgue o item a seguir. A peritonite bacteriana\nespontânea é definida pela presença de linfócitos mononucleares no líquido ascítico e no gradiente\nde albumina sérica/ascítico < 1,1.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212000","number":"212000","sourceNumber":"212000","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Após problemas domiciliares, um paciente com transtorno psiquiátrico social comparece\nao pronto-socorro, com relato de ingestão de mais de\n25 g de acetaminofeno. Ele apresenta\nnáuseas, vômitos, diarreia e dor abdominal com cinco horas de evolução. Nesse caso clínico, como\nantídoto para lesão por hepatotoxicidade, é correto:","options":{"A":"Utilizar N-acetilcisteína na dose de 140 mg/kg, seguido por 70 mg/kg a cada quatro horas até 20\nhoras.","B":"Empregar carvão vegetal ativado ou de colestiramina em razão do tempo de evolução.","C":"Estabilizar o paciente com reposição hídrica e prescrever sintomáticos.","D":"Indicar terapia maciça com cimetidina.","E":"Fazer lavagem gástrica, prescrever sintomáticos e solicitar vaga de unidade de terapia\nintensiva."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212006","number":"212006","sourceNumber":"212006","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Considere um paciente de 62 anos de idade, ex-etilista, ex-tabagista, infectado pelo\nvírus C (há 10 anos), apresentando quadro\nde cirrose não colestática, sem outras comorbidades ou\ncomplicações da doença. Esse paciente procura a médica e questiona se existe a possibilidade de\nque ele entre na lista de transplante hepático, pois ficou sabendo que um vizinho foi transplantado\ne\ncurou-se da hepatite C. Considerando esse caso clínico e os conhecimentos médicos correlatados,\na respeito das patologias do fígado, assinale a alternativa correta.","options":{"A":"A trombose da artéria hepática é considerada uma complicação precoce do transplante hepático\ne ocorre em 2% a 4% dos casos.","B":"A presença de carcinoma hepatocelular metastático é uma indicação absoluta de transplante\nhepático.","C":"A presença de hepatite viral C e de cirrose não colestática é contraindicação para transplante\nhepático.","D":"As taxas de sobrevida do paciente transplantado entre 1 ano e 5 anos após a cirurgia\npermanecem baixas (30% e 20%, respectivamente),\napesar dos avanços na técnica operatória.","E":"Ainda não existem estudos quanto à substituição do transplante hepático por transplante celular."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-154459","number":"154459","sourceNumber":"154459","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"P. P. S., 58 anos de idade, sexo masculino, etilista crônico e portador de cirrose\nhepática, é admitido com quadro de\nhematêmese moderada e melena, associado à queda do\nestado geral. Clinicamente observa-se paciente grave, ictérico +2/+4, afebril, consciente e\norientado. Ele apresenta ascite volumosa, circulação colateral tipo porta, aranhas vasculares e\nginecomastia moderada. No pronto-socorro, após as medidas iniciais, realiza-se paracentese com\ndébito de oito litros de líquido ascítico turvo encaminhado ao laboratório juntamente à amostra de\nsangue. Na análise do laboratório, obtêm-se gradiente soro-ascite albumina = 1,3 g/dl; adenosina\ndeaminase do líquido ascítico = 10 UI; contagem de polimorfonucleares = 252/mm³; no plasma,\nureia = 80 mg/dl e creatinina = 1,9 mg/dl. A cultura do líquido e do sangue não apresentam\ncrescimento de aeróbios e anaeróbios. Com relação ao caso clínico apresentado, assinale a\nalternativa CORRETA:","options":{"A":"Os achados são compatíveis com peritonite bacteriana secundária com cultura negativa, que\ndeve ser tratada como infecção\npolimicrobiana e com predomínio de Gram-negativos e anaeróbios\nentéricos. O tratamento deverá ser realizado com terapia antibiótica combinada, via endovenosa e\noral, e o antibiótico de eleição é o ciprofloxacino nas respectivas doses para as vias de\nadministração.","B":"A análise laboratorial é diagnóstica para uma ascite neutrocítica cultura-negativa e deve ser\ntratada como um caso de peritonite bacteriana\nespontânea clássica. O tratamento pode ser\nrealizado com cefotaxima 2 g de oito em oito horas por cinco dias, associadamente à albumina para\nredução da incidência de disfunção renal.","C":"Considerando apenas o volume de líquido ascítico removido, a albumina total que deve ser\ninfundida é de 24 g a 30 g. O cálculo leva em conta a dose de 8 g a 10 g de albumina por litro de\nlíquido ascítico removido após cinco litros de débito.","D":"Todos os pacientes cirróticos com peritonite bacteriana prévia devem receber profilaxia durante\nos três primeiros meses com norfloxacino 400\nmg/dia ou ciprofloxacino 750 mg/semana.","E":"O quadro clínicolaboratorial é compatível com peritonite bacteriana espontânea, devendo ser\n\nrealizada nova paracentese diagnóstica prévia ao tratamento. O antibiótico de eleição é o\nceftriaxona 1 g/dia a 2 g/dia durante cinco\ndias, e a albumina destina-se à correção por drenagem\nmaior que cinco litros do líquido ascítico."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-154340","number":"154340","sourceNumber":"154340","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A doença de Wilson é um distúrbio autossômico recessivo do metabolismo do cobre,\nprovocado, em última instância, acúmulo progressivo desse metal no organismo. Trata-se de\ndoença de incidência rara, e as manifestações clínicas incluem doenças hepática, anormalidades\nneuropsiquiátricas, doenças esqueléticas e síndrome tubular renal. Quanto a essa entidade\npatológica, assinale a alternativa correta.","options":{"A":"Os alelos do gene da doença de Wilson (ATP7A) são responsáveis pela codificação de uma\nATPase transportadora de cobre, expressa\nprincipalmente no cérebro e fígado. No fígado do\ndoente, a metalação da ceruloplamina encontra-se comprometido, refletindo baixos níveis de\nceruloplamina e de cobre sérico total. A tradução dos achados fisiopatológicos responde pela\nsobrecarga maciça de cobre no fígado e pela excreção deficiente pela bile.","B":"Embora seja técnica invasiva, a agulha percutânea de biópsia hepática para determinação\nquantitativa de cobre hepático continua a ser padrão-ouro no diagnóstico. Valores de cobre\nhepático superiores a 200 mg por grama de peso seco são diagnósticos.","C":"Na apresentação hepática, os sinais e sintomas incluem icterícia, hepatomegalia e ascite. Os\nefeitos endócrinos secundários à doença hepática podem incluir puberdade prococe ou\nhipermenorreia, além de ginecomastia e de aranhas vasculares, como ocorre nos casos de cirrose\nhepática.","D":"Além dos depósitos no cérebro e fígado, o olho é sítio primário de deposição do cobre na\ndoença de Wilson, produzindo o anel de Kayser-\nFleischer e a catarata em girassol. Esse anel\ncorresponde ao depósito de cobre na periferia das íris, sendo considerado patognomônico da\ndoença.","E":"A estratégia terapêutica com penicilina tem base na capacidade de formação de quelatos no\ncobre, não corrigindo o defeito básico de\nexcreção do cobre na bile, mas aumentando\nsignificativamente a excreção urinária de cobre. Esse mecanismo evita a sobrecarga de cobre e os\nrespectivos efeitos."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-154334","number":"154334","sourceNumber":"154334","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com dor abdominal, hiporexia e astenia comparece ao consultório para\navaliação. Ela nega doenças pregressas e relata\napenas o uso de anticoncepcional. Quanto ao\ncaso clínico apresentado, e considerando a hipótese diagnóstica de tumor hepático, é CORRETO\nafirmar que o tumor:","options":{"A":"Maligno mais comum no fígado é o hepatocarcinoma.","B":"Maligno primário do fígado mais comum é a metástase, em especial do câncer prostático.","C":"Hepático mais comum é a metástase, em especial do câncer colorretal.","D":"Hepático primário mais comum é o hepatocarcinoma, presente em até 80% da população em\ngeral.","E":"Hepático mais comum é o hemangioma, presente em até 8% da população em geral."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-152143","number":"152143","sourceNumber":"152143","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 47 anos de idade, sexo masculino, etilista de 12 latas de cerveja/dia, há 20\ndias apresenta náusea e anorexia. Ao exame físico, apresenta icterícia 1+/4+, telangiectasias,\ncirculação colateral em abdome e ascite. Os exames laboratoriais mostram hemoglobina de 11,2;\nTGO = 124; TGP = 98; albumina = 2,7; INR = 1,2; bilirrubina total = 2,2, indicando flapping.\n\nConsiderando esse caso clínico, julgue o item a seguir. Pela classificação Child-Pugh, é um\npaciente Child B.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-152148","number":"152148","sourceNumber":"152148","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 47 anos de idade, sexo masculino, etilista de 12 latas de cerveja/dia, há 20\ndias apresenta náusea e anorexia. Ao exame físico, apresenta icterícia 1+/4+, telangiectasias,\ncirculação colateral em abdome e ascite. Os exames laboratoriais mostram hemoglobina de 11,2,\nTGO = 124; TGP = 98; albumina = 2,7; INR = 1,2; bilirrubina total = 2,2, indicando flapping.\n\nConsiderando esse caso clínico, julgue o item a seguir. Pela situação apresentada, deve-se solicitar\nultrassonografia de abdome e, se tiver alterações difusas do parênquima, com veia porta superior a\n0,8 cm, pode haver indícios de hipertensão portal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-135093","number":"135093","sourceNumber":"135093","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sabendo que, de acordo com a Organização Mundial de Saúde (OMS),\naproximadamente 10% da população mundial residente\nem áreas urbanas abusa do uso de\nsubstâncias psicoativas como, por exemplo, o álcool, julgue o item a seguir, referente ao\nalcoolismo. As consequências do alcoolismo crônico incluem quadros de cirrose hepática, bem\ncomo o surgimento de varizes esofagianas e de hepatocarcinoma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-79678","number":"79678","sourceNumber":"79678","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A. J. S., 65 anos, cirrótico, histórico de diabetes tipo 2 apresentou exames de\ndiagnóstico salientando-se pancitopenia com\nmicrocitose e hipocromia, prolongamento do tempo de\nprotrombina e tromboplastina ativada, gama-GT e AST acima do limite superior da normalidade,\nácido fólico e vitamina B12 normais. É correto afirmar que se deve excluir cirrose por abuso de\nálcool","options":{"A":"pois o paciente é diabético.","B":"pois o paciente está pancitopênico.","C":"devido à presença de vitamina B12 em níveis normais.","D":"devido à AST elevada.","E":"devido ao tempo de protrombina ativada."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366225","number":"366225","sourceNumber":"366225","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nInfere-se do quadro clínico encefalopatia West Haven classificação IV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366224","number":"366224","sourceNumber":"366224","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nDepreende-se do texto classificação de Child-Pugh classe C, pois paciente pontua >10 pontos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366223","number":"366223","sourceNumber":"366223","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nO MELD (Model for End-stage Liver Disease), utilizado para deixar mais objetiva a urgência de\ntransplante hepático, é um valor numérico determinado por critérios clínicos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366221","number":"366221","sourceNumber":"366221","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nEstá indicada paracentese diagnóstica para todos os pacientes com ascite admtidos em Pronto\nAtendimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366220","number":"366220","sourceNumber":"366220","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nSe indicada paracentese para o paciente em questão espera-se um gradiente albumina soro-ascite\né esperado como maior ou igual a 1,1 g/dL.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366219","number":"366219","sourceNumber":"366219","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nEstá indicada de imediato endoscopia digestiva alta com sendo preferível terapia com ligadura\nelástica para interromper sangramento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366218","number":"366218","sourceNumber":"366218","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 54 anos de idade, trabalhador na construção civil, previamente etilista\n(consumo diário de 1 litro de cachaça por 30\nanos), apresenta história de hematêmese de grande\nmonta há aproximadamente uma hora e meia. Sabidamente hepatopata devido à cirrose de origem\nalcoólica, porém, com adesão irregular ao tratamento. O filho relata que nos últimos dias o paciente\ndemonstrava confusão mental e episódios de \"\"esquecimento\"\", ocasionalmente apático. Logo\ndepois, foi encaminhado à Sala de Emergência. No exame físico, o paciente encontra-se\ndesorientado, sonolento, com confusão mental evidente, icterícia ++/4+, extremidades frias e\númidas; mioclonias; flapping; reflexos hipoativos; abdome distendido com sinais de ascite\nmoderada; exame de toque retal com sangue em dedo de luva; frequência cardíaca de 140 bpm;\nfrequência respiratória de 30 irpm; pressão arterial 82x50 mm Hg; temperatura axilar de 36,6° C;\nglicemia capilar de 92 mg/dl; SpO2: 90% (com curva irregular no monitor). Na cateterização vesical\nde demora, a diurese é quantificada em 6 mL/kg/hora. Os exames laboratoriais mostram\nhemoglobina de 12 g/dL; hematócrito de 36%; leucograma sem alterações notáveis; TGO 90 U/L;\nTGP 45 U/L; 130 U/L; creatinina: 1,0 mg/dL; ureia 44 mg/dL; albumina: 3,5 g/dL; bilirrubina total\n3,2\nmg/dL; INR 2,1. Considerando o quadro clínico e assuntos correlatos, julgue o item que se segue.\nEm pacientes cirróticos com ascite neutrofílica está indicada cefotaxima mesmo na ausência teste\nde Gram negativo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-343399","number":"343399","sourceNumber":"343399","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A causa mais comum de hipertensão portal pré-hepática é:","options":{"A":"Síndrome de Budd-Chiari.","B":"Cirrose hepática.","C":"Trombose da veia porta.","D":"Hepatite crônica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-307100","number":"307100","sourceNumber":"307100","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente com história de hepatopatia alcoólica evoluiu com quadro de hematêmese\nvolumosa, broncoaspiração. Enquanto realizava admissão em unidade de terapia intensiva,\napresentou queda pressórica, com PA = 82 mmHg x 34 mmHg; dessaturação, SatO? = 78% com\nmáscara não reinalante = 6l/min, FC = 112 bpm e Glasgow = 8. O colega intensivista optou por\nproteção de via aérea, acesso venoso calibroso, início de antibioticoterapia, terlipressina,\nsolicitação de hemoderivados, e exames pertinentes ao caso. Quando solicitado endoscopia de\nurgência, detectaram-se grande quantidade de sangue no esôfago e varizes difusas, não\nconseguindo abordagem em primeiro tempo por dificuldade técnica. Nesse caso clínico, as\npróximas ações no tratamento são","options":{"A":"iniciar imediatamente bloqueador de bomba de prótons e propranolol.","B":"iniciar albumina endovenosa 1,5g/kg.","C":"passar sonda nasoentérica para drenar o conteúdo gástrico e antiemético.","D":"colocar um balão de Sengstaken-Blakemore (gastroesofágico) para controle de danos e\nestabilização do paciente.","E":"iniciar ressuscitação volêmica e aguardar medidas assumidas surtirem resultado."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-263343","number":"263343","sourceNumber":"263343","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher com 18 anos de idade vai ao ambulatório para levar o resultado da análise\ndo líquido ascítico, além de outros exames\nlaboratoriais. A história da paciente revela aumento\nprogressivo do volume abdominal há 2 meses, acompanhado de perda de peso (habitual = 60 kg;\natual = 51 kg) e episódios febris há 1 mês, geralmente no final da tarde, com temperatura de até 38\n\n°C. Os exames demonstram anemia ferropriva, albumina sérica = 3,4/dL (valor de referência: 3,5 a\n4,7g/dL), albumina no líquido ascítico = 2,5g/dL, leucocitúria = 35 a 40 leucócitos/campo e\nurocultura negativa. A fim de racionalizar a investigação diagnóstica, qual é o próximo exame\ncomplementar a ser solicitado?","options":{"A":"Pesquisa de BAAR na urina.","B":"Dosagem sérica de CA 19.9.","C":"Pesquisa de autoanticorpos lúpicos.","D":"Sorologia para hepatites virais B e C."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-268891","number":"268891","sourceNumber":"268891","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 60 anos de idade, hepatopata crônico secundário a etilismo,\ncompareceu à emergência com relato de febre\ne de aumento do volume abdominal há dois dias.\nNegou episódios semelhantes anteriores. Ao exame físico, apresentava-se em regular estado geral,\nictérico 1+/4, afebril, com ascite volumosa com dor difusa à palpação abdominal, PA = 100 mmHg x\n70 mmHg, FC = 112 bpm, FR = 20 irpm e SatO2 = 96%. Considerando esses achados, assinale a\nalternativa que corresponde à conduta correta.","options":{"A":"Realizar paracentese diagnóstica; caso ela apresente > 250 polimorfonucleares/mm3, o\ndiagnóstico será peritonite bacteriana espontânea, devendo ser realizado tratamento com\nparacentese de repetição.","B":"Realizar paracentese diagnóstica; caso ela apresente > 250 polimorfonucleares/mm3, o\ndiagnóstico será peritonite bacteriana espontânea, devendo ser realizado tratamento com\nfurosemida e espironolactona.","C":"Realizar paracentese diagnóstica; caso ela apresente < 250 polimorfonucleares/mm3, o\ndiagnóstico será tuberculose peritoneal, devendo ser realizado tratamento com rifampicina,\npirazinamida e isoniazida.","D":"Realizar paracentese diagnóstica; caso ela apresente > 250 polimorfonucleares/mm3, o\ndiagnóstico será peritonite bacteriana espontânea, devendo ser realizado tratamento com\nceftriaxona intravenosa.","E":"Realizar paracentese diagnóstica; caso ela apresente um transudato, o diagnóstico será de\nperitonite bacteriana espontânea, devendo ser realizado tratamento com furosemida e\nespironolactona."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-266434","number":"266434","sourceNumber":"266434","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quanto à doença gordurosa hepática não alcoólica, julgue o item seguinte. Pessoa com\nesteatose hepática pode ter alto risco de doença cardiovascular por ateromatose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-273340","number":"273340","sourceNumber":"273340","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 56 anos, portador de hepatite C há 10 anos, é levado ao Pronto\nAtendimento (PA) devido ao aumento de volume\nabdominal acompanhado de confusão mental e\nletargia com 1 semana de evolução. Fazia uso domiciliar de furosemida 80 mg há 1 ano. Realizou\nendoscopia digestiva há 1 mês, por solicitação do médico assistente, que revelou varizes\nesofágicas de grosso calibre. O paciente apresentou-se estável hemodinamicamente, pálido, com\npresença de aranhas vasculares, ginecomastia e com abdome com ascite volumosa, sendo\nrealizado paracentese propedêutica, que revelou: Celularidade: 370 leucócitos, sendo 55% de\npolimorfonucleares; gradiente soro-ascite de albumina > 1; glicose: 70 mg/dl. Considerando o caso\nclínico descrito, assinale a alternativa CORRETA:","options":{"A":"Realizar paracentese total, infundir albumina conforme a quantidade de líquido retirada, iniciar\nceftriaxona para tratamento de peritonite bacteriana espontânea e internar o paciente com\nassociação de furosemida, espironolactona e lactulose.","B":"Internar para investigação da encefalopatia e piora da ascite. Rastreio infeccioso, de hemorragia\ndigestiva e de distúrbio eletrolítico, além de suspensão inicial dos diuréticos, início de\nlactulose e\nultrassom abdominal são medidas a serem realizadas para investigação e tratamento do quadro\nclínico em questão.","C":"Rastrear a causa da descompensação da ascite, sendo, nesse caso, mais provável o mau uso\ndo diurético ou a necessidade de aumento de\ndose ou associação de fármaco.","D":"Indicar profilaxia primária para sangramento varicoso e a droga de escolha deve ser os\nbetabloqueadores, a exemplo do metoprolol."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274631","number":"274631","sourceNumber":"274631","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão portal provoca a alteração da pressão sanguínea na veia porta que\ntransporta o sangue do intestino ao fígado e suas ramificações. A alternativa que apresenta\nCORRETAMENTE os fatores que podem causar a alteração da pressão sanguínea e que\ncaracteriza a hipertensão focal é:","options":{"A":"Diminuição do volume de sangue fluindo pelos vasos e resistência aumentada ao fluxo de\nsangue pelo fígado.","B":"Aumento do volume de sangue fluindo pelos vasos e resistência diminuída ao fluxo de sangue\npelo fígado.","C":"Aumento do volume de sangue fluindo pelos vasos e resistência aumentada ao fluxo de sangue\npelo fígado.","D":"Diminuição do volume de sangue fluindo pelos vasos e resistência diminuída ao fluxo de sangue\npelo fígado."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274637","number":"274637","sourceNumber":"274637","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Nas varizes do esôfago, o sangue portal flui por intermédio de circulação colateral,\nhavendo risco de hemorragia quando o gradiente de pressão entre a veia porta e as veias\nsupra-hepáticas é:","options":{"A":"Maior do que 4 mmHg e menor do que 6 mmHg.","B":"Menor do que 6 mmHg.","C":"Maior do que 6 mmHg.","D":"Menor do que 4 mmHg."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-263388","number":"263388","sourceNumber":"263388","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente com 42 anos de idade, internada no hospital por prurido, cansaço,\nanorexia e epistaxe que foi prontamente\ntamponada, relata que tem ficado \"roxa\" com facilidade,\nmesmo após traumas muito leves. Em exame físico, a paciente apresenta icterícia e algumas\nequimoses e seus exames laboratoriais mostram aumento de fosfatase alcalina, de gama-glutamil\ntransferase, de aminotransaminases, de tempo de protrombina (TP) e da razão normalizada\ninternacional (INR). Nesse caso, qual é o tratamento indicado?","options":{"A":"Reposição de fator VIII, via endovenosa, dose única.","B":"Reposição de vitamina K, via parenteral, por 24 até 72 horas.","C":"Administração de prednisona 1 mg/kg uma vez ao dia por 72 horas.","D":"Administração de ácido tranexâmico, a cada 8 horas, por 24 a 48 horas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274648","number":"274648","sourceNumber":"274648","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O transplante pode ser a única escolha para portadores de alguma doença terminal,\nrepresentando uma alternativa terapêutica segura e eficaz. Considerando a classificação de\npotenciais doadores falecidos por morte cardiorrespiratória de órgãos e tecidos para transplantes, é\nCORRETO afirmar:","options":{"A":"Constatada a morte cerebral, é possível doar corações, pulmões e fígados.","B":"Se parada cardíaca maior que 6 horas, é possível a retirada de órgãos, em especial, os rins.","C":"Se parada cardíaca maior que 6 horas, podem ser doados apenas tecidos.","D":"Constatada a morte cerebral, é possível doar vasos, pele, ossos e tecidos."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227384","number":"227384","sourceNumber":"227384","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de sessenta e oito anos de idade, com quadro de aumento\ndo volume abdominal e edema de membros\ninferiores havia 1 semana, estava em seguimento com\nmédico cirurgião para programação cirúrgica de correção de hérnia inguinal direita. Exame de\nhemograma solicitado pelo cirurgião evidenciou plaquetopenia e tempo de protrombina alargado\n(54%). O paciente tinha antecedente de etilista diário de alto teor alcoólico por mais de 20 anos.\nEle\nnegou uso de drogas ilícitas. A ultrassonografia de abdome revelou cirrose hepática com\nhipertensão porta, esplenomegalia e ascite moderada. Procedeu-se a paracentese diagnóstica e de\nalívio associada a diuréticos. Contudo, 3 dias após esse procedimento, o paciente evoluiu com\nsonolência, flapping e lentificação verbal e motora. Considerando esse caso clínico, julgue o item a\nseguir. A ressonância magnética de crânio é um dos testes para diagnóstico de encefalopatia\nhepática nesse paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227385","number":"227385","sourceNumber":"227385","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de sessenta e oito anos de idade, com quadro de aumento\ndo volume abdominal e edema de membros\ninferiores havia 1 semana, estava em seguimento com\nmédico cirurgião para programação cirúrgica de correção de hérnia inguinal direita. Exame de\nhemograma solicitado pelo cirurgião evidenciou plaquetopenia e tempo de protombina alargado\n(54%). O paciente tinha antecedente de etilista diário de alto teor alcoólico por mais de 20 anos.\nEle\nnegou uso de drogas ilícitas. A ultrassonografia de abdome revelou cirrose hepática com\nhipertensão porta, esplenomegalia e ascite moderada. Procedeu-se a paracentese diagnóstica e de\nalívio associada a diuréticos. Contudo, 3 dias após esse procedimento, o paciente evoluiu com\nsonolência, flapping e lentificação verbal e motora. Considerando esse caso clínico, julgue o item a\nseguir. A plaquetopenia nesse paciente se deve à esplenomegalia secundária à hipertensão portal\nprovocada pela cirrose hepática.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227386","number":"227386","sourceNumber":"227386","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de sessenta e oito anos de idade, com quadro de aumento\ndo volume abdominal e edema de membros\ninferiores havia 1 semana, estava em seguimento com\nmédico cirurgião para programação cirúrgica de correção de hérnia inguinal direita. Exame de\nhemograma solicitado pelo cirurgião evidenciou plaquetopenia e tempo de protombina alargado\n(54%). O paciente tinha antecedente de etilista diário de alto teor alcoólico por mais de 20 anos.\nEle\nnegou uso de drogas ilícitas. A ultrassonografia de abdome revelou cirrose hepática com\nhipertensão porta, esplenomegalia e ascite moderada. Procedeu-se a paracentese diagnóstica e de\nalívio associada a diuréticos. Contudo, 3 dias após esse procedimento, o paciente evoluiu com\nsonolência, flapping e lentificação verbal e motora. Considerando esse caso clínico, julgue o item a\nseguir. Na cirrose hepática, a hipertensão portal é responsável por complicações como hemorragia\ndigestiva alta, ascite e encefalopatia hepática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227387","number":"227387","sourceNumber":"227387","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de sessenta e oito anos de idade, com quadro de aumento\ndo volume abdominal e edema de membros\ninferiores havia 1 semana, estava em seguimento com\nmédico cirurgião para programação cirúrgica de correção de hérnia inguinal direita. Exame de\nhemograma solicitado pelo cirurgião evidenciou plaquetopenia e tempo de protombina alargado\n(54%). O paciente tinha antecedente de etilista diário de alto teor alcoólico por mais de 20 anos.\nEle\nnegou uso de drogas ilícitas. A ultrassonografia de abdome revelou cirrose hepática com\nhipertensão porta, esplenomegalia e ascite moderada. Procedeu-se a paracentese diagnóstica e de\nalívio associada a diuréticos. Contudo, 3 dias após esse procedimento, o paciente evoluiu com\nsonolência, flapping e lentificação verbal e motora. Considerando esse caso clínico, julgue o item a\nseguir. O paciente em questão apresenta provável cirrose por álcool e encefalopatia de\n\nWernicke-Korsakoff.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-206117","number":"206117","sourceNumber":"206117","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A respeito do tratamento da ascite em pacientes cirróticos é INCORRETO afirmar:","options":{"A":"A restrição dietética de sódio razoável para maioria dos pacientes com ascite é 2 g/dia.","B":"Espironolactona (100 mg/dia) e furosemida (40 mg/dia) promoverão natriurese com manutenção\nna normocalemia.","C":"A paracentese de grande volume pode ser útil para pacientes que não responderam a restrição\nde sódio e ao tratamento diurético.","D":"A classificação da ascite por gradiente soro-ascite de albumina é baixa (<1,1 g/dl)."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183864","number":"183864","sourceNumber":"183864","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue. A\nrazão da incidência relativamente baixa de\ncirrose hepática em alcoólatras inveterados (menos de\n20%) é desconhecida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183882","number":"183882","sourceNumber":"183882","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue. A\nclassificação de Child-Pugh é um fator preditivo razoavelmente confiável de sobrevida para várias\ndoenças hepáticas e antecipa a probabilidade de complicações importantes da cirrose, como\nsangramento por varizes e peritonite bacteriana espontânea.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-175119","number":"175119","sourceNumber":"175119","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Daniela, 1 ano, apresentou febre aferida em 40 graus por 3 dias. Ao passar a febre\napresentou exantema por todo o corpo que durou\napenas um dia. Não tinha outros sintomas e nem\nsinais localizatórios. Procurou serviço médico no primeiro dia de doença e foi orientada a oferecer\nparacetamol 40 gotas a cada 3 horas durante 7 dias para o tratamento da doença, mesmo\n\nquando a febre passasse. Após 10 dias do início da febre, ela começou a apresentar irritabilidade,\nsonolência, flapping, icterícia, aumento do\nvolume abdominal e dispneia. Encontra-se em REG,\nacianótica, ictérica 4+/4, afebril, dispneica com batimento de asa de nariz, sonolenta. Aparelho\ncardiovascular sem alterações. Aparelho respiratório com MV + bilateral, diminuído nas bases com\nestertores finos difusos. Abdome distendido, muito aumentado de tamanho, moderadamente\ndoloroso difusamente, fígado a 4 cm do RCD, sinal do piparote positivo e macicez móvel dos\nflancos também positivo, RHA+. Pulsos cheios e boa perfusão periférica. Qual o diagnóstico mais\nprovável e como devo tratar essa paciente?","options":{"A":"Insuficiência hepática por citomegalovirose. Deve-se manter suporte vital com correções dos\ndistúrbios hidroeletrolíticos e\n\nadministrar ganciclovir.","B":"Insuficiência respiratória aguda por pneumonia grave. Deve-se iniciar ceftriaxone e oxacilina e\nrealizar intubação orotraqueal de\n\nurgência.","C":"Insuficiência hepática aguda por intoxicação exógena. Deve-se manter suporte vital com\ncorreções dos distúrbios\n\nhidroeletrolíticos, suspender o paracetamol e administrar N-acetilcisteína.","D":"Insuficiência respiratória crônica por fibrose cística. Deve-se realizar intubação de urgência e\nadministrar cefepime associada a\n\nvancomicina."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-154515","number":"154515","sourceNumber":"154515","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A classificação de Child-Turcotte-Pugh é utilizada na avaliação de gravidade das\ndoenças hepáticas, em especial nos portadores de\ncirrose. Qual dos seguintes parâmetros não é\ncontemplado nesta classificação?","options":{"A":"Presença de ascite.","B":"Concentração sérica de bilirrubinas.","C":"Concentração sérica de alanina aminotransferase (TGP).","D":"Tempo de protrombina.","E":"Presença de encefalopatia."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158058","number":"158058","sourceNumber":"158058","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No que se refere à síndrome de Budd-Chiari, assinale a alternativa CORRETA.","options":{"A":"É uma forma comum de doença hepática com hipertensão portal secundária a trombose das\nveias hepáticas.","B":"A icterícia é o sintoma mais comum dessa doença.","C":"Sintomas de dor abdominal e ascite são incomuns nessa síndrome.","D":"A biópsia é de fundamental importância na decisão do tratamento.","E":"A presença de cirrose contraindica transplante hepático."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158026","number":"158026","sourceNumber":"158026","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No que diz respeito a peritonite bacteriana espontânea, assinale a alternativa\nCORRETA.","options":{"A":"O diagnóstico demonstra mais de 450 neurófilos/mm³ na análise do líquido de ascite do paciente\ncom sintomas clínico sugestivos.","B":"Os germes mais comumente isolados são anaeróbios da flora entérica.","C":"É uma patologia com baixa taxa de mortalidade.","D":"Recomenda-se profilaxia para cirróticos que apresentam mais de três episódios de hemorragia\ndigestiva alta.","E":"No caso de uma suspeita clínica, antibióticos de amplo espectro, como as cefalosporinas de\nterceira geração, devem ser iniciados imediatamente."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-111301","number":"111301","sourceNumber":"111301","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Considere um paciente de 38 anos de idade, sexo masculino, há trinta dias com\nquadro de prurido generalizado, fadiga,\ndesconforto abdominal no quadrante superior direito e\nperda ponderal. Os exames laboratoriais mostraram elevação dos níveis séricos de fosfatase\nalcalina, gama glutamiltransferase e, em menor escala, das aminotransferases. Os valores das\nbilirrubinas séricas eram normais. A ecografia hepática não mostrou anormalidades. A\ncolangioressonância mostrou estreitamentos e irregularidades em vários pontos da via biliar, com\naspecto de ?colar de contas?. Com base na situação descrita, assinale a alternativa que apresenta\no diagnóstico correto nesse caso:","options":{"A":"Cirrose biliar primária.","B":"Colangiocarcinoma.","C":"Hepatite autoimune.","D":"Cirrose hepática.","E":"Colangite esclerosante primária."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-80738","number":"80738","sourceNumber":"80738","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Para avaliar a ingestão de álcool e a função renal, os melhores marcadores bioquímicos\nsão, respectivamente:","options":{"A":"Gama-Glutamil-Transpetidase (GGT) e creatinina.","B":"Fosfatase alcalina e ureia.","C":"TGO e creatinina.","D":"TGP e ureia.","E":"Fosfatase ácida e creatinina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-75553","number":"75553","sourceNumber":"75553","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Rapaz com 15 anos de idade, portador de cirrose biliar primária, com classificação\nMELD igual a 32, encontra-se na fila de\ntransplantes do Sistema Único de Saúde (SUS). Seu pai,\ncom 40 anos de idade, saudável, deseja antecipar o transplante. A orientação adequada para essa\nsituação é:","options":{"A":"não há possibilidade de acelerar o transplante, pois o paciente é menor de idade e tem uma\navaliação de menor gravidade clínica.","B":"o transplante somente poderá ser antecipado se houver um doador com morte cerebral\ncomprovada e consentimento da família.","C":"o transplante poderá ser acelerado, pois o quadro clínico do paciente é grave e a doação\nintervivos pelo pai é consentida.","D":"em hipótese alguma o transplante poderá ser antecipado, pois, para a fila do SUS, os critérios\nsão bem definidos e éticos.","E":"o transplante poderá ser antecipado somente com doador falecido HLA idêntico ou\nsemi-idêntico."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-75517","number":"75517","sourceNumber":"75517","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem com 40 anos de idade, portador de cirrose alcoólica, encontra-se em avaliação\npara transplante hepático. Relata abstinência de\nálcool há dois anos. Há sete dias apresentou\nhematêmese e ascite moderada. Foi submetido à endoscopia digestiva com ligadura elástica de\nvarizes de esôfago. No momento encontra-se bem, hemodinamicamente estável, sem sinais de\nsangramento. A conduta CORRETA a seguir é:","options":{"A":"Cancelar a alta, listar o paciente para transplante\nhepático e mantê-lo internado até realizar o\ntransplante, antes que ocorra outro sangramento e\nóbito.","B":"Cancelar a alta, até ele ter acompanhamento por\n\nassistente social para avaliar se ele não está ingerindo bebida alcoólica, prescrever antiemético,\ninibidor de bomba de prótons e diazepam.","C":"Suspender a avaliação para transplante hepático por provável ingestão de bebida alcoólica.\n\nSolicitar\n\navaliação de psiquiatra e assistente social, prescrever propranolol, inibidor de bomba de prótons e\nantibiótico profilático.","D":"Informar aos familiares e ao paciente que cirrose alcoólica não é uma indicação para transplante\nhepático, e que o melhor tratamento para\nele é o uso correto de propranolol, inibidor de bomba de\nprótons e o antibiótico profilático.","E":"Alta hospitalar com orientação aos familiares e\n\npaciente, prescrever propranolol, inibidor de bomba de prótons, antibiótico profilático, diuréticos,\nagendar nova endoscopia em 6 meses e manter avaliação para transplante hepático."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-368177","number":"368177","sourceNumber":"368177","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quanto ao papel da inflamação sistêmica no desenvolvimento da síndrome\nhepatorrenal, assinale a alternativa correta.","options":{"A":"Na cirrose, as citocinas estão elevadas, mas diminuem com a progressão da doença.","B":"A principal causa da inflamação sistêmica em pacientes cirróticos com hipertensão porta é a\ntranslocação bacteriana.","C":"A translocação bacteriana ativa os linfócitos que liberam citocinas para combater as bactérias\ncirculantes.","D":"Mesmo na vigência de infecção, a síndrome hepatorrenal só pode ocorrer com uma disfunção\nhemodinâmica grave."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-354081","number":"354081","sourceNumber":"354081","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 56 anos de idade, com cirrose hepática secundária à hepatite autoimune, é\nhospitalizada com história de dor abdominal, diarreia e febre não aferida há 3 dias. Medicações de\nuso domiciliar incluem: azatioprina 100 mg/dia, espironolactona 100 mg/dia, furosemida 40 mg/dia e\npropranol 40 mg/dia. Ao exame físico: apresenta ascite moderada, flapping, temperatura: 38,5oC,\nFC: 96 bpm, pressão arterial 98/60 mmhg. Resultado de exames laboratoriais revelam HB: 11g/dl\n(VCM: 89 / HCM: 27); contagem de leucócitos: 12.400/?L sem desvio; plaquetas: 104.000/?L; CR: 2\nmg/dl; UR: 85 mg/dl; albumina 2,6 mg/dl; bilirrubina total: 3,5 mg/dl e INR: 2,8. Levando-se em\nconta o quadro clínico da paciente, qual é a causa mais provável da descompensação e a conduta\ninicial?","options":{"A":"Síndrome hepatorrenal ? manter diuréticos e iniciar antibioticoterapia empírica.","B":"Peritonite bacterina espontânea ? iniciar antibioticoterapia empírica e administrar plasma fresco\npara realizar paracentese quando INR<1,5.","C":"Síndrome hepatorrenal ? iniciar infusão de albumina e realizar paracentese apenas quando INR\nestiver <1,5.","D":"Peritonite bacteriana espontânea ? iniciar antibioticoterapia empírica e realizar paracentese\nindependente do INR.","E":"Peritonite bacteriana espontânea - realizar infusão de albumina e realizar paracentese após\ninfusão de plasma para normalização do INR."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-354082","number":"354082","sourceNumber":"354082","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 72 anos, com cirrose hepática de etiologia alcoólica, abstinente há\n1 ano, é admitido no hospital pela terceira\nvez no mês por quadro de ascite tensa. Em cada\nadmissão prévia foi submetido à paracenteses de alívio com remoção de 2 e 3 litros de fluido. Ele\nrefere estar seguindo uma dieta restrita de sódio (2g/dia) e tomando 160 mg de furosemida e 400\nmg de espironolactona ao dia. A concentração urinária de sódio é baixa, comprovando sua\nobediência à dieta com baixo teor de sódio. O sódio e o potássio séricos são de 125 mEq/L e 4,2\nmEq/L, respectivamente. Qual é a conduta inicial mais apropriada no tratamento da ascite deste\npaciente?","options":{"A":"administrar furosemida venosa.","B":"remover todo líquido ascítico possível e iniciar reposição intravenosa de albumina.","C":"remover todo líquido ascítico que for possível e adicionar amilorida à sua medicação.","D":"remover no máximo 5l de líquido ascítico, não fazer reposição de albumina e aumentar a dose\nde ambos os diuréticos.","E":"remover todo líquido ascítico possível, fazer reposição de albumina e fazer furosemida venosa."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-337618","number":"337618","sourceNumber":"337618","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente em fila de transplante hepático cujo escore prognóstico utilizado para avaliar\ngravidade de doença hepática é o Model for End Stage Liver Disease (MELD): SIGLAS: RNI =\nRAZÃO NORMALIZADA INTERNACIONAL, ALT = ALANINA AMINO TRANSFERASE; Nesse\n\ncontexto, é CORRETO afirmar que os critérios de base do MELD são:","options":{"A":"Bilirrubina sérica, creatinina sérica e o RNI.","B":"Bilirrubina sérica, RNI e albumina sérica.","C":"Bilirrubina sérica, fosfatase alcalina, ureia sérica e o INR.","D":"Fosfatase alcalina, ALT, albumina e o INR."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-334723","number":"334723","sourceNumber":"334723","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A análise do líquido ascitico é uma propedêutica importante na investigação da ascite e\nfoi realizada em três pacientes, obtendo-se os resultados abaixo. Qual o diagnóstico mais provável\ndos pacientes 1, 2 e 3 respectivamente?","options":{"A":"Insuficiência cardíaca congestiva, cirrose hepática e tuberculose peritoneal.","B":"Hipotireoidismo, insuficiência cardíaca congestiva e hipertensão portal esquistosomótica.","C":"Cirrose hepática, síndrome nefrótica, ascite pancreática.","D":"Cirrose hepática, carcinomatose peritoneal, insuficiência cardíaca congestiva."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/334723.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-346859","number":"346859","sourceNumber":"346859","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"É CORRETO afirmar que o tratamento de varizes gástricas hemorrágicas, no contexto\nde uma hipertensão portal esquerda, deve ser\nrealizado com:","options":{"A":"Gastrectomia.","B":"Esplenectomia.","C":"Derivação mesocava.","D":"Derivação portossistêmica intra-hepática transjugular."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-320452","number":"320452","sourceNumber":"320452","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher com 53 anos de idade, internada por cirrose de etiologia alcoólica e\nhemorragia digestiva alta, em uso de\nfurosemida 40 mg endovenosa por dia, evoluindo com piora\nda função renal nos últimos 3 dias. Encontra-se em regular estado geral, ictérica 2+/4, edemaciada,\nsonolenta, com flapping presente. Sinais vitais: pressão arterial de 90 x 60 mmHg, FC 90 de bpm e\nFR de 16 irpm. Ausculta pulmonar e cardíaca sem alteração. Abdome com ascite volumosa. Edema\nde membros inferiores de 2+/4+. Sobre a causa de injúria renal aguda (IRA) apresentada, é correto\nafirmar que:","options":{"A":"Esta paciente apresenta síndrome hepatorrenal.","B":"Esta paciente não apresenta IRA pré-renal, pois encontra-se em anasarca.","C":"Para diferenciar causa pré-renal de hepatorrenal, deve-se dosar a fração de excreção de uréia.","D":"Para afastar causa pré-renal, deve-se suspender o diurético e iniciar expansão com albumina.","E":"Nesta paciente, a IRA é causada por uma síndrome compartimental abdominal."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-306726","number":"306726","sourceNumber":"306726","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"J.C.P, 60 anos, etilista, dá entrada no pronto atendimento apresentando hematêmese\nde grande monta. Acompanha no ambulatório de\ngastroenterologia devido cirrose hepática e nega\nepisódio prévio de sangramento. Faz uso de propranolol 40mg de 12/12 horas. PA = 70/40mmHg,\nFC = 130bpm, FR = 20irpm, SpO2 = 95%. Qual é a melhor conduta no momento?","options":{"A":"Infusão venosa de nitroglicerina","B":"Inserção de balão de Sengstaken-Blakemore","C":"Administração de propranolol","D":"Realização de endoscopia digestiva alta imediatamente"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-291636","number":"291636","sourceNumber":"291636","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"?A infecção da ascite se constitui em uma das mais frequentes infecções que acomete\no paciente cirrótico, estando associada à alta\nmorbimortalidade. Pode ocorrer secundariamente a\numa fonte intra-abdominal de infecção, havendo, nesta situação, uma contagem de leucócitos\npolimorfonucleares (PMN) e cultura da ascite :\nperitonite bacteriana secundária (PBS) ou mais comumente na ausência de infecção\n\nintra-abdominal: Peritonite bacteriana espontânea (PBE). Para o diagnóstico de PBE há a\nnecessidade de uma contagem PMN , independente do resultado da\ncultura.? Assinale a alternativa que completa correta e sequencialmente a afirmativa anterior.","options":{"A":"> 250 células/ml / negativa / < 250 células/ml.","B":"< 250 células/ml / positiva / > 250 células/ml.","C":"> 250 células/ml / indeterminada / < 250 células/ml.","D":"< 250 células/ml / negativa / > 250 células/ml.","E":"> 250 células/ml / positiva / > 250 células/ml."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-287329","number":"287329","sourceNumber":"287329","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 55 anos, cirrótico de etiologia alcoólica, com 03 episódios de\nhemorragia digestiva alta (hematêmese) no último ano, por duas vezes tendo sido necessário\nreceber hemotransfusões. Atualmente não sangra há 30 dias. Qual a melhor conduta para o caso\nclínico?","options":{"A":"Tratamento farmacológico com propranolol.","B":"Tratamento endoscópico com ligadura elástica de varizes e tratamento farmacológico com\npropranolol.","C":"Tratamento cirúrgico com desconexão ázigo-portal + esplenectomia.","D":"Tratamento cirúrgico com derivação esplenorrenal."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-283889","number":"283889","sourceNumber":"283889","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na avaliação do diagnóstico diferencial da ascite, a paracentese e análise do líquido de\nascite são fundamentais. Assim, são causas de gradiente albumina sérica-ascite ? 1,1, EXCETO\nascite secundária à:","options":{"A":"Pericardite constritiva.","B":"Cirrose.","C":"Síndrome de Budd-Chiari.","D":"Síndrome nefrótica.","E":"Insuficiência cardíaca congestiva."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-287335","number":"287335","sourceNumber":"287335","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 78 anos, masculino, diabético, é atendido na Unidade Básica de Saúde. Os\nfamiliares informam que o paciente está apresentando frequentes episódios de desorientação, com\nperíodos de melhora. Relatam também que está apresentando inversão do ciclo sono x vigília. Ao\nexame físico, paciente encontra-se desorientado, confuso, apresentando um hálito forte, está\ncorado e hidratado, apresenta manchas avermelhadas em tórax com o formato aracneiforme,\naumento de volume abdominal e edema de membros inferiores. Qual o provável diagnóstico da\nalteração neurológica?","options":{"A":"Demência.","B":"Hipovolemia.","C":"Encefalopatia hepática.","D":"Uremia."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-283903","number":"283903","sourceNumber":"283903","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual das alternativas abaixo apresenta uma relação GASA (Gradiente Albumina Sérica\nAlbumina do líquido de ascite) <1.1g/dL?","options":{"A":"Cirosse.","B":"Hepatite alcoólica.","C":"Carcinomatose peritoneal.","D":"Insuficiência cardíaca.","E":"Síndrome de Budd-Chiari."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-246351","number":"246351","sourceNumber":"246351","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 43 anos de idade encontra-se internado na enfermaria de clínica médica\ndevido a quadro de aumento do volume\nabdominal de início há 10 dias. Nega episódios febris e\nrelata ser etilista há cerca de 20 anos, com ingestão de 0,5 litro de aguardente por dia durante\neste\nperíodo. Nega outras comorbidades conhecidas, mas relata que não faz acompanhamento médico\nregular. Ao exame físico apresenta-se emagrecido, em regular estado geral, lúcido e orientado,\nhipocorado (+/4+), ictérico (+/4+), afebril. Sinais vitais estáveis e exame do aparelho\ncardiovascular\ne respiratório sem alterações. O abdome apresenta-se globoso, com RHA presentes, indolor a\npalpação superficial e profunda, sem sinais de irritação peritoneal, macicez móvel positiva e espaço\nde Traube ocupado. À admissão no pronto-socorro foram solicitados exames laboratoriais, com os\nseguintes resultados: Hemoglobina 10,6 mg/dl; hematócrito 37%, leucócitos 4.200 com diferencial\nnormal, plaquetas 90.000 mm³, ureia 30 mg/dl, creatinina 0,6 mg/dl, sódio 137 mEq/dl, potássio 3,7\nmEq/dl, AST 60 UI (VR:40), ALT 80 UI (VR: 45), fosfatase alcalina 424 U/L (VR:210 U/L), gama-GT\n367 U/L (VR: 50 U/L), bilirrubina total 3,2 mg/dL com 2,8 mg/dL de fração direta, proteínas totais\nde\n3,1 g/dL (albumina sérica: 2,0 g/dL), INR 1,2 e sorologias para hepatites virais negativas.\n\nRadiografia de tórax em ortostase e de abdome em decúbito lateral não evidenciaram ar livre.\nRealizada paracentese diagnóstica e envio do líquido ascítico para análise, que evidenciou\ndosagem de proteínas totais 0,8 g/dL (albumina 0,5 g/dL) e ausência de bactérias coradas pelo\nGram. A citometria revelou 120 leucócitos/mm³ (33% de polimorfonucleares) e a cultura está em\nandamento. Baseado neste caso, assinale a alternativa que representa a melhor condução para\neste paciente.","options":{"A":"Realização de dieta hipossódica (até 2 g de sódio/dia) associado a furosemida endovenosa.","B":"Está indicado antibiótico para prevenção de peritonite bacteriana espontânea, podendo ser\nutilizada a norfloxacina oral diária.","C":"Realização de paracentese de alívio para remoção de todo líquido ascítico, permitindo assim a\nrealização de biópsia hepática diagnóstica.","D":"A complementação propedêutica com ecocardiograma transtorácico é fundamental antes de\n\nqualquer terapêutica para este caso."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-246352","number":"246352","sourceNumber":"246352","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 35 anos, vigilante, previamente hígida, comparece ao ambulatório de clínica\nmédica referindo parestesia em membros inferiores de evolução há cerca de um ano. Há 2 meses\nsua mãe faleceu de câncer gástrico e, desde então, está apresentando dificuldade de concentração\ne déficit de memória recente. Após o falecimento de sua mãe a paciente foi submetida a\nendoscopia digestiva alta, que evidenciou gastrite atrófica confirmada por biópsia, com pesquisa\nnegativa para Helicobacter pylori. Além disso, também traz exames realizados de rotina há 1\nsemana que foram solicitados por sua ginecologista: Hemoglobina: 10,4 g/dL, hematócrito 30%,\nVCM: 110 fL, HCM 28 pg, CHCM 32g/dL, RDW 10%, Leucócitos totais 3,5 x 10³/mm³ (basófilos\n0,5%/ eosinófilos 2,5%/ mielócitos 0%/ metamielócitos 0%/ bastões 1%/ segmentados 55%/\nlinfócitos 35%/ monócitos 6%) com hiperssegmentação de neutrófilos, plaquetas 87.000, TSH 4,0\nmUI/L (VR: 0,45 - 4,5 mUI/L). Baseado no caso podemos afirmar que trata-se de:","options":{"A":"Síndrome nefrótica.","B":"Hepatite alcoólica fulminante.","C":"Cirrose não complicada.","D":"Cirrose complicada com peritonite bacteriana."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-234411","number":"234411","sourceNumber":"234411","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 45 anos é levado ao pronto atendimento pelos familiares com o relato\nde ter apresentado um episódio de\nhematêmese. É portador de cirrose hepática e possui varizes de\nesôfago. Faz uso diário de furosemida, espironolactona, propranolol e clonazepam há 1 semana.\n\nAo exame físico, apresenta-se letárgico, com fala arrastada, desorientado no tempo e no espaço;\nas mucosas estão coradas, ictéricas e\nhidratadas. Os dados vitais são PA: 120 X 70mmHg, FC:\n61bpm, FR: 13ipm, SpO? em ar ambiente 98%. Apresenta aranhas vasculares no tronco. O exame\nneurológico revela força muscular simétrica e normal; há mioclonias nos membros superiores ao\nficarem estendidos. O restante do exame físico não apresenta anormalidades. Exames de\nlaboratório: hemoglobina 13,9g/dL; leucócitos 5.560/mm³; neutrófilos segmentados 4.310/mm³;\nplaquetas 102.000/mm³; proteína C reativa 3mg/L; creatinina 0,5mg/dL; ureia 12mg/dL; bilirrubina\ntotal 1,5mg/dL; bilirrubina direta 0,9mg/dL; bilirrubina indireta 0,6mg/dL; potássio 2,6mEq/L; sódio\n131mEq/L. Considerando o caso descrito, assinale a alternativa que apresenta uma condição que\nNÃO deve ter desencadeado a encefalopatia nesse paciente.","options":{"A":"Hemorragia digestiva.","B":"Hipocalemia.","C":"Uso do clonazepam.","D":"Uso do propranolol."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227257","number":"227257","sourceNumber":"227257","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a Peritonite Bacteriana Espontânea (PBE), infecção que ocorre no líquido\nascítico de pacientes cirróticos sem que exista\nqualquer outra fonte intra-abdominal de infecção,\nassinale a alternativa CORRETA:","options":{"A":"A profilaxia primária da PBE é recomendada para todo paciente cirrótico que apresente proteína\nno líquido ascítico menor 1,5 mg/dl.","B":"A infusão de albumina humana a 20% é recomendada para prevenção de síndrome hepatorrenal\nquando o paciente cirrótico com\ndiagnóstico de PBE apresentar bilirrubina sérica maior que 2 mg/dl\ne ureia maior 25 mg/dl.","C":"Pacientes cirróticos com ascite, que apresentem episódio de sangramento gastrointestinal agudo\ndevem receber antibioticoprofilaxia para PBE.\nA droga de escolha é a amoxicilina na dose de 500\nmg de 12/12 horas por via oral durante 7 dias.","D":"A profilaxia secundária de PBE deve ser feita com norfloxacina 400 mg ao dia até resolução da\nascite, ou até que o paciente seja submetido ao transplante hepático, caso seja elegível."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-232137","number":"232137","sourceNumber":"232137","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 55 anos de idade se apresenta com um primeiro episódio de ascite.\nRealizada paracentese diagnóstica, fluído\nascítico tem nível de proteína 2,8 g/dL e o nível de\nalbumina de 2,1 g/dL. Uma amostra sanguínea simultânea mostra uma albumina de 3,4 g/dL. Qual\na causa mais provável da ascite neste caso?","options":{"A":"Cirrose.","B":"Doença Cardíaca.","C":"Síndrome Nefrótica.","D":"Doença Pancreática.","E":"Carcinomatose Peritoneal."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-255662","number":"255662","sourceNumber":"255662","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quais as condutas que são a base do tratamento da doença hepática gordurosa não\nalcoólica? MARQUE A CORRETA:","options":{"A":"Alterações no estilo de vida e modificações dietéticas.","B":"Administração de Metformina associada a insulina.","C":"Cirurgia bariátrica e acompanhamento psicológico.","D":"Prescrição de probióticos e estatinas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212900","number":"212900","sourceNumber":"212900","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente cirrótico por vírus B, sem tratamento específico, etilista inveterado.\nApresenta-se bilirrubina total de 6,5 mg%, ascite\nmoderada, albumina de 2,9 mg%, TAP e PTTK\nnormais, sem sinais de encefalopatia hepática. Segundo a Classificação de Child-Pugh, a\npontuação e a classe deste paciente é:","options":{"A":"7 pontos, Child-Pugh A.","B":"8 pontos, Child-Pugh B.","C":"9 pontos, Child-Pugh B.","D":"10 pontos, Child-Pugh C.","E":"11 pontos, Child-Pugh C."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-199516","number":"199516","sourceNumber":"199516","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Os pacientes portadores de cirrose hepática podem apresentar diversas complicações,\nque podem levar ao óbito se não reconhecidas e\ntratadas pronta e adequadamente. Assinale a\nalternativa que apresenta um tratamento INADEQUADO para a respectiva complicação da cirrose\nhepática.","options":{"A":"Hemorragia digestiva alta ? octreotide intravenoso e ligadura elástica das varizes do\nesôfago.","B":"Peritonite bacteriana espontânea ? paracentese de alívio e ceftriaxona intravenosa.","C":"Ascite ? restrição dietética de sódio e diureticoterapia (furosemida e espironolactona).","D":"Síndrome hepatorrenal ? expansão volêmica com albumina e noradrenalina intravenosa."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212913","number":"212913","sourceNumber":"212913","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na evolução da hipertensão portal a ruptura de varizes esofagogástricas é a\ncomplicação mais temida. Assinale a alternativa correta quanto ao sangramento por varizes de\nesôfago:","options":{"A":"Pode ocorrer com valores de pressão venosa portal < 5mmHg.","B":"Ocorre sangramento recorrente quando valor de pressão venosa portal > 20 mmHg.","C":"A taxa de ressangramento da hemorragia digestiva alta varicosa é menor que a taxa de\nhemorragia digestiva alta não varicosa.","D":"A chance de sangramento não está associada a gravidade da doença hepática.","E":"O risco de sangramento ocorre com mais freqüência nas varizes proximais."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-202752","number":"202752","sourceNumber":"202752","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual o método mais rápido e eficaz na determinação da etiologia da ascite?","options":{"A":"Ultrassonografia de abdome total com doppler.","B":"Angiotomografia abdominal.","C":"Paracentese com análise do líquido ascítico.","D":"Ressonância Nuclear Magnética de Abdome total.","E":"Dosagem sérica de provas de função hepática e sorologia viral."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-215125","number":"215125","sourceNumber":"215125","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A indicação mais frequente para um transplante hepático em crianças é:","options":{"A":"Doença de Wilson.","B":"Síndrome de Alagille.","C":"Atresia Biliar.","D":"Hepatite aguda fulminante.","E":"Tirosinemia elevada."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-172789","number":"172789","sourceNumber":"172789","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Hemorragia Digestiva Alta Varicosa (HDAV) é uma condição frequente em\natendimentos de pronto-socorro. Em relação\nao episódio agudo de HDAV analise as afirmativas\nabaixo e em seguida assinale a alternativa CORRETA.\n\nI. Faz parte do protocolo de HDAV, e é sempre recomendado, o uso de lactulose para previnir\nepisódio de encefalopatia hepática;\n\nII. Drogas vasoativas devem ser iniciadas após realização da endoscopia disgestiva alta e\ncomprovação da origem varicosa da hemorragia digestiva;\n\nIII. Antobioticoprofilaxia é parte integral da terapia para pacientes cirróticos que se apresentam\ncom\nHDAV. O uso de ceftríaxone endovenoso 1 g a cada 24 horas deve ser considerada para pacientes\ncom cirrose avançada;\n\nIV. Hiponatremia é um efeito colateral descrito da terlipressina, especialmente em pacientes com\nfunção hepática preservada.","options":{"A":"I,II e IV estão corretos.","B":"III e IV estão corretos.","C":"II, III, e IV estão corretos.","D":"I, II, III e IV estão corretos."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-172800","number":"172800","sourceNumber":"172800","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite é a causa mais comum de descompensação na cirrose hepática. Sobre a\nascite do paciente cirrótico e suas complicações, assinale a alternativa CORRETA:","options":{"A":"Bactérias Gram-negativas (Escherichia coli e Klebsiella pneumoniae) e Gram-positivas\n(Staphylococcus aureus) são os micro-organismos mais\nfrequentemente isolados na peritonite\nbacteriana espontânea.","B":"A ascite do paciente cirrótico se caracteriza pela presença de um gradiente de albumina\nsoroascítico (GASA) maior ou igual a 1,1 g/dl e\nproteína total no líquido ascítico maior que 2,5 g/dl.","C":"Ascite neutrocítica é caracterizada por contagem de polimorfonucleares maior ou igual a\n250/mm³ e cultura do líquido ascítico negativa. Deve ser tratada como peritonite bacteriana\nespontânea clássica.","D":"Pacientes cirróticos com ascite, febre e piora de função renal podem ser tratados de forma\nempírica para peritonite bacteriana espontânea sem necessidade de realização de paracentese\ndiagnóstica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-172537","number":"172537","sourceNumber":"172537","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na análise do líquido ascítico de um paciente cirrótico, estéril e/ou com peritonite,\npodem ser encontradas as seguintes alterações\nEXCETO:","options":{"A":"Gradiente soro-ascite de albumina \"maior que\" ou = 1.1g/dl.","B":"Número de neutrófilos \"maior que\" 250/mm³.","C":"Proteína total \"maior que\" 2,5 g/dl","D":"Proteína total \"menor que\" 2.5 g/dl.","E":"Coloração amarelo translúcido."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174355","number":"174355","sourceNumber":"174355","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em portadores de hipertensão portal, na vigência de hemorragia digestiva alta de\netiologia varicosa, com o objetivo de diminuir a chance de ressangramento, a modalidade\nterapêutica endoscópica e a droga de escolha são, respectivamente:","options":{"A":"Ligadura elástica e terlipressina.","B":"Escleroterapia e octreotideo.","C":"Clampeamento metálico e somatostatina.","D":"Termoterapia e terlipressina.","E":"Ligadura elástica e propranolol."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174369","number":"174369","sourceNumber":"174369","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a hemorragia digestiva alta por varizes esofágicas, pode-se afirmar:","options":{"A":"Shunt intra-hepático transjugular portossistêmico (TIPS) está associado a taxas de\nressangramento de até 80% no primeiro mês.","B":"O balão de Sengstaken-Blakemore deve ser utilizado na admissão enquanto aguarda a\nrealização de endoscopia digestiva alta.","C":"Vasopressina deve ser utilizada para iniciar a vasodilatação esplâncnica.","D":"O tratamento endoscópico é capaz de controlar a hemorragia em até 90% dos pacientes.","E":"Antibioticoterapia deve ser iniciada somente em casos de pneumonia associada ao uso do balão\nde Sengstaken-Blakemore."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187476","number":"187476","sourceNumber":"187476","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 50 anos, com cirrose relacionada com hepatite C e álcool apresenta\nascite necessitando de paracenteses de grande\nvolume com certa frequência. Todos os\ntratamentos descritos abaixo são indicados para esse paciente, EXCETO:","options":{"A":"Restrição de líquidos para menos de 2 litros por dia.","B":"Furosemida 40mg ao dia.","C":"Restrição de sódio para menos de 2 gramas por dia.","D":"Espironolactona 100mg ao dia.","E":"Se o tratamento clínico falhar está indicado shunt portossistêmico intra-hepático transjugular."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-172776","number":"172776","sourceNumber":"172776","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São indicações para transplante hepático, exceto:","options":{"A":"Paciente cirrótico CHILD A com 02 ou mais episódios de hemorragia digestiva alta e\nnecessidade de hemotransfusão.","B":"Paciente cirrótico CHILD B ou C, independente de complicações.","C":"Paciente cirrótico que já tenha apresentado trombose de veia porta, independente do escore de\nCHILD.","D":"Paciente cirrótico com carcinoma hepatocelular menor que 5 cm."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-162568","number":"162568","sourceNumber":"162568","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O antídoto indicado para o tratamento da intoxicação exógena por paracetamol é:","options":{"A":"Atropina.","B":"Piridoxina.","C":"Tiamina.","D":"Riboflavina.","E":"N-acetilcisteína."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-148552","number":"148552","sourceNumber":"148552","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente deu entrada no pronto-socorro com queixas de aumento do volume abdominal\nnas ultimas semanas. Durante o exame físico foi\ndiagnosticado ascite. Foi realizado coleta de\nsangue e paracentese para coleta de liquido ascítico. Conforme a classificação da ascite pelo\ngradiente soro-albumina-ascite, são causas de gradiente elevado (>1,1 g/dl) as seguintes\nsituações, EXCETO:","options":{"A":"Cirrose.","B":"Ascite cardíaca.","C":"Ascite pancreática.","D":"Síndrome e Budd-Chiari.","E":"Mixedema."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-131639","number":"131639","sourceNumber":"131639","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Devem ser testados para mutação do gene HFE para hemocromatose hereditária\npacientes que apresentem :","options":{"A":"Hematócrito > 50% e ferro sérico elevado.","B":"Ferro sérico elevado e ferritina baixa.","C":"Saturação de transferrina e ferritina elevados.","D":"Saturação de transferrina normal ou elevada e hematócrito > 50%.","E":"Ferritina elevada e ferro sérico elevado."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-106421","number":"106421","sourceNumber":"106421","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dentre os fármacos abaixo, qual é o que tem um efeito tóxico direto sobre os\nhepatócitos?","options":{"A":"Paracetamol.","B":"Clorpromazina.","C":"Halotano.","D":"Isoniazida.","E":"Rosuvastatina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-111589","number":"111589","sourceNumber":"111589","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hepatite alcoólica aguda:","options":{"A":"tem como ponto de corte habitual para seu diagnóstico o nível de TGP duas vezes maior que\nTGO.","B":"tem como ponto de corte habitual para seu diagnóstico o nível de TGO 1,3 vezes maior que\nTGP.","C":"deve ser tratada com corticoide se houver índice de Maddrey superior a 22.","D":"é caracteristicamente acompanhada de leucopenia.","E":"ocorre com aumento do uso de álcool, mas também com ingesta excessiva estável."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-101042","number":"101042","sourceNumber":"101042","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 28 anos, feminina, deu entrada no pronto-socorro com dor abdominal\nintensa e distensão abdominal. Ao exame,\napresentava ascite tensa. Foram realizados exames que\nmostraram proteína total no sangue de 6,3 g/dl, albumina de 3,5 g/dl e globulina de 2,8 g/dl. O\nexame do líquido ascítico mostrou proteína total de 5,8 g/dl, com albumina de 2,8 g/dl. Sabendo\nque o GASA (Gradiente de Albumina Soro-Ascite) é importante para o raciocínio diagnóstico da\netiologia da ascite, responda qual foi o GASA da paciente:","options":{"A":"6,3.","B":"0,7.","C":"1,25.","D":"9,8.","E":"0,5."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-77367","number":"77367","sourceNumber":"77367","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente 68 anos, sexo masculino, é internado no hospital com sinais de desnutrição e\natrofia muscular, em anasarca e com pronunciado aumento do volume abdominal, com rarefação\nde pelos, ginecomastia, aranhas vasculares e icterícia. Qual das alternativas abaixo não é\nesperada neste paciente?","options":{"A":"US de abdome com fígado de volume reduzido.","B":"RNI > 2,3.","C":"Gradiente de Albumina Soro-Ascite (GASA) > 1,1 g/dl, com proteína total no líquido ascítico\nmaior que 2,5 g/dl.","D":"Varizes de esôfago na endoscopia digestiva alta.","E":"Albumina sérica < 2,8 g/dl."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-88878","number":"88878","sourceNumber":"88878","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um alcoólico contumaz apresentou manifestações clínicas compatíveis com beribéri.\nEssa doença está relacionada à deficiência da\nseguinte vitamina:","options":{"A":"Biotina.","B":"Tiamina.","C":"Niacina.","D":"Piridoxina.","E":"Ácido ascórbico."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-59451","number":"59451","sourceNumber":"59451","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação às hepatopatias relacionadas ao álcool, marque a alternativa CORRETA:","options":{"A":"São duas as suas formas de apresentação clínica: esteatose ou hepatite alcoólica.","B":"São causadas apenas pelo consumo excessivo e prolongado de bebidas destiladas.","C":"A hepatite alcoólica grave pode apresentar mortalidade superior a 50% em 30 dias em pacientes\ngravemente enfermos.","D":"O uso de corticoides no tratamento da hepatite alcoólica grave foi abolido devido ao aumento de\nmortalidade relacionado a seu uso.","E":"Os pacientes com hepatite alcoólica grave são candidatos a transplante de fígado em caráter de\nemergência quando disponível."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-9413","number":"9413","sourceNumber":"9413","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 47 anos de idade, com história de cirrose hepática, foi\ninternado na enfermaria de clínica médica.\nAo exame físico apresenta-se sonolento, desorientado\nno tempo e no espaço, com flapping. Apresenta aranhas vasculares em tronco e membros\nsuperiores, hipotrofia muscular e edema de MMII (++/4+). Ao exame físico do abdome nota-se\ncirculação colateral, hérnia umbilical e manobra de macicez móvel positiva. Foram realizados os\nseguintes exames laboratoriais: albumina 2,2 g/dl; AST 110 U/l (valor de referência até 30 U/l); ALT\n60 U/l (valor de referência até 30 U/l); bilirrubina total 4,1 mg/dl, TAP 45%; Na 135 mEq/L; K 3,8\nmEq/L; creatinina 1,5 mg/dl; ureia 48 mg/dl. Os achados do líquido ascítico incluem 650\nleucócitos/mm³ (60% polimorfonucleares); proteína total de 0,8 g/dl e albumina de 0,4 g/dl. A\ncultura\ndo líquido ascítico ainda está em andamento. Em relação ao caso acima, assinale a alternativa\nINCORRETA:","options":{"A":"A análise do líquido ascítico é compatível com diagnóstico de peritonite bacteriana espontânea\ne, portanto, o paciente deve receber tratamento\ncom cefalosporina de 3ª geração.","B":"O paciente apresenta alterações ao exame físico que são compatíveis com encefalopatia\nhepática. A insuficiência renal e a presença\nde infecções são fatores precipitantes dessa\ncomplicação da cirrose hepática.","C":"Os níveis séricos elevados de bilirrubinas e transaminases e o prolongamento do tempo de\nprotrombina, ajudam a avaliar o prognóstico do paciente.","D":"A taxa de recorrência da peritonite bacteriana espontânea é elevada, portanto, após o fim do\ntratamento, esse paciente deverá receber profilaxia secundária com quinolona.","E":"A paracentese terapêutica com reposição de albumina pode ser utilizada para tratar a ascite do\npaciente."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-363958","number":"363958","sourceNumber":"363958","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na conduta relacionada à hemorragia digestiva alta, de etiologica varicosa, é\nimportante","options":{"A":"a realização da profilaxia de infecções, considerando os seguintes antibióticos: a cefadroxila,\ncefazolina e cefoxitina.","B":"o uso da terlipressina, por ser um constritor esplâncnico, é uma das opções medicamentosas.","C":"o uso do balão de Sengstaken - Blackmore, mantido por no máximo 48 horas.","D":"a utilização do TIPS, com o objetivo de embolizar ramos portais, nos casos refratários à\nterapêutica endoscópica adequada."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-353840","number":"353840","sourceNumber":"353840","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em casos de Peritonite Bacteriana Espontânea (PBE), a antibioticoterapia empírica\nmais indicada é:","options":{"A":"Azitromicina.","B":"Vancomicina.","C":"Amoxicilina.","D":"Cefotaxima."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-363963","number":"363963","sourceNumber":"363963","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Leia o caso clínico a seguir: Mulher, 22 anos, chega ao ambulatório com história de\ninício, há 40 dias, de aumento progressivo\ndo volume abdominal, com dor leve, associado a perda\nde peso de 5 Kg no período, inapetência, episódios esporádicos de febre não medida. Ao exame\nclínico nota-se ascite moderada, indolor à palpação, sem aumento de fígado e baço; ausência de\nicterícia e outros sinais de hepatopatia crônica. Exames complementares revelam discreta anemia e\nleucopenia, plaquetas normais, AST, ALT e bilirrubinas normais, INR 1,2 e albumina sérica 2,8\nmg/dl; análise do líquido ascítico com predomínio de linfócitos, albumina 2,4 mg/dl. Já trouxe\nconsigo resultado de endoscopia, com úlcera duodenal em atividade, colonoscopia normal e TC de\nabdome e pelve, mostrando sinais de ascite e aparente espessamento peritoneal. Qual é a principal\nhipótese diagnóstica?","options":{"A":"Ascite por hipertensão portal não cirrótica.","B":"Tuberculose peritoneal.","C":"Neoplasia de ovário.","D":"Úlcera duodenal perfurada bloqueada."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-363985","number":"363985","sourceNumber":"363985","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"As lesões hepáticas induzidas por drogas podem se manifestar de diversas formas,\ncomo Hepatite, Fibrose, Esteatose ou Colestase.\nDentre as drogas que cursam com lesão\ncolestática, podemos citar:","options":{"A":"Paracetamol.","B":"Amiodarona.","C":"Amoxicilina + Clavulanato.","D":"Prednisolona."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-366973","number":"366973","sourceNumber":"366973","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 60 anos com cirrose hepática é avaliado para transplante de fígado.\nSeus exames mostram uma bilirrubina total de\n3,5 mg/dL, albumina sérica de 3,2 g/dL, tempo de\nprotrombina prolongado e ascite moderada. Com base nesses parâmetros, qual dos seguintes\ncritérios é correto em relação à classificação funcional de Child-Turcotte modificada por Pugh?","options":{"A":"O paciente é classificado como Child-Pugh A.","B":"O paciente é classificado como Child-Pugh B.","C":"O paciente é classificado como Child-Pugh C.","D":"A classificação Child-Pugh não avalia ascite."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-354825","number":"354825","sourceNumber":"354825","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 56 anos de idade, sexo masculino,\nportador de cirrose de etiologia metabólica,\ndeu entrada no pronto socorro relatando episódio de\nhematêmese volumosa há cerca de 12 horas, seguido por vários episódios de melena; trouxe\nresultado de endoscopia realizada há 3 meses, que mostra varizes esofágicas de grosso calibre,\ncom múltiplos sinais vermelhos, época em que iniciou uso profilático de propanolol. O paciente\nencontra-se orientado, lúcido, descorado, levemente ictérico, com ascite moderada, PA: 90/50\nmmHg, FC: 110 bpm. Os primeiros exames revelam Hb: 8,1 md/dL e plaquetas: 42.000. De acordo\ncom o caso relatado, qual é a conduta a ser adotada pelo médico da emergência?","options":{"A":"Iniciar reposição de volume com soro fisiológico de forma rápida, e imediatamente solicitar\ntransfusão de concentrado de hemácias e plaquetas.","B":"Iniciar reposição de volume com soro fisiológico de forma rápida e entrar em contato urgente\ncom a equipe de endoscopia.","C":"Iniciar tratamento com vasoconstritor esplâncnico e antibioticoterapia profilática, aguardar\nestabilização hemodinâmica, e programar endoscopia nas próximas 12 horas.","D":"Iniciar transfusão de concentrado de hemácias, e aguardar que a HB esteja acima de 10 e\nplaquetas acima de 60.000, para programar endoscopia."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-354824","number":"354824","sourceNumber":"354824","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente 14 anos de idade, sexo feminino, foi\ninternada apresentando história de icterícia há 1 mês e desconforto em hipocôndrio direito. Possui\nantecedente pessoal de diabetes mellitus tipo 1. Ao exame físico apresentava-se ictérica ++/4, com\nhepatomegalia, sem sinais de ascite. Exames laboratoriais: TGO: 700; TGP: 850; FA: 315;\ngamaGT: 400; bilirrubinas totais= 7,0; Anti HCV negativo; aghbs negativo; antiHBC negativo;\nantihbs positivo; anti LKM1 positivo 1/160, FAN neg; eletroforese de proteínas com elevação de\ngamaglobulinas. Realizado biópsia hepática: visto infiltrado linfoplasmocitário intenso invadindo a\nplaca limitante do espaço porta, além de septos de fibrose esboçando nódulos de regeneração. De\nacordo com o caso relatado, qual é a hipótese diagnóstica?","options":{"A":"Colangite esclerosante primária.","B":"Colangite biliar primária.","C":"Hepatite autoimune.","D":"Hepatite B aguda."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-363933","number":"363933","sourceNumber":"363933","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Leia o caso clínico a seguir. Um homem de 60 anos, com histórico de cirrose hepática,\nprocura atendimento médico queixando de aumento\nde volume abdominal e mucosas oculares\namareladas. O paciente relata que faz consumo de bebidas alcoólicas desde os 12 anos.\n\nBaseando-se no relato do paciente, qual complicação da cirrose hepática está associada a esses\nachados?","options":{"A":"Hepatite viral aguda.","B":"Hematêmese.","C":"Ascite.","D":"Encefatopatia hepática."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-321542","number":"321542","sourceNumber":"321542","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão portal geralmente ocorre em virtude da maior resistência ao afluxo\nvenoso portal de localização pré, intra ou pós-hepática. Por sua vez, a hipertensão portal\n\nintra-hepática pode ocorrer nos níveis pré-sinusoidal, sinusoidal ou pós-sinusoidal. Qual é a causa\nmais comum de hipertensão intra-hepática pré-sinusoidal?","options":{"A":"Trombose de veia porta.","B":"Cirrose alcoólica.","C":"Esquistossomose.","D":"Síndrome de Budd-Chiari."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-334776","number":"334776","sourceNumber":"334776","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, 45 anos de idade, encaminhada por apresentar fadiga,\nprurido difuso, icterícia e xantelasmas. Refere\nepisódios anteriores de icterícia há cerca de 3 anos.\nApresentava exames com AST e ALT elevadas cerca de 2 vezes o limite da normalidade, com\naumento expressivo de Gama GT e fosfatase alcalina (10 vezes acima do limite superior da\nnormalidade). Trazia consigo outros exames laboratoriais: Anti- HCV negativo; HBsAg negativo;\nAnti-HBc total reagente; AntiHBs reagente; FAN negativo; Antimúsculo liso reagente 1/20;\nAntimitocôndrias reagente 1/320. De acordo com o relato, o diagnóstico pode ser uma","options":{"A":"hepatite autoimune.","B":"colangite esclerosante primária.","C":"hepatite B crônica.","D":"colangite Biliar Primária"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-342608","number":"342608","sourceNumber":"342608","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em portadores de hipertensão portal, na vigência de hemorragia digestiva alta de\netiologia varicosa, com o objetivo de diminuir a chance de ressangramento, a modalidade\nterapêutica endoscópica e a droga de escolha são, respectivamente:","options":{"A":"ligadura elástica e terlipressina","B":"escleroterapia e octreotida","C":"clampeamento metálico e somatostatina","D":"termoterapia e terlipressina"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-339769","number":"339769","sourceNumber":"339769","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com diagnóstico de hemocromatose será avaliado por método de imagem. O\nmelhor método de avaliação é a:","options":{"A":"Tomografia computadorizada.","B":"Elastografia.","C":"Ressonância nuclear magnética.","D":"Ultrassonografia."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-321553","number":"321553","sourceNumber":"321553","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com diagnóstico de hemocromatose será avaliado por método de imagem. O\nmelhor método de avaliação é a","options":{"A":"tomografia computadorizada.","B":"elastografia.","C":"ressonância nuclear magnética.","D":"ultrassonografia."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-330104","number":"330104","sourceNumber":"330104","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à paracentese, é INCORRETO afirmar:","options":{"A":"O uso da albumina em paracentese de grande volume reduz a hiponatremia dilucional.","B":"É utilizada no tratamento de infecção cutânea ou celulite da parede abdominal.","C":"O paciente deve ser posicionado de maneira ereta na borda do leito ou em uma cadeira, e em\nFowler quando acamado.","D":"Uma amostra no líquido aspirado deve ser enviada para exames bioquímicos e bacterioscópico."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-317145","number":"317145","sourceNumber":"317145","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A circulação colateral do tipo hepato-fuga, por hipertensão portal, é encontrada nas\nseguintes situações, exceto:","options":{"A":"Sarcoidose.","B":"Obstrução de veias supra-hepáticas.","C":"Crise falcêmica.","D":"Síndrome da veia cava superior."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-317146","number":"317146","sourceNumber":"317146","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação a etiologia da hipertensão portal é correto afirmar, exceto:","options":{"A":"A esquistossomose mansônica é uma afecção que cursa com hipertensão portal pré-sinusoidal,\nintra-hepática.","B":"A cirrose hepática alcoólica cursa com hipertensão portal severa devido a obstrução\nintra-hepática, pré-sinusoidal, pela intensa fibrose associada.","C":"A síndrome de Budd-Chiari é a clássica causa de hipertensão portal pós-hepática.","D":"A hipertensão portal pré-hepática é uma grave complicação da pancreatite aguda."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-313189","number":"313189","sourceNumber":"313189","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 43 anos chegou ao ambulatório de cirurgia com antecedente de\nesquistossomose e relatando 2 episódios prévios de sangramento. Anteriormente ele necessitou de\ninternações com realização de ligaduras elásticas de varizes de esôfago, a última há 20 dias. Com\nbase nesse caso hipotético, assinale a alternativa que apresenta o tratamento de escolha para o\npaciente:","options":{"A":"acompanhamento clínico com betabloqueadores","B":"passagem de TIPS (Transjugular Intrahepatic Portosystemic Shunt)","C":"esofagectomia com anastomose faringocolônica","D":"desconexão ázigo-portal com esplenectomia"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-295357","number":"295357","sourceNumber":"295357","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na abordagem do paciente com ascite, considera-se importante o cálculo do Gradiente\nde Albumina Soro-Ascite (GASA). A etiologia da\nascite que apresenta GASA < 1,1 g/dl é:","options":{"A":"Cirrose hepática.","B":"Ascite cardíaca.","C":"Síndrome de Budd-Chiari.","D":"Ascite pancreática."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-311911","number":"311911","sourceNumber":"311911","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Durante a avaliação de uma hérnia de hiato esofágico, um homem de 45 anos\ndescobriu possuir esteatose hepática, de grau\nmoderado, pela avaliação ultrassonográfica. O\npaciente não tem histórico de doenças prévias, nega uso de medicações de uso contínuo, e refere\nà ingesta de bebidas alcoólicas apenas aos finais de semana. O exame físico era normal, exceto\npor IMC = 28 kg/m²; sobre esta condição clínica:","options":{"A":"Este paciente possui risco de desenvolver cirrose hepática nos próximos 10 a 20 anos, e a\nhistória natural desta doença independe do fato\nde a etiologia ter sido por esteato-hepatite alcoólica\nou não alcoólica.","B":"A maioria dos indivíduos com esteatose nega consumir álcool excessivamente, mas\npossivelmente preenche critérios para abuso por questionários específicos, apontando para\netiologia alcoólica.","C":"Níveis séricos de transaminases frequentemente se encontram aumentados e correlacionam-se\nbem com a gravidade da doença hepática,\npredizendo quais pacientes podem evoluir para cirrose\nhepática.","D":"O tratamento para a esteatose de etiologia alcoólica envolve interromper a ingesta de álcool,\nvitamina E e corticoesteroides. Para a forma não alcoólica, apenas vitamina E e modificação do\nestilo de vida são suficientes."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-317943","number":"317943","sourceNumber":"317943","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de 48 anos, portador de cirrose hepática secundária. Ao\nVHC, refere dor abdominal difusa há seis horas, febre de 38,9ºC e calafrios. Ao Exame físico,\nencontra-se sonolento, com flapping, PA: 118/75 mmHg. FC 105 bpm, FR 23 ipm. SaO?: 97% (ar\nambiente). A ausculta pulmonar é limpa, sem ruídos adventícios. O abdome encontra-se globoso,\ncom ascite moderada, distendido, sem sinais de irritação peritoneal, porém com ruídos hidroaéreos\ndiminuídos, trouxe ocupado e dor difusa à palpação. Foi realizada paracentese com retirada de\n1000 mL de líquido ascético turvo, cuja celularidade é 550 cels/mm³ e 80% de neutrófilos. Nesse\ncaso, qual o tratamento a seguir é o mais apropriado?","options":{"A":"Metronidazol e Amicacina.","B":"Rifaximina ou Neomicina.","C":"Vancomicina e Gentamicina.","D":"Ceftriaxona ou Cefotaxima."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-317944","number":"317944","sourceNumber":"317944","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher de 47 anos apresentou fadiga crônica e seu clínico geral notou testes de\nfunção hepática anormais nos últimos oito meses. Os resultados do exame de sangue foram\nfosfatase alcalina 311 UI/L (intervalo normal <130), alanina aminotransferase 110 U/L (normal <40),\nbilirrubina 0,64 mg/dl, anticorpos antinucleares não reagentes, anticorpos antimitocondriais 1: 80\n(subunidade M2 positiva), anticorpos antimúsculo liso não reagente. A ultrassonografia do fígado foi\nnormal. Nesse caso, qual é o diagnóstico mais provável?","options":{"A":"Reação medicamentosa colestática.","B":"Colangiocarcinoma intra-hepático.","C":"Colangite biliar primária.","D":"Colangite esclerosante primária."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-316323","number":"316323","sourceNumber":"316323","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação à cirrose, marque a alternativa INCORRETA:","options":{"A":"A classificação de Child-Pugh avalia prognóstico e sobrevida de pacientes com cirrose. Para o\nseu cálculo, utilizam-se as seguintes\nvariáveis: bilirrubina total, albumina, creatinina, presença de\nencefalopatia e ascite.","B":"Na cirrose ocorrem alterações no metabolismo dos hormônios sexuais e o paciente evolui com\naumento dos níveis séricos de estrogênio. O estrogênio tem efeito vasodilatador nos vasos\nsuperficiais da pele, justificando o aparecimento das telangiectasias e do eritema palmar.","C":"A síndrome hepatorrenal tipo I tem prognóstico ruim e se caracteriza por uma insuficiência renal\naguda oligúrica com sódio urinário baixo.","D":"Na cirrose ocorre fibrose do fígado. A célula estrelada hepática desempenha importante papel\nnesse processo de fibrose hepática."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-277414","number":"277414","sourceNumber":"277414","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão portal geralmente é assintomática, sendo seus sinais e sintomas\ndecorrentes das complicações da patologia. As\ncomplicações primárias consistem em varizes\ngastroesofágicas que correspondem às colaterais portossistêmicas, ascite e o hiperesplenismo. Em\nrelação às etiologias, assinale a seguir qual é responsável por uma hipertensão portal\nintra-hepática\nsinusoidal:","options":{"A":"Cavernomatose da veia porta","B":"Esquistossomose","C":"Malformação congênita da veia cava inferior","D":"Hepatite crônica"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-281990","number":"281990","sourceNumber":"281990","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre as hepatopatias crônicas, é INCORRETO afirmar que:","options":{"A":"Os anticorpos antimitocondriais estão presentes na colangite biliar primária.","B":"O diagnóstico de colangite esclerosante primária se dá através de exames de imagem como\ncolangiorressonância, colangiografia endoscópica.","C":"A hepatite autoimune tipo 1 tem como marcador sérico o anticorpo anti-LKM1.","D":"A quantidade e a duração do consumo de álcool são fatores de risco primários para a doença\nalcoólica do fígado."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-273172","number":"273172","sourceNumber":"273172","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quanto ao manejo da hepatopatia em paciente que apresenta hemorragia digestiva alta\npor varizes de esôfago, é INCORRETO afirmar:","options":{"A":"Corrigir distúrbios de coagulação.","B":"Prevenir a encefalopatia hepática.","C":"Iniciar antibiótico profilático.","D":"Realizar manejo endoscópico."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274497","number":"274497","sourceNumber":"274497","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No que concerne às patologias hepáticas assinale a INCORRETA:","options":{"A":"O hemangioma hepático representa o tumor benigno mais comum do fígado, à frente da\nhiperplasia nodular focal.","B":"O cistoadenoma hepático pode ter transformação maligna e acomete principalmente mulheres\nacima de 40 anos.","C":"A principal manifestação da hipertensão portal é a hemorragia digestiva alta manifestando-se\ngeralmente por hematêmese ou melena, sendo no\nBrasil as principais causas a esquistossomose e\ncirrose hepática. A realização de tomografia de abdome auxilia no diagnóstico e a endoscopia se\ntorna imperativa para pacientes com suspeita clínica, contudo o achado de varizes gástricas ou\nesofágias não confirma hipertensão portal.","D":"Segundo a classificação de Coinaud para a segmentação hepática a hepatectomia direita\nampliada inclui os segmentos IV, V, VI, VII e VIII."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-273180","number":"273180","sourceNumber":"273180","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em um transplante, o órgão ou tecido doado pode ser proveniente de um doador vivo\nou morto. Pode ser doador vivo:","options":{"A":"Qualquer pessoa saudável que se disponha a doar um órgão, tecido ou parte dele.","B":"Não parentes, desde que seja o cônjuge e possua autorização judicial.","C":"Parentes até quarto grau e cônjuge que atenda todos os critérios para doação.","D":"Indivíduo saudável, juridicamente capaz, submetido à rigorosa investigação clínica, no caso de\ndoação do fígado."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-241685","number":"241685","sourceNumber":"241685","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 46 anos, diagnosticado com esteato-hepatite não alcoólica e diabetes\nmellitus, busca orientações quanto ao\ntratamento de sua doença hepática. Conclui-se que melhores\nresultados são obtidos por meio de:","options":{"A":"ácidos graxos ômega-3.","B":"metformina e estatinas.","C":"perda de 5 a 10% do peso.","D":"restrição completa de carboidratos.","E":"rosiglitazona."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-254217","number":"254217","sourceNumber":"254217","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual hepatopatia é mais comum em homens?","options":{"A":"Cirrose biliar primária.","B":"Hepatite autoimune.","C":"Hemocromatose.","D":"Nenhuma das anteriores."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-254218","number":"254218","sourceNumber":"254218","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente encaminhado para ambulatório de Hepatologia após diagnóstico de Cirrose\nHepática pelo vírus C. Paciente sem queixas\nespontâneas, nega queixas neurológicas. Nega\nhemorragia digestiva prévia. Ao exame físico, observada icterícia, ascite leve, ausência de\nflapping.\nNos exames já realizados na unidade básica, observado albumina 2,5g/dL, bilirrubina 4mg/dL, TAP\n7seg, endoscopia com varizes esofágicas de fino calibre. Sobre o caso, é correto afirmar:","options":{"A":"O tratamento antiviral não apresenta benefício para o caso em questão.","B":"Paciente pode ser classificado como Child-Pugh B.","C":"Existe indicação de profilaxia primária de sangramento por varizes esofágicas.","D":"Se for submetido à análise do líquido ascítico, seria observado GASA abaixo de 1,0."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-248910","number":"248910","sourceNumber":"248910","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à doença hepática gordurosa não alcoólica, é correto afirmar que:","options":{"A":"a maioria dos pacientes é assintomática","B":"na avaliação dos pacientes, as enzimas hepáticas alanina aminotransferase e aspartato\naminotransferase são bons marcadores de gravidade do dano da célula hepática","C":"ocorre exclusivamente em pacientes com excesso de peso corpóreo","D":"os medicamentos da classe das tiazolidinedionas (exemplo: metformina) são os de escolha para\no tratamento"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-248911","number":"248911","sourceNumber":"248911","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite é a causa mais comum de descompensação na cirrose hepática. Sobre a\nascite do paciente cirrótico e suas complicações, assinale a alternativa correta:","options":{"A":"bactérias Gram negativas (Escherichia coli e Klebsiella pneumoniae) e Gram positivas\n(Staphylococcus aureus) são os micro-organismos mais frequentemente isolados na peritonite\nbacteriana espontânea","B":"a ascite do paciente cirrótico se caracteriza pela presença de um gradiente de albumina\nsoroascite (GASA)>1,1g/dL e proteína total no líquido ascítico >2,5g/dL","C":"a ascite neutrocítica é caracterizada pela contagem de polimorfonucleares >250/mm3 e cultura\ndo líquido ascítico negativa. Deve ser tratada\ncomo peritonite bacteriana espontânea clássica","D":"pacientes cirróticos com ascite, febre e piora de função renal podem ser tratados de forma\nempírica para peritonite bacteriana espontânea sem a necessidade de paracentese diagnóstica"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249851","number":"249851","sourceNumber":"249851","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A colangite biliar primária é um processo inflamatório que acomete os ductos biliares\nintra-hepáticos, resultando na destruição dos mesmos e em fibrose, cirrose e insuficiência hepática.\nQual é o marcador sorológico mais importante para o diagnóstico desta doença?","options":{"A":"Antinúcleo.","B":"Antimitocôndria.","C":"Antimúsculo liso.","D":"Anti-LKM 1."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252744","number":"252744","sourceNumber":"252744","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A.L.M., 55 anos, sexo masculino, procura atendimento referindo escurecimento da pele,\ndores articulares, poliúria, polidipsia, atrofia testicular e icterícia. Ao exame físico,\napresenta-se com\nhepatomegalia a deformidades articulares. Exames laboratoriais mostram saturação de transferrina\nde 60% e ferritina de 2.500 ug/L. Em relação a essa doença, marque a alternativa CORRETA:","options":{"A":"Nessa doença, há acúmulo de ferro nos órgãos. O excesso de ferro ocorre principalmente por\nhemólise crônica.","B":"As primeiras manifestações clínicas dessa doença sempre aparecem precocemente, entre os 8\ne 10 anos de idade.","C":"A mutação mais comum dessa doença consiste em mutação no gene HFE, com substituição de\nácido histidina por ácido aspártico no códon 63 (H63D).","D":"Os familiares dos pacientes com essa doença devem ser rastreados com dosagem de ferritina e\nsaturação de transferrina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252745","number":"252745","sourceNumber":"252745","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente que se apresenta com doença hepática, neurológica e psiquiátrica e, ao\nexame físico, tem Anel de Kayser-Fleischer,\nprovavelmente possui acúmulo de\n\nno organismo.","options":{"A":"Zinco.","B":"Mercúrio.","C":"Cobre.","D":"Chumbo."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-229847","number":"229847","sourceNumber":"229847","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O sangramento digestivo alto por varizes esofágicas (VE) configura uma das\ncomplicações mais temidas da hipertensão\nportal como consequência da cirrose hepática. Entre as\nalternativas marque a que NÃO se enquadra neste contexto.","options":{"A":"A chance de ressangramento no paciente cirrótico pode alcançar números da ordem de 70%,\ncom mortalidade semelhante a do primeiro episódio.","B":"Betabloqueadores não seletivos podem ser utilizados de forma profilática em portadores de VE\nde alto risco para sangramento (médio ou\ngrosso calibre ou finas com pontos vermelhos recentes\ne/ou Child B ou C) reduzindo a chance do primeiro episódio.","C":"O uso de betabloqueadores não seletivos é bem consagrado na profilaxia secundária do\nsangramento por VE associado à ligadura elástica e tem grande indicação principalmente nos\nportadores de asma e DPOC.","D":"Pacientes com ascite volumosa ou refratária ou história de peritonite bacteriana espontânea,\nsegundo dados recentes na literatura, podem\nevoluir com piora do débito cardíaco quando\nassociado o uso de betabloqueadores não seletivos em altas doses, podendo desencadear\nsíndrome hepatorrenal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-249498","number":"249498","sourceNumber":"249498","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual o valor do gradiente albumina soro-ascite (GASA) indica a etiologia da ascite\ncomo hipertensão portal?","options":{"A":"> 1","B":"> 1,1","C":"< 1","D":"< 1,1"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-201664","number":"201664","sourceNumber":"201664","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente procedente de Barreiras-BA, de 22 anos, com história de aumento do volume\nabdominal há cerca de cinco anos. Nega etilismo, transfusões sanguíneas, uso de drogas ou outros\nmedicamentos. Relata ter tido um episódio de hemorragia digestiva alta, que foi controlada após\nmedidas clínicas há cerca de sessenta dias. No exame físico, apresenta abdome globoso, com\npiparote positivo e aranhas vasculares periumbilicais. Qual é a possível etiologia do sangramento\nneste paciente?","options":{"A":"Úlcera duodenal.","B":"Úlcera gástrica.","C":"Discrasia sanguínea.","D":"Ruptura de varizes esofagianas."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-201666","number":"201666","sourceNumber":"201666","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente procedente de Barreiras?BA, de 22 anos, com história de aumento do volume\nabdominal há cerca de cinco anos. Nega etilismo, transfusões sanguíneas, uso de drogas ou outros\nmedicamentos. Relata ter tido um episódio de hemorragia digestiva alta, que foi controlada após\nmedidas clínicas há cerca de sessenta dias. No exame físico, apresenta abdome globoso, com\npiparote positivo e aranhas vasculares periumbilicais. Caso fosse indicado um tratamento cirúrgico\neletivo para o paciente, qual seria o mais adequado?","options":{"A":"Gastrectomia parcial com vagotomia troncular.","B":"Anastomose da veia esplênica com a veia renal.","C":"Esqueletização do esôfago distal e estômago proximal.","D":"Ligadura dos ramos do nervo vago abaixo do ramo hepático."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-202671","number":"202671","sourceNumber":"202671","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite é uma complicação frequente no paciente com cirrose, e o seu aparecimento já\ntraduz um mau prognóstico, com uma mortalidade ao redor de 50% em três anos. Com relação à\nascite e suas complicações considera-se que:","options":{"A":"a realização da paracentese deve ser evitada quando há distúrbio de coagulação.","B":"o uso de betabloqueadores para prevenir a ascite refratária deve ser evitado em pacientes já\nportadores da doença.","C":"os diuréticos de alça são os de escolha para o tratamento das ascites, devido à sua potência.","D":"o tratamento na ascite tensa deve ser iniciado com paracentese terapêutica e expansão\nvolêmica com reposição de albumina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216566","number":"216566","sourceNumber":"216566","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A.N.A., 24 anos de idade, vai ao ambulatório de clínica médica por estar apresentando\nepisódios de astenia, icterícia e prurido\nintenso. Referia início do quadro há cerca de um ano.\n\nTrazia consigo exames que mostravam aumento de enzimas canaliculares e necrose hepatocitária.\nA hipótese diagnóstica principal a ser aventada\nneste caso clínico e o exame complementar que\ncorroboraria este diagnóstico são respectivamente:","options":{"A":"Colangite esclerosante primária - anticorpo anti-músculo liso.","B":"Hepatite auto-imune tipo I - FAN (fator anti-nuclear).","C":"Colangite biliar primária - anticorpo anti-mitocôndria.","D":"Hepatite anti-imune tipo II - anticorpo Anti-LKM-1."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216583","number":"216583","sourceNumber":"216583","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"J.O.S., 54 anos de idade, vai ao pronto socorro com quadro de hematêmese.\nApresentava também ascite, circulação\ncolateral, esplenomegalia e aranhas vasculares. Segundo a\nacompanhante, há uma semana encontrava-se confuso e desorientado. O paciente prontamente foi\nlevado ao box de emergência sendo estabilizado e transferido para a Unidade de Tratamento\nIntensivo. A despeito deste quadro clínico verfica-se que:","options":{"A":"a droga de escolha para o tratamento da hemorragia digestiva alta desse paciente é o\noctreotide.","B":"a causa da confusão mental prévia desse paciente era encefalopatia hepática, e a lactulose\npode ser instituída como tratamento.","C":"A paracentese deste líquido ascítico com gradiente de albumina soro-ascite menos que 1,1g/dL\npermite afirmar tratar-se de ascite provocada por hipertensão portal.","D":"a droga de escolha para o tratamento da ascite deste paciente é a furosemida, um potente\ndiurético de alça."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216646","number":"216646","sourceNumber":"216646","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"L.A., sexo feminino, é uma paciente de 14 anos de idade que foi ao ambulatório de\nclínica médica com queixa de anemia. Durante a\ninvestigação notou-se que a mesma apresentava\nalém da anemia, plaquetopenia e leucopenia. Foi encaminhada ao hematologista que realizou\nbiópsia de medula óssea e a mesma mostrou-se hipercelular sem quaisquer outras alterações.\n\nPossuía esplenomegalia, aumento de AST e ALT três vezes acima dos valores de referência e FAN\npositivo. Acerca do quadro citado, assinale verifica-se o seguinte:","options":{"A":"Trata-se de paciente com possível hipertensão portal devido a hepatite autoimune.","B":"A principal hipótese diagnóstica para o caso é leucemia linfocítica aguda.","C":"É necessário solicitar Coombs direto e indireto além de avaliar o nível de reticulócitos para\ndescartar anemia hemolítica.","D":"A hemocromatose hereditária é a principal hipótese diagnóstica."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-215463","number":"215463","sourceNumber":"215463","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em pacientes pediátricos, a hipertensão portal é uma importante causa de hemorragia\ndigestiva alta. Das alternativas abaixo, qual éa que contêm causas de hipertensão portal?","options":{"A":"Atresia de vias biliares, doença veno-oclusiva e síndrome de Buddi-Chiari.","B":"Doença veno-oclusiva, síndrome de Buddi-Chiari e púrpura de Henoch-Schonlein.","C":"Síndrome de Buddi-Chiari, púrpura de Henoch-Schonlein e atresia de vias biliares.","D":"Púrpura de Henoch-Schonlein, atresia de vias biliares e doença veno-oclusiva."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-215396","number":"215396","sourceNumber":"215396","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A rejeição celular aguda incide em 30 a 50% dos casos de transplante hepático\nortotópico e é mais frequente durante o\nprimeiro mês após este procedimento, podendo aparecer\nem qualquer outro período do seguimento do doente. Assinale a alternativa INCORRETA.","options":{"A":"Manifesta-se clinicamente por mal-estar, febre, icterícia, dor abdominal e ascite.","B":"Os exames laboratoriais mostram aumento do número de leucócitos, das transaminases\nhepáticas e das bilirrubinas.","C":"O diagnóstico definitivo só é comprovado pela análise histológica da biópsia hepática, que avalia\na presença de endotelialite, infiltrado\nlinfoplasmocitário nos espaços-porta e lesão dos ductos\nbiliares e classifica a rejeição em leve, moderada ou grave.","D":"A bile, quando monitorizada, torna-se mais espessa e ocorre um aumento no volume diário."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-205582","number":"205582","sourceNumber":"205582","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A doença gordurosa não alcoólica do fígado se refere a um grande espectro de\ndoenças hepáticas. Aponte a afirmação que NÃO faz\nparte dos conceitos.","options":{"A":"Pode ser caracterizada por infiltração gordurosa em mais de 5% do tecido hepático, com ou sem\ninflamação leve (esteatose hepática), inflamação hepática associada à presença de gordura (NASH\nou esteato-hepatite não alcoólica), esteatose/necroinflamação, cirrose hepática e carcinoma\nhepatocelular.","B":"Entre as causas de doença gordurosa não alcoólica, destacam-se distúrbios metabólicos\n(obesidade, DM, dislipidemias), medicamentos\n(antibióticos, ARV, glicocorticoides, estrógenos,\ntamoxifeno), hepatite crônica C e nutrição parenteral.","C":"Os fatores de risco para desenvolvimento da NASH incluem obesidade, DM tipo 2, resistência à\ninsulina, hipertrigliceridemia, mas não à perda rápida de peso, como nas cirurgias bariátricas.","D":"As pessoas vivendo com HIV-PVHIV frequentemente apresentam distúrbios metabólicos, tais\ncomo resistência à insulina e lipodistrofia,\ngeralmente associados à presença de NASH. Além disso,\nalguns ARV, particularmente os ITRN, causam esteatose hepática."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-178777","number":"178777","sourceNumber":"178777","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São causas de ascite, exceto:","options":{"A":"síndrome nefrótica.","B":"síndrome de Tietze.","C":"lúpus eritematoso sistêmico.","D":"síndrome da hiperestimulação ovariana.","E":"hipotireoidismo."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174144","number":"174144","sourceNumber":"174144","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ilustração a seguir refere-se à alternativa técnica para o tratamento da hipertensão\nportal. A operação ilustrada representa uma:","options":{"A":"Anastomose portossistêmica seletiva, com pouca repercussão no gradiente pressórico portal e\napropriada a situações eletivas.","B":"Desconexão ázigo-portal, com grande repercussão no gradiente pressórico portal e apropriada a\nsituações emergenciais.","C":"Anastomose portossistêmica não seletiva, com grande repercussão no gradiente pressórico\nportal e apropriada a situações emergenciais.","D":"Desconexão ázigo-portal, com pouca repercussão no gradiente pressórico portal e apropriada a\nsituações eletivas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/174144.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-182454","number":"182454","sourceNumber":"182454","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a Hemorragia Digestiva Alta (HDA) varicosa em pacientes cirróticos, assinale a\nalternativa correta:","options":{"A":"o tamponamento com balão de Sengstaken-Blakemore (que deve ser mantido insuflado por, no\nmáximo, 6 horas) é empregado, apenas, nos hemodinamicamente estáveis quando não se dispõe\nde endoscopia de urgência","B":"o TIPS (shunt portossistêmico intra-hepático transjugular) é um procedimento que envolve a\ncriação de um canal entre a veia porta e a veia cava inferior por meio de uma prótese vascular que\npassa anteriormente ao fígado","C":"o TIPS pode ser indicado na vigência de HDA grave e refratária ao tratamento endoscópico, com\nbons resultados em interromper o sangramento.\nEntretanto, podem ocorrer complicações como\nencefalopatia portossistêmica e estenose/trombose da prótese","D":"o uso de terlipressina na HDA varicosa está em desuso, devido aos seus maus resultados em\ncontrolar o sangramento por varizes esofagogástricas em cirróticos. Atualmente são preferidas a\nnoradrenalina e a octreotida para vasoconstrição esplâncnica e consequente redução da pressão\nnas varizes"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-182473","number":"182473","sourceNumber":"182473","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quais das situações a seguir são caracterizadas como situações especiais para a\ninclusão em lista de transplante de fígado:","options":{"A":"hemangioendotelioma epitelioide de fígado irressecável, síndrome hepatopulmonar e síndrome\nhepatorrenal","B":"síndrome hepatopulmonar, hemangioendotelioma epitelioide de fígado irressecável e\ncolangiocarcinoma irressecável","C":"polineuropatia amiloidótica familiar, trombose de artéria hepática pós--transplante de fígado e\nmetástase de neoplasia de cólon irressecável","D":"adenomatosa múltipla bilobar extensa irressecável, trombose de artéria hepática pós-\ntransplante de fígado e síndrome hepatopulmonar"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-178791","number":"178791","sourceNumber":"178791","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual, dos seguintes agentes, não está relacionado com lesão hepatocelular nas\nhepatites medicamentosas?","options":{"A":"Paracetamol.","B":"Isoniazida.","C":"Halotano.","D":"Eritromicina.","E":"Fenitoína."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-186463","number":"186463","sourceNumber":"186463","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hemorragia digestiva alta é um problema clínico comum e grave. No tratamento de\ncirróticos com varizes de esôfago, existe alta letalidade. Além da endoscopia emergencial para\nescleroterapia e/ou ligadura elástica, na recorrência da hemorragia, ou falha no tratamento inicial,\npode-se utilizar que outra opção terapêutica?","options":{"A":"TIPS (derivação transjugular intra-hepática portossistêmica).","B":"Transplante hepático.","C":"Hemodiálise transperitoneal.","D":"Apenas betabloqueador oral."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174090","number":"174090","sourceNumber":"174090","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"De acordo com o Consenso de Baveno VI, para tratamento de hipertensão portal,","options":{"A":"a abstinência alcoólica deve ser estimulada em todos os pacientes com cirrosse hepática.","B":"a escleroterapia das varizes esofágicas está indicada para a profilaxia primária da hemorragia\nvaricosa em pacientes com Child-Pugh C.","C":"a obesidade é um indicador de bom prognóstico, uma vez que reflete o bom estado nutricional\ndo paciente.","D":"o uso de betabloqueadores está indicado para prevenir a formação das varizes esofagianas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-186507","number":"186507","sourceNumber":"186507","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, 34 anos, procura atendimento com quadro de icterícia,\nfadiga, mal estar, anorexia e edema de\nmembros inferiores. Exames laboratoriais mostram aumento\ndas amonitransferases e discreto aumento das bilirrubinas. Diante da suspeita de hepatite\nautoimune, os seguintes acados são caracteristicos:","options":{"A":"Aticorpo antimitocôndria positivo e aumento dos níveis séricos de creatinofosfoquinase.","B":"Hipergamaglobulinemia e anticorpo antimúsculo liso positivo.","C":"Aumento dos níveis séricos de albumina e anticorpo antifosfolípide positivo.","D":"Anticorpo antiedomísio positivo e redução dos níveis séricos de homocisteína."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-186478","number":"186478","sourceNumber":"186478","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"J.L., 45 anos, sexo masculino, motorista, casado, procura atendimento médico referindo\nlabilidade emocional, irritabilidade, disartria e tremor de extremidades. Consulta com\noftalmologista\nrecentemente evidenciou a presença de anéis de Kayser-Fleischer. Dentre os exames abaixo, qual\né o mais importante para o diagnóstico dessa doença:","options":{"A":"Ferritina.","B":"Cobre urinário.","C":"Zinco sérico.","D":"Angiografia cerebral."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187520","number":"187520","sourceNumber":"187520","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente admitido com ascite, a paracentese evidenciou um gradiente soro-ascite de\nalbumina de 1,2 g/dl, Este achado é compatível com","options":{"A":"insuficiência cardíaca congestiva.","B":"carcinomatose peritoneal.","C":"tuberculose peritoneal.","D":"síndrome nefrótica."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-178820","number":"178820","sourceNumber":"178820","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma criança de 7 anos foi levada ao pronto-socorro pela avó por ter ingerido 20\ncomprimidos de acetaminofeno (fármaco comprado nos Estados Unidos). O antídoto para\nintoxicação por acetaminofeno é:","options":{"A":"vitamina K.","B":"atropina.","C":"clonidina.","D":"naloxona.","E":"acetilcesteína."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174524","number":"174524","sourceNumber":"174524","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Segundo a classificação de Child-Pugh, um paciente com bilirrubina total de 3mg/dL,\nalbumina de 2,9 g/dL, tempo de protrombina de 5 segundos aumentados, ascite leve e sem\nencefalopatia, corresponde a:","options":{"A":"B ? 7 pontos.","B":"B ? 8 pontos.","C":"B ? 9 pontos.","D":"C ? 10 pontos."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174421","number":"174421","sourceNumber":"174421","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O escore MELD é um sistema de priorização de pacientes no transplante de fígado.\nQuais são as variáveis para o cálculo deste escore?","options":{"A":"Albumina, Creatinina e INR.","B":"Albumina, INR e Bilirrubinas.","C":"Creatinina, INR e Bilirrubinas.","D":"Fibrinogênio, Bilirrubina e Creatinina."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174445","number":"174445","sourceNumber":"174445","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São causas de gradiente de albumina soroascite elevadas, EXCETO:","options":{"A":"Cirrose alcoólica.","B":"Metástase hepática.","C":"Síndrome de Budd-Chiari.","D":"Ascite pancreática."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187611","number":"187611","sourceNumber":"187611","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com classificação B de Child-Pugh, com quadro de varizes esofágicas com\nsangramento prévio há 1 ano deu entrada no Pronto Socorro com novo sangramento em grande\nquantidade no domicílio. À admissão encontrava-se hipotenso, contudo sem novos vômitos.\n\nConduta mais adequada imediata","options":{"A":"ressuscitação volêmica, hemograma, octreotide e endoscopia se novo sangramento.","B":"ressuscitação volêmica, hemograma, octreotide e endoscopia de urgência com ligadura de\nvarize sangrante.","C":"ressuscitação volêmica, hemograma , octreotide e balão de Sengstaken-Blakemore.","D":"ressuscitação volêmica, hemograma , octreotide endoscopia de urgência com escleroterapia e\nbalão de Sengstaken-Blakemore independente de persistência de sangramento."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183317","number":"183317","sourceNumber":"183317","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Descrita por Kinnear Wilson, caracteriza-se por ter uma herança autossômica\nrecessiva, a Doença de Wilson (DW) é uma doença genética com manifestações clínicas\nconsequentes a um defeito no metabolismo do cobre. Sendo assim, assinale a alternativa\nCORRETA:","options":{"A":"Quando a capacidade de acúmulo de cobre no fígado é excedida ou quando há dano\nhepatocelular, ocorre liberação de cobre na\n\ncirculação, elevando-se o nível de cobre sérico não ligado à ceruloplasmina. Este cobre circulante\ndeposita-se em tecidos extra-hepáticos. Um dos principais locais de deposição é o cérebro,\ncausando dano neuronal e sendo responsável pelas manifestações neurológicas e psiquiátricas da\nDW.","B":"Somente quando a capacidade de acúmulo de cobre no fígado é excedida ocorre liberação de\ncobre na circulação, elevando-se o nível de cobre sérico não ligado à ceruloplasmina. Este cobre\ncirculante deposita-se em tecidos extra-hepáticos. Um dos principais locais de deposição é o\ncérebro, causando dano neuronal e sendo responsável pelas manifestações neurológicas e\npsiquiátricas da DW.","C":"Somente quando há dano hepatocelular, ocorre liberação de cobre na circulação, elevando-se o\nnível de cobre sérico não ligado à ceruloplasmina. Este cobre circulante deposita-se em tecidos\nextra-hepáticos. Um dos principais locais de deposição é o cérebro, causando dano neuronal e\nsendo responsável pelas manifestações neurológicas e psiquiátricas da DW.","D":"Quando a capacidade de acúmulo de cobre no fígado é excedida ou quando há dano\nhepatocelular, porém não ocorre liberação\n\nde cobre na circulação, elevando-se o nível de cobre sérico ligado à ceruloplasmina. Este cobre\ncirculante deposita-se em tecidos extra-hepáticos. Um dos principais locais de deposição é o\ncérebro, causando dano neuronal e sendo responsável pelas manifestações neurológicas e\npsiquiátricas da DW."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183344","number":"183344","sourceNumber":"183344","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Doença de Wilson (DW) é uma doença genética com manifestações clínicas\nconsequentes a um defeito no metabolismo do\ncobre, o que leva a seu acúmulo. Está INCORRETO\nque:","options":{"A":"O nível circulante desta gliproteína nos pacientes com DW está aumentado.","B":"A ceruloplasmina é uma glicoproteína sintetizada no fígado.","C":"A ceruloplasmina contém 6 átomos de cobre por molécula.","D":"O defeito no transporte intracelular acarreta diminuição na incorporação de cobre a nível\ncirculante desta glicoproteína nos pacientes com DW com reduz de ceruloplasmina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-157424","number":"157424","sourceNumber":"157424","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 43 anos, com cirrose hepática alcoólica, procurou você no\nambulatório para tratamento de hérnia\numbilical. Encontra-se sem sinais de encefalopatia, ascite\nleve, bilirrubina 2 mg/dL; albumina 2,5 g/L; INR1,2. Segundo o sistema de pontuação Child-Pugh,\nassinale a associação CORRETA entre a pontuação aplicada para esse paciente e os respectivos\níndices de mortalidade:","options":{"A":"6 pontos ? Child A ? índice de mortalidade de 10%.","B":"9 pontos ? Child B ? índice de mortalidade de 31%.","C":"10 pontos ? Child B ? índice de mortalidade de 31%.","D":"15 pontos ? Child C ? índice de mortalidade de 76%."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-150753","number":"150753","sourceNumber":"150753","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão portal e as complicações dela decorrentes são importantes causas de\nóbito em pacientes com cirrose hepática. De\nacordo com o Consenso de Baveno VI, no tratamento\nde hipertensão portal:","options":{"A":"A abstinência do álcool deve ser incentivada em todos os pacientes com cirrose,\nindependentemente da sua etiologia.","B":"O uso de betabloqueadores não seletivos são recomendados para a prevenção do surgimento\nde varizes esofágicas.","C":"O carvedilol é mais eficaz na redução da hipertensão portal em cirróticos que os tradicionais\nbetabloqueadores não seletivos (propranolol), sendo a droga de escolha na prevenção de um novo\nsangramento varicoso nesses pacientes.","D":"A escleroterapia das varizes esofágicas é a opção de escolha na profilaxia do primeiro\nsangramento em pacientes com contraindicação ou intolerância ao uso de betabloqueadores."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-127090","number":"127090","sourceNumber":"127090","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 57 anos deu entrada no serviço de emergência com quadro de\nhemorragia digestiva alta, devido a sangramento\nde varizes gástricas. Questionado sobre queixas\nprévias, relatou ter sofrido alguns episódios de pancreatite grave secundária à ingestão alcoólica.\nDiante desse quadro, o provável fator relacionado ao desenvolvimento das varizes foi a trombose\nda veia:","options":{"A":"Porta.","B":"Esplênica.","C":"Gastroepiploica.","D":"Gástrica esquerda."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-127702","number":"127702","sourceNumber":"127702","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"<p>Uma paciente de 54 anos chega ao ambulatório de hepatologia apresentando\nicterícia, colúria, acolia fecal e prurido\nintenso generalizado há cerca de um ano. Traz consigo uma\nultrassonografia evidenciando múltiplos cálculos na vesícula biliar, sem dilatação de vias biliares,\ncom fígado de aspecto ecográfico normal, além dos seguintes exames laboratoriais: AST: 67; ALT:\n79; Gama GT: 950; Fosfatase alcalina: 1120; Bilirrubina total: 7,2 (BD: 5,9 Bl: 1,3); HbsAg não\nreagente; Anti-HBc total reagente; Anti-HBs reagente; Anti-HCV não reagente; FAN negativo;\nAntimitocôndrias reagente 1/640. Diante deste quadro, qual é o diagnóstico mais provável ?</p>","options":{"A":"Colelitíase com coledocolitíase.","B":"Hepatite crônica pelo vírus B.","C":"Cirrose biliar primária.","D":"Hepatite autoimune."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-138612","number":"138612","sourceNumber":"138612","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O conhecimento de fisiopatologia nos auxilia na abordagem terapêutica de todas as\ndoenças. Assim, considerando a fisiopatologia da hipertensão portal, qual ação seria mais racional\npara controlar a hemorragia digestiva alta?","options":{"A":"Vasoconstrição esplâncnica.","B":"Vasodilatação esplâncnica.","C":"Vasoconstrição periférica.","D":"Vasodilatação periférica."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-111395","number":"111395","sourceNumber":"111395","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre hepatopatias, assinale a alternativa correta:","options":{"A":"A hemocromatose é uma doença metabólica que causa acúmulo de ferro no organismo,\nespecialmente no fígado, coração, pâncreas e\noutros. O acumulo de ferro se dá sob a forma de\nhemossiderina e ferritina. Pode levar à diabetes, escurecimento da pele, cirrose hepática.\nRaramente apresenta hepatomegalia e tem o hepatocarcinoma como sua principal complicação.","B":"Doença de Wilson caracteriza por depósito de cobre hepático, que se apresenta de forma\nbranda até quadros graves de insuficiência hepática aguda. Dentre as principais ferramentas\ndiagnósticas estão a presença do Anel de Kayser-Fleischer e baixo nível de ceruloplasmina.","C":"Um paciente com Ascite moderada, Encefalopatia grau 2, Albumina de 3,0 g/dl, bilirubina < 2,0\ng/dl e Tempo de Protrombina < 4 seg está classificado com Child-Pugh C.","D":"Na Hepatite pelo Vírus C o marcador de certeza diagnóstica é o anti-HCV.","E":"Todas as alternativas estão incorretas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-109339","number":"109339","sourceNumber":"109339","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão portal pode ter diversas etiologias. Levando-se em conta a fisiopatologia\nda doença e a localização anatômica da\nresistência ao fluxo portal, qual das etiologias a seguir é\nresponsável por hipertensão portal intra-hepática, pré-sinusoidal?","options":{"A":"Trombose da veia porta.","B":"Síndrome de Budd-Chiari.","C":"Cirrose alcoólica.","D":"Esquistossomose."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-112374","number":"112374","sourceNumber":"112374","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de 42 anos, dá entrada em pronto-socorro apresentando\nicterícia há três dias, prurido generalizado,\ndor e desconforto abdominal, edema de MMII e, nas\núltimas 24 horas, desenvolvimento de quadro de bradilalia e agitação psicomotora. Familiares\nrelataram antecedente de uso de drogas endovenosas e ingesta de cerca de 200 gramas de\netanol/dia há 20 anos. Exames laboratoriais mostraram: Hb = 11,2; leucócitos totais = 16.800;\nplaquetas = 105.000; bilirrubina total = 9,8 (BD = 6,0); AST = 510; ALT = 80; gama GT = 1.240;\nanti-HCV negativo; anti-HIV negativo; anti-HAV IgG reagente; HBsAG negativo; anti-HBc IgG\nreagente; anti-HBs > 1.000. Qual é a principal hipótese diagnóstica e qual a medicação\nrecomendada?","options":{"A":"Hepatite A aguda e interferon peguilado.","B":"Hepatite B crônica agudizada e lamivudina.","C":"Colestase extra-hepática e ácido ursodesoxicólico.","D":"Hepatite alcoólica e corticosteroide."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-111410","number":"111410","sourceNumber":"111410","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"As condições abaixo cursam com dosagem sérica de cobre elevada, exceto:","options":{"A":"Leucemia crônica.","B":"Hipertireoidismo.","C":"Doença de Wilson.","D":"Anemia perniciosa.","E":"Lúpus eritematoso sistêmico."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-109350","number":"109350","sourceNumber":"109350","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na doença de Wilson:","options":{"A":"O sinal do anel de Kayser-Fleischer é patognomônico e quando presente indica\ncomprometimento neurológico.","B":"A presença de sintomas psiquiátricos é rara e, quando presentes, devem indicar uma gravidade\nmaior da doença, com pior prognóstico.","C":"O acúmulo de ferro está presente nos gânglios da base, levando a sintomas parkinsonianos e\nsendo responsável também pelo comportamento\nhepático.","D":"O comprometimento sistêmico de rins, ossos, coração e glândulas antecede os sintomas\nneurológicos e hepáticos em até cinco anos."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-84389","number":"84389","sourceNumber":"84389","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Cite o CORRETO dos abaixo que indica doença hepática por abuso de álcool.","options":{"A":"Relação TGO:TGP = 2.1.","B":"Baixos níveis de ureia.","C":"Glicemia alta acima de 140 mg.","D":"Trombocitose.","E":"Microcitose das hemácias."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-83818","number":"83818","sourceNumber":"83818","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual é o principal constituinte dos cálculos primários de colédoco?","options":{"A":"Bilirrubina","B":"Bilirrubinato de cálcio","C":"Colesterol","D":"Lecitina","E":"Oxalato de cálcio"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-48318","number":"48318","sourceNumber":"48318","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dentre as assertivas abaixo, a que não causa cirrose e/ou hepatopatia crônica é:","options":{"A":"Hemocromatose.","B":"Esquistossomose.","C":"Doença de Wilson.","D":"Mononucleose infecciosa.","E":"Deficiência de alfa-1-antitripsina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-51037","number":"51037","sourceNumber":"51037","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Carlos, 7 anos, foi medicado pelos pais com ácido acetilsalicílico, no intuito de reduzir\nsua febre. Ele evoluiu com vômitos e alteração\ndo estado mental. Levado ao hospital, desenvolveu\nconvulsões seguidas de coma. O que se deve esperar da biópsia hepática?","options":{"A":"Fibrose difusa com áreas de regeneração.","B":"Depósitos de hemossiderina.","C":"Necrose hepatocitária.","D":"Esteatose microvesicular.","E":"Corpos de Mallory."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-48475","number":"48475","sourceNumber":"48475","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A complicação mais frequente no uso de anestésicos inalatórios halogenados\n(halotano) é:","options":{"A":"Hepatite.","B":"Arritmia cardíaca.","C":"Hipertensão arterial.","D":"Insuficiência renal aguda.","E":"Insuficiência cardíaca."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-27159","number":"27159","sourceNumber":"27159","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No diagnóstico diferencial entre Esteato-Hepatite Não Alcoólica (EHNA) e a hepatite\nalcoólica, do ponto de vista laboratorial, podemos considerar como sugestivo da doença não\nalcoólica:","options":{"A":"Níveis elevados de gamaglutamiltransferase.","B":"Níveis baixos de ferritina.","C":"Índice AST/ALT inferior a 1.","D":"Hemograma mostrando um aumento do volume corpuscular médio das hemácias.","E":"Maior grau de esteatose hepática."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-273986","number":"273986","sourceNumber":"273986","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 48 anos chega ao pronto-socorro inconsciente, com hemorragia digestiva\nalta. Mantém pressão arterial normal e taquicardia\n(110 batimentos por minuto). Detectada\npresença de ascite e esplenomegalia. Além da reposição volêmica, as duas classes de\nmedicamentos que devem ser utilizados nessa situação são:","options":{"A":"Inibidor de bomba de prótons e vasoconstritor sistêmico.","B":"Inibidor de bomba de prótons e betabloqueador não seletivo.","C":"Vasoconstritor esplâncnico e antibiótico.","D":"Vasoconstritor sistêmico e betabloqueador não seletivo."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216424","number":"216424","sourceNumber":"216424","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 30 anos apresentando quadro clínico compatível com cirrose hepática.\nApresenta ainda anéis de Kayser-Fleischer. Qual o exame de rastreio para a PRINCIPAL\nHIPÓTESE diagnóstica de base desse paciente?","options":{"A":"Ferritina.","B":"Antimitocôndria.","C":"Antimúsculo liso.","D":"Ceruloplasmina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216276","number":"216276","sourceNumber":"216276","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 62 anos de idade, etilista, internado para avaliação de ascite, apresenta\nalbumina sérica de 3,8 g/dl (N: 3,5?4,7 g/dl),\nproteína total sérica de 6,8 g/dl (N: 6?8 g/dl), albumina\ndo líquido ascítico em 2,2 g/dl e proteína total do líquido ascítico em 3,2 g/dl (N: até 2,5 g/dl).\nA\netiologia de ascite MAIS COMPATÍVEL com esses valores nesse contexto clínico é:","options":{"A":"Insuficiência hepática crônica.","B":"Síndrome nefrótica.","C":"Insuficiência cardíaca congestiva.","D":"Tuberculose peritoneal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-176262","number":"176262","sourceNumber":"176262","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a doença hepática alcoólica, é correto afirmar, EXCETO:","options":{"A":"A esteatose pode ser apenas um achado de imagem ou pode vir associada a leve aumento de\ntransaminases. Em geral, a AST não ultrapassa o valor de 300 U/L e habitualmente é maior do que\na ALT em pelo menos 2x.","B":"A hepatite pode apresentar-se agudamente com quadro de febre, dor em quadrante superior\ndireito e icterícia, fazendo diagnóstico\ndiferencial com doenças biliares.","C":"Dentre as opções farmacológicas para o tratamento da esteato-hepatite, a vitamina E e a\nmetformina têm se mostrado como as mais promissoras.","D":"A hepatite pode apresentar-se agudamente com esplenomegalia, ascite, febre e encefalopatia,\nfazendo diagnóstico diferencial com a peritonite\nbacteriana espontânea do cirrótico.","E":"A biópsia hepática pode demonstrar macrovesículas de gordura e, em pacientes com hepatite,\ninfiltrado polimorfonuclear, corpúsculos de Mallory e fibrose perivenular e perissinusoidal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-155290","number":"155290","sourceNumber":"155290","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação ao diagnóstico diferencial de ascite, assinale a alternativa INCORRETA:","options":{"A":"O achado clínico de maior sensibilidade para o diagnóstico da ascite parece ser a presença de\nmacicez móvel nos flancos, que consegue detectar ascite em torno de 1,5 litros, sendo esse\nachado geralmente mais útil do que piparote e semicírculo de Skoda.","B":"A ascite era anteriormente classificada como transudato ou como exsudato baseada na\nconcentração total de proteínas do líquido\nascítico menor ou maior que 2,5 g/dl, respectivamente.\nAtualmente é preferencialmente classificada como decorrente ou não de hipertensão portal\nbaseada no GASA maior ou menor que 1,1 g/dl, respectivamente.","C":"São indicações de paracentese diagnóstica em pacientes com ascite: encefalopatia hepática,\npiora da função renal, hemorragia digestiva,\ndor abdominal e febre.","D":"A presença de coagulopatia não tratada é contraindicação absoluta à paracentese.","E":"Neoplasia é a etiologia mais comum de ascite exsudativa."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-105668","number":"105668","sourceNumber":"105668","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente cirrótico por vírus B, de 56 anos, está internado na enfermaria de\ngastroenterologia com descompensação da ascite e edema de membros inferiores. Não há sinais\nde encefalopatia hepática e, a análise do líquido ascítico na admissão, há 3 dias, mostrou 56\npolimorfonucleares/ml. O GASA é de 1,8 g/dl. O paciente está em uso de furosemida 80 mg/d e\nespironalactona 100 mg/d. Na visita de hoje, está orientado e sem desconforto respiratório. Desde\na internação, o paciente perdeu 200 g de peso. Laboratório da manhã de hoje mostrou: Ureia = 32\nmg/dl; Creatinina = 0,9 mg/dl; Sódio = 135 mEq/L; Potássio = 3,2 mEq/L. Com relação ao manejo\nda ascite, a melhor conduta hoje para esse paciente é:","options":{"A":"Paracentese de alívio.","B":"Aumentar espironolactona.","C":"Suspender diuréticos.","D":"Aumentar furosemida.","E":"Reduzir furosemida."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-28271","number":"28271","sourceNumber":"28271","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O consumo excessivo de álcool é associado às lesões hepáticas agudas e crônicas.\nAcerca da hepatite alcoólica, assinale a\nalternativa INCORRETA:","options":{"A":"A hepatite alcoólica é uma síndrome clínica de icterícia, insuficiência hepática que geralmente\nocorre após décadas de uso pesado de álcool\n(ingestão média, aproximadamente 100 g/dia).","B":"A combinação de aspartato aminotransferase elevada (mas < 300 IU/ml) e razão AST/ALT maior\nque 2, bilirrubina total maior que 5 mg/dl, INR elevada, neutrofilia em pacientes com ascite e\nhistória\nde uso pesado de álcool é indicativa de hepatite alcoólica.","C":"O aumento dos níveis de creatinina sérica é um sinal ominoso, pois indica o estabelecimento da\nsíndrome hepatorrenal.","D":"No exame histopatológico, os corpúsculos de Mallory são patognomônicos da hepatite alcoólica,\nnão ocorrendo, por exemplo, na esteato-hepatite não\nalcoólica (NASH) que faz diagnóstico\ndiferencial com a hepatite alcoólica.","E":"A abstinência imediata e para toda a vida do uso do álcool é essencial para prevenir a\nprogressão da hepatite alcoólica."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-342383","number":"342383","sourceNumber":"342383","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O melhor fator para avaliar a reserva funcional hepática é:","options":{"A":"Albumina.","B":"Aspartato aminotransferase.","C":"Gamaglutamiltranspeptidase.","D":"Tempo de protrombina.","E":"Fosfatase alcalina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-342397","number":"342397","sourceNumber":"342397","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na hepatopatia alcoólica, apesar de não ser específico, sugereetilismo ativo:","options":{"A":"AST/ALT >2","B":"Macrocitose","C":"Aumento de Gama-GT","D":"Neutrófilos hipersegmentados","E":"Bilirrubina indireta > bilirrubina direta"},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-308641","number":"308641","sourceNumber":"308641","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a síndrome de BUDD-CHIARI é INCORRETO afirmar:","options":{"A":"Apresenta líquido ascítico com gradiente de albumina soro-ascite > 1,1.","B":"Costuma evoluir de forma crônica.","C":"Apresenta atrofia do lobo caudado do fígado em exames de imagem.","D":"Caracteriza-se pela obstrução ao fluxo venoso hepático e desenvolve.","E":"A dor abdominal, ascite e hepatoesplenomegalia são os achados mais frequentes."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-311531","number":"311531","sourceNumber":"311531","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Menino de 2 anos deu entrada no pronto-socorro após ter ingerido um frasco de\nparacetamol. O pediatra de plantão deverá estar atento para o risco de a criança apresentar:","options":{"A":"Sinais de hepatotoxicidade.","B":"Hemólise maciça.","C":"Depressão respiratória.","D":"Coma.","E":"Sintomas de liberação extrapiramidal."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-281504","number":"281504","sourceNumber":"281504","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual medida farmacológica no paciente com hemorragia digestiva alta varicosa tem\nimpacto na redução de novo sangramento e que pode impactar em redução de mortalidade?","options":{"A":"Uso de terlipressina EV.","B":"Uso de octreotide EV.","C":"Uso de vasopressina EV.","D":"Uso de dopamina EV.","E":"Uso de adrenalina IM."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252364","number":"252364","sourceNumber":"252364","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São consideradas contraindicações relativas dos transplantes hepáticos:","options":{"A":"Doença cardiopulmonar avançada e obesidade mórbida","B":"Doença maligna extra-hepática não tratada e desnutrição grave","C":"Sorologia positiva para HIV e alcoolismo ativo","D":"Tumores hepáticos metastáticos e idade acima de 70 anos","E":"Alcoolismo ativo e infecção ativa extra-hepática não tratada"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-244661","number":"244661","sourceNumber":"244661","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 57 anos de idade com ascite de grande volume, ausência de trombo na veia\nhepática ou massa hepática. Realizou paracentese diagnostica e de alívio, com retirada de 4,5 L de\nlíquido seroso do abdome. Em seguida, são apresentados os resultados laboratoriais dos exames\ndo soro e líquido ascítico do paciente. Soro: sódio 135 meq/dL creatinina 1,15 mg/dL albumina 3,65\ng/dL bilirrubina 4,1 mg/dL. Líquido ascítico: albumina 1,1 g/dL; proteína 0,9 g/dL. Qual das\nseguintes condições é a causa mais provável de ascite?","options":{"A":"Cirrose","B":"Síndrome nefrótica","C":"Infarto intestinal","D":"Carcinomatose intraperitoneal","E":"Tuberculose"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-244676","number":"244676","sourceNumber":"244676","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A veia porta fornece cerca de 75% do fluxo sanguíneo hepático. Ela se forma atrás do\npâncreas, mais comumente, pela confluência da veia mesentérica:","options":{"A":"Inferior e da veia esplênica.","B":"Superior e da veia esplênica.","C":"Superior e da veia pancreática inferior.","D":"Inferior e da veia pancreática inferior.","E":"Superior e da veia mesentérica inferior."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-218058","number":"218058","sourceNumber":"218058","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual dos seguintes casos tem indicação formal para realização de transplante hepático\nconforme legislação brasileira vigente?","options":{"A":"Paciente com CHC de 5,5 cm, no segmento II.","B":"Paciente com CHC de 4,5 cm, no segmento VIII, com invasão da veia hepática direita.","C":"Paciente com carcinoma fibrolamelar irressecável, mas com 1 lesão metastática pulmonar\nressecável.","D":"Paciente com colangiocarcinoma hilar de 2 cm, estendendo-se para ducto hepático direito, sem\nacometimento vascular.","E":"Paciente com três lesões compatíveis com CHC no lobo hepático direito, sendo que a maior\nmede 2,8 cm."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-203302","number":"203302","sourceNumber":"203302","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Atualmente não tem sido indicação para transplante hepático a seguinte condição:","options":{"A":"cirrose alcoólica com insuficiência hepática","B":"infecção por hepatite C","C":"esteatose com insuficiência hepática","D":"carcinoma hepatocelular","E":"câncer de cólon metastático"},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-175024","number":"175024","sourceNumber":"175024","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"No exame laboratorial de um paciente com ascite foi encontrado um GASA (gradiente\nsoro-ascite) > 1,1. Assinale a opção em que o exame solicitado NÃO se aplica a investigação\ndiagnóstica desse caso.","options":{"A":"ADA (adenosina deaminase).","B":"HBsAG.","C":"Ecocardiograma.","D":"Gama GT (Gamaglutamiltransferase).","E":"Ultrassonagrafia Doppler de abdome."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-177521","number":"177521","sourceNumber":"177521","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A escala de MELD (Model for End-Stage Liver Disease) é um sistema de pontuação\npara avaliar a gravidade da doença hepática\ncrônica. Muito utilizado para priorizar alocação de\npacientes candidatos ao transplante hepático. É calculado numa fórmula que avalia as\nconcentrações de:","options":{"A":"Bilirrubina, creatinina e INR","B":"Bilirrubina, albumina e INR","C":"Albumina, DHL e TAP","D":"Bilirrubina, albumina, TAP","E":"Albumina, INR, ascite e encefalopatia hepática"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-175078","number":"175078","sourceNumber":"175078","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Peritonite Bacteriana Espontânea (PBE) é uma das principais complicações do\npaciente cirrótico com ascite, sendo importante\nfator de morbidade e mortalidade nessa população.\nAssinale a opção que contém o resultado de líquido ascítico que provavelmente se encontra frente\na um paciente com diagnóstico de PBE.","options":{"A":"Glicose acima de 50 mg/dl; neutrófilos < 250 células; LDH > 500; proteínas > 1 g/dl.","B":"Glicose acima de 50 mg/dl; neutrófilos > 250 células; LDH < 500; proteínas < 1 g/dl.","C":"Glicose acima de 50 mg/dl; neutrófilos < 250 células; LDH< 500; proteínas > 1 g/dl.","D":"Glicose abaixo de 50 mg/dl; neutrófilos > 250 células; LDH > 500; proteínas > 1 g/dl.","E":"Glicose abaixo de 50 mg/dl; neutrófilos < 250 células; LDH < 500; proteínas > 1 g/dl."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-177534","number":"177534","sourceNumber":"177534","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 28 anos procura atendimento médico com quadro de edema de membros\ninferiores, notado nas últimas semanas. Refere apresentar déficit de disposição para atividades do\ndia-a-dia ao longo dos últimos 2 ou 3 anos, bem como libido reduzida. Ao exame, chama atenção\numa hiperpigmentação cutânea, notadamente, em face, pescoço e dorso das mãos, bem como\nrarefação de pelos em tronco e membros inferiores. Observa-se ainda aumento de volume da\nsegunda e terceira articulações metacarpofalangeanas, bilateralmente, com discreta dor à\npalpação. Atrofia testicular também está presente no exame físico. A condição de base que pode\nestar relacionada ao desenvolvimento de tais sinais e sintomas é:","options":{"A":"Anemia sideroblástica","B":"Macroglobuinemia de Waldenstrom","C":"Tuberculose","D":"Infecção pelo vírus HIV","E":"Sarcoidose"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-154458","number":"154458","sourceNumber":"154458","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Considera-se como contraindicações para o transplante hepático:","options":{"A":"Trombose do sistema porta, alcoolismo, HIV positivo.","B":"Neoplasia extra-hepática, doenças cardiopulmonares, coagulopatias.","C":"Desnutrição grave, cirrose biliar primária, doença cardíaca isquêmica.","D":"Doença renal crônica, hepatite tipo C, tumores metastáticos não endócrinos.","E":"Alcoolismo persistente, hepatocarcinoma maior que 5 cm, doenças cardiopulmonares graves."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-160455","number":"160455","sourceNumber":"160455","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente é admitido no pronto-socorro torporoso. Ele estava sozinho e não há\nfamiliares por perto. No exame físico,\nobservam-se hálito cetônico, eritema palmar, apagamento do\nângulo da mandíbula, teleangiectasias, ginecomastia, flapping, importante aumento do volume\nabdominal, com circulação colateral visível e sinal do piparote. Exames laboratoriais da admissão\nmostram (conforme imagem do caderno de questões) A etiologia mais provável para o quadro\nclínico é:","options":{"A":"Sepse grave.","B":"Encefalopatia hepática.","C":"Encefalopatia urêmica.","D":"Hiponatremia sintomática.","E":"Intoxicação alcoólica."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/160455.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-160378","number":"160378","sourceNumber":"160378","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente é admitido no pronto-socorro torporoso. Ele estava sozinho e não há\nfamiliares por perto. No exame físico,\nobservam-se hálito cetônico, eritema palmar, apagamento do\nângulo da mandíbula, teleangiectasias, ginecomastia, flapping, importante aumento do volume\nabdominal, com circulação colateral visível e sinal do piparote. Exames laboratoriais da admissão\nmostram: (conforme imagem do caderno de questões) Sobre esse cenário clínico, assinale a\nafirmativa CORRETA.","options":{"A":"Há indicação de paracentese diagnóstica mesmo na ausência de sintomas abdominais.","B":"Deve-se realizar teste da catalase nas fezes e, se positivo, solicitar endoscopia digestiva\nalta.","C":"Deve ser iniciada reposição de sódio, calculando pela fórmula \"(140 - [Na+] do paciente) x água\ncorporal\".","D":"Tiamina associada a soro fisiológico deve ser imediatamente administrada via parenteral.","E":"É importante a avaliação do hematologista, pois na presença de pancitopenia o aspirado e\nbiópsia da medula óssea são indispensáveis."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/160378.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-132828","number":"132828","sourceNumber":"132828","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em uma investigação de hepatopatia crônica em paciente feminino, 25 anos, são\ncritérios diagnósticos imunológicos que falam a favor de hepatite autoimune, EXCETO:","options":{"A":"Anticorpo antimúsculo liso.","B":"Anticorpo antinúcleo.","C":"Anticorpo antimitocôndria.","D":"Anticorpo antimicrossomo fígado/rim 1.","E":"Anticorpo citoplasmático antineutrofílico perinuclear."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-87485","number":"87485","sourceNumber":"87485","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com diagnóstico de doença cística das vias biliares, cuja colangiorressonância\nevidencia dilatações das vias biliares intra e\nextra-hepática, qual a classificação desse tipo segundo\nTodani?","options":{"A":"Tipo IV - A;","B":"Tipo IV - B;","C":"Tipo I;","D":"Tipo II;","E":"Tivo V (Doenca de Caroli)."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-89572","number":"89572","sourceNumber":"89572","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher, 54 anos, queixa-se de prurido e fadiga há alguns anos. Passou a apresentar\nicterícia discreta, xantelasmas, equimoses e dores\nósseas. Ao exame físico apresenta\nhepatoesplenomegalia e a pesquisa de anticorpos antimitocondriais é positiva. Qual o diagnóstico\nmais provável?","options":{"A":"Cirrose biliar primária.","B":"Hemocromatose.","C":"Esclerodermia.","D":"Hepatite autoimune.","E":"Hepatite C."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-89622","number":"89622","sourceNumber":"89622","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Doença de Wilson está associada a distúrbio no metabolismo do (a):","options":{"A":"Ferro.","B":"Zinco.","C":"Glicogênio-6-fosfatase.","D":"Cobre.","E":"Alfa-1-antitripsina."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-87504","number":"87504","sourceNumber":"87504","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Escolar de 6 anos de idade, 25 kg, apresenta febre intermitente há 3 dias sem outras\nqueixas. Mãe vem fazendo uso regular de 10\nml de Tylenol bebê a cada 6h para controle de picos\nfebris. A cerca de 12h, evoluiu com vômitos incoercíveis que não melhoram com a administração de\n25 gts de Plasil. Admitido no pronto-socorro pediátrico, o exame físico inicial revela icterícia\n1+/4+,\ndistensão abdominal, fígado palpável a 2 cm do rebordo costal direito. Exames laboratoriais\nmostram leucograma 12.400 leucócitos/mm³ com 52% de segmentados sem desvio, TGO 560 U/L,\nTGP 487 U/L, bilirrubina direta 4,8 mg/dl. Ultrassonografia de abdômen total com hepatomegalia e\nascite. Qual o diagnóstico mais provável e tratamento adequado?","options":{"A":"Intoxicação por acetaminofeno; acetilcisteína oral ou EV;","B":"Gastrite; bloqueador H2;","C":"Hepatite B; imunoglobulina hiperimune;","D":"Hepatite A; vacina anti-hepatite A;","E":"Hepatite transinfecciosa; antibioticoterapia EV."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-52202","number":"52202","sourceNumber":"52202","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem branco de 35 anos de idade vai ao ambulatório queixando-se de fraqueza\ngeral, emagrecimento, dor abdominal mal\ncaracterizada e dor nos punhos e quadril à\nmovimentação. Ao exame, verifica-se hiperpigmentação cutânea difusa, fígado palpado a dois\ndedos abaixo da reborda costal, elástico, liso e indolor e aumento do volume dos punhos, com dor\nà movimentação passiva. Trouxe o resultado de uma glicemia em jejum: 185 mg/dl. A hipótese\ndiagnóstica mais provável é:","options":{"A":"Diabetes mellitus tipo 2.","B":"Carcinoma de pâncreas.","C":"Esteatose hepática.","D":"Doença de Addison.","E":"Hemocromatose."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-327332","number":"327332","sourceNumber":"327332","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 72 anos, com cirrose hepática, causada pelo vírus da hepatite C, vem em\nconsulta no ambulatório de hepatologia acompanhado pelo filho, apresentando icterícia ++/4+ e\ndistensão abdominal por volumosa ascite não controlada por paracentese. Filho refere que o pai\ntem apresentado quadros de confusão mental. Em relação à classificação de Child Pugh, quais\nexames são necessários para avaliar se o paciente tem indicação de transplante hepático?","options":{"A":"Bilirrubinas, ureia sérica e tempo de protrombina.","B":"Bilirrubinas, albumina sérica e tempo de protrombina.","C":"Bilirrubinas, ureia sérica e gamaglutamiltransferase.","D":"Bilirrubinas, albumina sérica e gamaglutamiltransferase."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-346643","number":"346643","sourceNumber":"346643","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Criança de oito anos é levada ao serviço de pronto atendimento com quadro de\ninsuficiência hepática aguda. Dentre exames\ncomplementares realizados, chama a atenção valores\nmuito altos de bilirrubinas, de cobre sérico e um discreto aumento das aminotransferases, com uma\nrelação AST/ALT igual a 5. Os pais são primos em primeiro grau e um irmão da criança, de 26\nanos, apresenta quadro neurológico caracterizado por alterações na fala com tremores e distonia.\nConsiderando os dados fornecidos, marque o diagnóstico MAIS PROVÁVEL para esta criança:","options":{"A":"Deficiência de alfa-1 -antitripsina.","B":"Doença de Wilson.","C":"Forma grave de hepatite A.","D":"Hepatite autoimune."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-315998","number":"315998","sourceNumber":"315998","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale o procedimento cirúrgico utilizado para descomprimir as varizes de esôfago,\nconsiderado uma derivação seletiva:","options":{"A":"Esplenorrenal distal","B":"Mesentérico-cava calibrada","C":"Esplenorrenal laterolateral de pequeno diâmetro","D":"Portocava calibrada","E":"Esplenorrenal central"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-308328","number":"308328","sourceNumber":"308328","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Durante uma colecistectomia videolaparoscópica, o cirurgião se depara com um fígado\nde aspecto cirrótico, associado à discreta\ncirculação colateral, sem ascite. Os exames laboratoriais\nda véspera mostram hemoglobina de 12,8 g/dL, hematócrito de 39,6%, INR de 1,12, TTPa 30,2\nsegundos, bilirrubinas totais de 1,0 com direta de 0,4 e indireta de 0,6, Albumina de 4,1 g/dL,\nfunção renal preservada. Diante do exposto, assinale a afirmativa correta.","options":{"A":"Biopsiar o fígado, fazer a colecistectomia e deixar um cateter na via biliar, pelo maior risco de\nfístula.","B":"Para segurança do procedimento, converter para cirurgia aberta e realizar apenas a\ncolecistectomia.","C":"Abortar a cirurgia e investigar o caso, para determinar a causa da cirrose.","D":"Prosseguir com a cirurgia via laparoscopia e realizar o planejado, mais a biópsia hepática."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274107","number":"274107","sourceNumber":"274107","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Pacientes hepatopatas candidatos a transplante hepático tem o status médico\ndeterminado pelo modelo de pontuação da doença hepática em estágio terminal. Quais são os\nparâmetros utilizados na avaliação?","options":{"A":"Razão normatizada internacional, creatinina e albumina.","B":"Razão normatizada internacional, creatinina e bilirrubina.","C":"Tempo da atividade da protrombina, ureia e bilirrubina.","D":"Tempo da atividade da protrombina, bilirrubina e fosfatase alcalina."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-288135","number":"288135","sourceNumber":"288135","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na cirurgia de Warren, utilizada no tratamento da hipertensão portal, realiza-se:","options":{"A":"Derivação espleno renal proximal e desconexão ázigo-portal.","B":"Derivação espleno renal proximal e desconexão espleno-pancreática.","C":"Derivação espleno renal distal e desconexão espleno-pancreática.","D":"Derivação espleno renal distal e desconexão ázigo-portal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-244769","number":"244769","sourceNumber":"244769","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São indicações de transplante hepático, exceto:","options":{"A":"Atresia biliar","B":"Cirrose biliar primária","C":"Síndrome de Alagille","D":"Cirrose criptogênica","E":"Síndrome de Alport"},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-214568","number":"214568","sourceNumber":"214568","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 52 anos, portador de cirrose alcoólica, é internado na enfermaria de clínica\nmédica do Hospital Universitário Júlio Muller com quadro de anasarca oligúria e piora da função\nrenal. De acordo com a Sociedade Brasileira de Hepatologia para Manejo de Lesão Renal Aguda\nna Cirrose (2017), é CORRETO afirmar:","options":{"A":"A definição de lesão renal aguda em portadores de cirrose, segundo o International Club of\nAscites (ICA), é o aumento da creatinina sérica\n? 0,3 mg/dl em relação ao seu valor basal, ocorrido\ndentro de 48 horas.","B":"A administração de albumina venosa está indicada na profilaxia da síndrome hepatorrenal\nassociada à peritonite bacteriana espontânea, a\ndose é de 1,0 g/kg de peso no primeiro dia e de\n2,0 g/kg de peso no segundo.","C":"O tratamento isolado com a albumina é a terapêutica de escolha na síndrome hepatorrenal, já\nque a associação com vasoconstrictores sistêmicos foi proscrita pelo alto índice de efeitos\ncolaterais.","D":"Após o diagnóstico de lesão renal aguda, a identificação da causa subjacente para adequado\nmanejo e prognóstico não é mais necessária devido à incidência crescente de síndrome\nhepatorrenal."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181573","number":"181573","sourceNumber":"181573","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre complicações da cirrose hepática, qual alternativa apresenta conceituação\nequivocada?","options":{"A":"Diuréticos devem ser usados com muita cautela, pois podem ocasionar episódios de\nencefalopatia\n\nportossistêmica ou síndrome hepatorrenal.","B":"Contaminação bacteriana de ascite pode estar presente, mesmo que a contagem de neutrófilos\nno líquido ascítico não exceda 250 células por\nmm³.","C":"O nível de plaquetas no paciente cirrótico não apresenta relação com o risco de sangramento\ndigestivo por ruptura de varizes\ngastroesofagianas.","D":"Ascite volumosa deve sempre ser combatida com diuréticos e esvaziamento mecânico,\nindependentemente do estado circulatório."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-177334","number":"177334","sourceNumber":"177334","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma criança de 3 anos ingere o conteúdo de um vidro do \"remédio para febre\", que é o\nacetaminofeno (paracetamol). Após a mensuração do nível sérico de paracetamol, você constata\nque a concentração está acima da linha de \"toxidade provável\". Qual é o antídoto indicado nesse\ncaso?","options":{"A":"desferroxamina","B":"atropina","C":"vitamina K1","D":"acetilcisteína","E":"carvão ativado"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-167810","number":"167810","sourceNumber":"167810","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação à esteatose hepática, é CORRETO afirmar que:","options":{"A":"Pode evoluir para cirrose.","B":"É fator de risco para o desenvolvimento de hemangiomas múltiplos.","C":"É a manifestação mais precoce da síndrome metabólica.","D":"Está presente em todos os pacientes em terapia hormonal."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158113","number":"158113","sourceNumber":"158113","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A respeito da síndrome hepatorrenal, é CORRETO afirmar que:","options":{"A":"Tem, como fisiopatologia básica, a disfunção tubular proximal, ocasionada por diminuição da\nprodução de prostaglandina E.","B":"Deve ser abordada com expansão volumétrica, administração de albumina humana e agentes\ninotrópicos positivos.","C":"Deve ser tratada com expansão volumétrica por albumina humana, seguida da administração\nvenosa de furosemida.","D":"Caracteriza-se por uremia com oligúria e hipertensão arterial reativa à hipoperfusão renal."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158151","number":"158151","sourceNumber":"158151","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a peritonite bacteriana secundária, é CORRETO afirmar que:","options":{"A":"Apenas uma bactéria é isolada na cultura frequentemente.","B":"A presença de flora mista no líquido ascítico sugere seu diagnóstico fortemente.","C":"O antígeno carcinoembrionário no líquido ascítico encontra-se baixo.","D":"A fosfatase alcalina baixa no líquido ascítico favorece o diagnóstico."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-109291","number":"109291","sourceNumber":"109291","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 15 anos, do sexo masculino, se apresenta ao médico com icterícia,\nemagrecimento discreto e astenia. Exames mostram\nbilirrubina total de 5 mg/dl, à custa de\nbilirrubina direta, aminotransferases em torno de 1.000 UI/ml e discreta esplenomegalia. Seus\nexames mostram anticorpos contra hepatite A classe IgG positivos; antígeno de superfície da\nhepatite B negativo; anticorpos contra hepatite C negativos; FAN positivo 1:320 padrão pontilhado\nfino; albumina de 3,6 mg/dl; globulinas de 4,7; gamaglobulina de 3,2. Anticorpos antimúsculo liso e\nantimitocôndria negativos. Biópsia hepática mostra fibrose em ponte, esboçando nódulos e\ninfiltrado inflamatório linfoplasmocitário portal e periportal invadindo a placa limitante. O\nprovável\ndiagnóstico é:","options":{"A":"Hepatite A aguda.","B":"Hepatite autoimune.","C":"Hepatite C aguda no período de \"janela imunológica\".","D":"Cirrose biliar primária."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-98039","number":"98039","sourceNumber":"98039","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa que apresenta as variáveis avaliadas na classificação de\nChield-Pugh da cirrose hepática alcoólica.","options":{"A":"Encefalopatia, edema, aminotransferases, albumina e INR.","B":"Encefalopatia, ascite, bilirrubinas, albumina e tempo de atividade da protrombina.","C":"Eritema palmar, ascite, aminotransferases, albumina e tempo de atividade da protrombina.","D":"Ginecomastia, eritema palmar, bilirrubinas, proteínas totais e tempo de atividade da\nprotrombina."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-98041","number":"98041","sourceNumber":"98041","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A presença do anel de Kayser-Fleischer ao exame clínico dos olhos é indicativo de:","options":{"A":"Doença de Wilson.","B":"Hemocromatose.","C":"Tirosinemia.","D":"Deficiência de alfa-1-antitripsina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-75396","number":"75396","sourceNumber":"75396","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A contagem de polimorfonuclear no líquido ascítico \"maior ou igual a\" 250 céls/mm³, em\ncirróticos, é indicativa de:","options":{"A":"Peritonite bacteriana secundária, mesmo na ausência de paracentese prévia ou outra infecção\nsistêmica.","B":"Peritonite tuberculosa, se associada à redução na dosagem de glicose.","C":"Peritonite bacteriana espontânea, mesmo na ausência de sintomas.","D":"Carcinomatose peritoneal, se a gradiente soro-ascite de albumina for < 1,1."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-57603","number":"57603","sourceNumber":"57603","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A formação de varizes de esôfago e a ocorrência de sangramento varicoso em\npacientes portadores de cirrose na forma sinusoidal e pós-sinusoidal estão relacionadas,\nrespectivamente, a valores do gradiente de pressão porta a partir de:","options":{"A":"10 mmHg e 12 mmHg.","B":"4 mmHg e 7 mmHg.","C":"6 mmHg e 9 mmHg.","D":"5 mmHg e 10 mmHg.","E":"2,5 mmHg e 5 mmHg."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-360574","number":"360574","sourceNumber":"360574","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale os critérios utilizados na classificação funcional de Child-Turcotte modificada\npor Pugh.","options":{"A":"Albumina, bilirrubina, tempo de protrombina, ascite e encefalopatia.","B":"Albumina, bilirrubina, plaquetas, ascite e encefalopatia.","C":"Amilase, bilirrubina, coagulograma, ascite e encefalopatia.","D":"Creatinina, bilirrubina, tempo de protrombina, ascite e encefalopatia."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-301657","number":"301657","sourceNumber":"301657","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A cirrose descompensada distingue-se da compensada por meio do escore de\nChild-Turcotte-Pugh (Child-Pugh), sendo adequado que:","options":{"A":"Utilizado para avaliar o grau de deterioração da função hepática, e ano como marcador\nprognóstico.","B":"Não utilizado para avaliar o grau de deterioração da função hepática, e sim marcador\nprognóstico.","C":"Utilizado para avaliar o grau de deterioração da função hepática, além de ser marcador\nprognóstico.","D":"Nunca utilizado para avaliar o grau de deterioração da função hepática, nem marcador\nprognóstico."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-276018","number":"276018","sourceNumber":"276018","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à doença hepática gordurosa não alcoólica, é correto afirmar:","options":{"A":"A maioria dos pacientes é assintomática.","B":"Na avaliação dos pacientes, as enzimas hepáticas alanina aminotransferase e aspartato\naminotransferase são bons marcadores de gravidade do dano da célula hepática.","C":"Ocorre exclusivamente em pacientes com excesso de peso corporal.","D":"Os medicamentos da classe tiazolidinedionas (ex: metformina) são os medicamentos de escolha\npara o tratamento."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-286101","number":"286101","sourceNumber":"286101","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A cirrose hepática é a principal causa de ascite e é o evento final de uma série de\nalterações anatômicas, fisiológicas e\nbioquímicas. Na análise do líquido ascítico devemos analisar o\ngradiente de albumina soroascite (GASA). Considerando o GASA aumentado na hipertensão portal,\nqual das doenças abaixo não possui este padrão e deveria ser excluído no diagnostico diferencial.","options":{"A":"Cirrose cardíaca","B":"Trombose de veia porta","C":"Síndrome nefrótica","D":"Hepatite alcóolica","E":"Insuficiência hepática fulminante"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274895","number":"274895","sourceNumber":"274895","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à Doença Hepática Gordurosa Não Alcoólica (DHGNA), assinale a\nalternativa correta.","options":{"A":"A principal causa de morte nesse grupo de pacientes é devido à própria doença hepática\ncrônica.","B":"Mudanças de hábito de vida, incluindo dieta com restrição de carboidratos simples e atividade\nfísica, são medidas terapêuticas\nfundamentais.","C":"Na esteato-hepatite não alcoólica, a redução de outros agressores hepáticos, como álcool e\nmedicamentos, não é relacionada ao melhor prognóstico.","D":"Em longo prazo, o acompanhamento de pacientes com DHGNA deve contemplar uma avaliação\ndo grau de fibrose hepática, devendo ser\nrealizada por meio de biópsia hepática.","E":"No contexto do Diabetes mellitus tipo 2, pacientes apresentando alterações em bioquímica\nhepática não necessitam ser investigados quanto à quantificação do consumo de álcool e à\npresença de hepatites virais, pois a DHGNA é a causa mais provável."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274906","number":"274906","sourceNumber":"274906","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 49 anos, sexo masculino, com relato de consumo de álcool de pelo menos\n1 garrafa de destilado ao dia, nos últimos 25\nanos, é avaliado no ambulatório de Clínica Médica. Ao\nexame, notam-se icterícia, abdome ascítico, eritema palmar e edema em membros inferiores. O\ncaso caracteriza um paciente com cirrose hepática de etiologia alcoólica, e sobre isso, assinale a\nalternativa CORRETA:","options":{"A":"Apesar de recomendada, a abstinência alcoólica nesse grupo de pacientes não influencia o seu\nprognóstico.","B":"A realização de Endoscopia Digestiva Alta (EDA), para diagnóstico de varizes de esôfago, pode\nser substituída pela prescrição de\nbetabloqueadores não seletivos.","C":"A incidência de hepatocarcinoma é semelhante à população em geral.","D":"Nos exames laboratoriais do paciente descrito, é esperado predomínio de AST (aspartato\naminotransferase) sobre ALT (alanina aminotransferase).","E":"A redução da ingestão de sal e proteínas é orientação importante no aconselhamento inicial\ndesse paciente."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-274985","number":"274985","sourceNumber":"274985","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 11 anos de idade, menina, com diagnóstico de Hepatite há 1 mês, retorna\nà consulta com resultado de exames: Hemograma\nsem alterações, TGO: 648 U/L, TGP 752 U/L,\nGama GT 40 U/L, FA: 184 U/L, BT: 8 mg/dl, BD: 7.5 mg/dl, BI 0.5 mg/dl, RNI: 1.6 e TTPA 30\nsegundos. A mãe refere que a criança está bem. Pergunta se será necessário examiná-la, pois a\ncriança está muito irritada e não quer entrar no consultório. Qual a conduta adequada nesse caso?","options":{"A":"Como os exames laboratoriais não exibem alterações relevantes, dispensar para casa com\norientação de retorno em 15 dias.","B":"Pedir para examinar a criança e, se constatada hepatomegalia, internar na enfermaria.","C":"Solicitar vaga na enfermaria, devido aos altos níveis de transaminases.","D":"Pedir para examinar a criança e, se constatada irritabilidade, internar na unidade de terapia\nintensiva.","E":"Solicitar vaga na unidade de terapia intensiva pelo risco aumentado de hemorragia."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-216817","number":"216817","sourceNumber":"216817","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O score que tem sido utilizado para predizer a severidade da cirrose hepática e o risco\nde complicações é o de Child-Pugh. Qual dentre os\nfatores abaixo NÃO é levado em consideração\npara a pontuação do score?","options":{"A":"Albumina sérica.","B":"Bilirrubina sérica.","C":"Contagem de plaquetas.","D":"Tempo de protrombina."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-220238","number":"220238","sourceNumber":"220238","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem, 54 anos, cirrose hepática de etiologia alcoólica (Child C), renal crônico não\ndialítico, com história de 2 internações prévias, uma com hemorragia digestiva alta (recebeu\ntratamento com escleroterapia) e outra com necessidade de paracentese de alívio. Faz uso de\npropranolol 40mg/dia de forma irregular. Hoje admitido após episódio importante de melena, PA:\n80/60 mmHg, FC 125 bpm, sonolento, não atendendo ao comando, gasping, hipocorado 3+/4+,\ndesidratado +/4+ e afebril. O procedimento que está contraindicado no momento é:","options":{"A":"passagem de sonda nasoenteral.","B":"intubação orotraqueal.","C":"transfusão sanguínea.","D":"octreotide."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-214090","number":"214090","sourceNumber":"214090","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação aos fatores de risco para desenvolvimento de Doença Hepática Alcoólica\n(DHA), assinale a alternativa CORRETA.","options":{"A":"Indivíduos do sexo masculino são mais suscetíveis à hepatotoxicidade induzida pelo álcool e\ndesenvolvimento da DHA.","B":"A quantidade de álcool ingerida (g/dia) não interfere no desenvolvimento da DHA.","C":"O tempo de ingestão alcoólica (em anos) não influencia o desenvolvimento da DHA.","D":"Os níveis de gama GT e VCM (Volume Corpuscular Médio) aumentados são suficientes para se\ndefinir a etiologia alcoólica de uma doença hepática crônica.","E":"A associação entre hepatite viral e ingestão alcoólica acarreta progressão mais acentuada da\nlesão hepática do que quando as duas doenças aparecem de forma isolada."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183524","number":"183524","sourceNumber":"183524","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 62 anos de idade, portador de cirrose por vírus C, obeso,\nem acompanhamento ambulatorial, sem outras\ncomorbidades, tem endoscopia digestiva alta\nrecente mostrando varizes de esôfago de grosso calibre e está em uso de diuréticos para controle\nda ascite, sem outras medicações no momento. Apresenta, segundo familiares, alterações no ciclo\nsono-vigília e aumento progressivo do volume abdominal. Com relação à Encefalopatia Hepática\n(EH), assinale a alternativa CORRETA.","options":{"A":"A reconciliação medicamentosa dos diuréticos e até mesmo sua suspensão, a despeito da\nqueixa de aumento de volume abdominal, deve ser considerada no tratamento desse paciente.","B":"Sem relato de hematêmese ou melena, a hemorragia digestiva não deve ser considerada como\nfator desencadeante da EH nesse caso.","C":"O uso de dissacarídeos não absorvíveis como lactulose e lactitol vem sendo substituído pelo\nemprego de L-ornitina L-aspartato (LOLA) no tratamento inicial da EH.","D":"A ausência de dor abdominal e febre exclui Peritonite Bacteriana Espontânea (PBE) como\nfator desencadeante da EH.","E":"A terapêutica de prevenção de recorrência não é recomendada em grande parte dos pacientes,\nem função dos riscos potenciais das medicações\nutilizadas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-183480","number":"183480","sourceNumber":"183480","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quanto aos fatores de risco para o desenvolvimento da Doença Hepática Alcoólica\n(DHA), assinale a alternativa incorreta.","options":{"A":"A quantidade de álcool (g/dia) e o tempo de ingesta alcoólica influenciam o seu\ndesenvolvimento.","B":"A associação de outras hepatopatias, como a hepatite viral, acarreta uma progressão mais\nacelerada da doença do que quando de forma isolada.","C":"Indivíduos do sexo masculino são mais suscetíveis à hepatotoxicidade induzida pelo álcool e ao\ndesenvolvimento de DHA.","D":"Predisposição genética e fatores ambientais estão relacionados ao desenvolvimento do\nalcoolismo e, como consequência, da DHA.","E":"O questionário CAGE tem boa acurácia na identificação de dependência alcoólica."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-155657","number":"155657","sourceNumber":"155657","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à cirrose hepática, quais dos escores abaixo é o mais utilizado para\nplanejamento de transplante hepático?","options":{"A":"Child-Pugh.","B":"APACHE II.","C":"SAPS.","D":"MELD.","E":"ECOG."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-155691","number":"155691","sourceNumber":"155691","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Fernando, de 28 anos, vem ao Pronto Atendimento do Hospital Regional de Mato\nGrosso do Sul porque está há cinco dias\ncom náusea, vômitos, dor abdominal difusa, febre de\n38,3°C e dores musculares. Perdeu o apetite, mas tolera líquidos e não tem diarreia. Não tem\nhistória médica ou familiar significativas e não viajou para fora de Campo Grande. Admite ter tido\n12\nparceiras sexuais durante a vida, nega uso de drogas ilícitas e bebe álcool ocasionalmente, mas\nnão depois que a doença começou. Não toma medicação rotineiramente, refere ser alérgico à\ndipirona e vem tomando aproximadamente 30 comprimidos de paracetamol por dia há dois dias por\ncausa de febre e das dores no corpo desde que a doença começou. Durante o exame, sua\ntemperatura é 38°C, a frequência cardíaca é de 98 bpm e a pressão arterial é de 120/74 mmHg. O\npaciente está ictérico, mas o tórax está limpo à asculta, e o ritmo cardíaco é regular, sem sopros.\nO\nfígado é percutível por 12 cm, liso e levemente doloroso à palpação. Não há distensão abdominal\nou edema periférico. Os exames laboratoriais mostram hemograma normal, sorologia para Dengue\nnegativa, teste rápido de HIV negativo, com níveis de creatinina de 1,1 mg/dL, alanina\naminotransferase (ALT) de 3,440 UI/L, aspartato aminotransferase (AST) de 2,705 UI/L, bilirrubina\ntotal de 24,5 mg/dL, bilirrubina direta de 18,2 mg/dL, fosfotase alcalina de 349 UI/L, albumina\nsérica\nde 3 g/dL e tempo de protrombina de 14 segundos. Qual é a conduta a ser tomada?","options":{"A":"Internação imediata para a equipe de hepatologia do hospital, entrada de acetilcisteína,\nsolicitar:\nsorologia para hepatites B e C, teste rápido para leishmaniose e solicitar Ultrassom de Abdômen\ntotal para afastar outros diagnósticos. Manter hidratação rigosa e medidas de suporte até conduta\nda equipe de hepatologia.","B":"Internação imediata para a equipe de hepatologia do hospital, solicitar sorologia para Hepatite\nB,\nC, ultrassom de abdome e aguardar resultado de exames para tomar uma conduta.","C":"Internar para cirurgia geral por ser tratar de colangite e iniciar protocolo para sepse de foco\nabdominal.","D":"Internar para clínica médica por se tratar provavelmente de leishmaniose aguda e iniciar\nanfotericina lipossomal imediatamente.","E":"Internar para equipe de oncologia por ser tratar de possível hepatocarcinoma."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-155629","number":"155629","sourceNumber":"155629","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Das reações abaixo, qual é a mais provável de ser catalisada pelo citocromo P450?","options":{"A":"Acetilação da hidralazina.","B":"Desmetilação da cetamina.","C":"Desanimação oxidativa da noradrenalina.","D":"Conjugação da morfina com glicuronídeo.","E":"Conjugação do acetaminofeno com sulfato."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-107824","number":"107824","sourceNumber":"107824","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à associação entre o consumo e abuso de álcool e as doenças crônicas,\nassinale a afirmativa INCORRETA:","options":{"A":"A partir do consumo diário médio de 30 g de etanol para homens e 15 g para mulheres, há\ndefinido e exponencial aumento da pressão arterial.","B":"Em pessoas que já apresentam HAS,o consumo excessivo de álcool pode dificultar o controle da\ndoença e a diminuição do consumo de álcool\nreduz discretamente a pressão arterial.","C":"Pessoas com doenças crônicas, incluindo o diabetes, não devem tomar álcool em qualquer\nquantidade, uma vez que o consumo de álcool\npode trazer prejuízos aos tratamentos das doenças\ncrônicas.","D":"Usuários que abusam de álcool costumam ter dificuldade para uso regular das medicações para\ntratamento das condições crônicas, fato estimulado pela crença de que após o consumo de álcool\nnão se deve fazer uso delas.","E":"Episódios de consumo excessivo de álcool podem levar a descompensações agudas das\ndoenças crônicas, sendo fundamental avaliar\nnesses casos a pressão arterial e a glicemia desses\nusuários, pois podem ocorrer alterações significativas que necessitam de intervenções clínicas."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-81186","number":"81186","sourceNumber":"81186","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual dos medicamentos abaixo não é causa de esteatose hepática medicamentosa?","options":{"A":"Glicocorticoides.","B":"Estrogênios.","C":"Tamoxifeno.","D":"Digoxina.","E":"Amiodarona."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-45963","number":"45963","sourceNumber":"45963","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher, 38 anos, sobrepeso, apresenta dor em hipocôndrio direito inicialmente em\ncólica há 3 dias, atualmente contínua, vomitou 5 vezes desde o início do quadro, e apresentou\nfebre não aferida hoje. Está ictérica ++/4+, bilirrubina total 4 mg/dl, gamaglutamiltransferase 345\nUI/l, transaminases pouco alteradas, 14.800 leucócitos, 8% de bastões. É INCORRETO afirmar\nque:","options":{"A":"O primeiro exame de imagem que deve ser realizado é a ultrassonografia de abdome.","B":"Colecistite aguda é um diagnóstico provável, já que pode cursar com icterícia leve.","C":"Coledocolitíase é um diagnóstico possível, podendo inclusive haver colangite.","D":"Não havendo dilatação importante das vias biliares, é possível se fazer papilotomia endoscópica\nseguida por videocolecistectomia, caso se\nconfirme colelitíase e coledocolitíase.","E":"Caso se confirme tratar-se de síndrome de Mirizi deve-se fazer inicialmente antibioticoterapia e\npostergar a colecistectomia, o que diminui o risco de lesão acidental da via biliar."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-31889","number":"31889","sourceNumber":"31889","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Síndrome de Korsakoff é uma síndrome amnéstica causada por:","options":{"A":"Deficiência de vitamina B12.","B":"Deficiência de acetilcolina.","C":"Deficiência de vitamina B1.","D":"Ação direta do álcool.","E":"Idade avançada."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-25726","number":"25726","sourceNumber":"25726","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente jovem, queixando-se de artrite, foi encaminhado pelo oftalmologista que\nidentificou anéis de Kayser-Fleischer na córnea. Qual é o provável diagnóstico?","options":{"A":"Hemocromatose.","B":"Ocronose.","C":"Anemia falciforme.","D":"Acromegalia.","E":"Doença de Wilson."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-25735","number":"25735","sourceNumber":"25735","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a opção INCORRETA, quanto às hepatopatias.","options":{"A":"A esteato-hepatite não alcoólica (NASH) é doença de alta prevalênicia, associa-se à síndrome\nmetabólica, sendo que perda de peso e controle de níveis glicêmicos e lípides fazem parte do\ntratamento.","B":"O diagnóstico da NASH é feito por ultrassonografia de abdome e alterações do nível sérico de\nenzimas hepáticas sendo a biópsia hepática irrelevante para avaliação do prognóstico da doença.","C":"A Doença de Wilson ou degeneração hepatolenticular é decorrente de um distúrbio do\nmetabolismo do cobre.","D":"O tratamento da hemocromatose baseia-se na remoção do ferro acumulado por flebotomias\nseriadas.","E":"Achados de níveis séricos de GamaGT aumentados, de aspartatoaminotransferase (TGO) maior\nque alaninaaminotransferase (TGP) e de esteatose hepática na ultrassonografia de abdome\nsugerem hepatopatia alcoólica."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-25751","number":"25751","sourceNumber":"25751","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quanto à hepatite autoimune, assinale a OPÇÃO CORRETA.","options":{"A":"É uma doença que acomete preferencialmente as mulheres e caracteriza-se pela presença de\nhipoalbuminemia","B":"É uma doença inflamatória aguda do fígado, que raramente evolui para cirrose hepática","C":"O diagnóstico é feito pela interpretação de um sistema de escores, excluindo-se outras\nhepatopatias, como por VHC ou álcool","D":"A histologia hepática é irrelevante no seu diagnóstico","E":"A terapêutica inclui corticoterapia e imunossupressores por tempo limitado, sem necessidade de\ntratamento de manutenção."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-255915","number":"255915","sourceNumber":"255915","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 43 anos queixa-se de dor abdominal difusa há 48h. Nega febre, alterações\nrespiratórias, intestinais ou urinárias. É portador de cirrose hepática alcoólica. Ao exame físico,\napresenta PA 98/72 mmHg, FC 68 bpm, FR 16 ipm, SpO2 em ar ambiente 98%. Está sonolento,\ndesorientado no espaço e com lentidão psicomotora. As mucosas são coradas e ictéricas. Há\nginecomastia e aranhas vasculares no tórax. O abdome é globoso, doloroso à palpação difusa,\nnormotenso, sem sinais de irritação peritoneal, com submacicez móvel dos flancos. Exames de\nlaboratório: sangue: Hb 11,5 g/dl; LG 8.670/mm³; NS 5.500/mm³; Plq 176.000/mm³; AST 88 U/L;\nALT 34 U/L; RNI 1,7; BT 4,4 mg/dl; Creat 1,2 mg/dl; Ur 46 mg/dl; Albumina 2,9 g/dl. Líquido\nascítico:\ncélulas nucleadas 700/mm³; neutrófilos 45%; albumina 1,2 g/dl. Assinale a alternativa que\napresenta uma conduta INADEQUADA no manejo inicial deste paciente.","options":{"A":"Prescrever albumina humana pela via intravenosa.","B":"Prescrever ceftriaxona pela via intravenosa.","C":"Prescrever furosemida e espironolactona pela via oral.","D":"Prescrever lactulose pela via oral."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174682","number":"174682","sourceNumber":"174682","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 47 anos, assintomática, apresenta elevação dos níveis séricos de fosfatase\nalcalina e gamaglutamiltransferase, associada a anticorpo antimitocôndria positivo (1/320) e\nelevação dos níveis séricos de IgM. O médico assistente opta pela realização da biópsia hepática,\nque evidencia lesão ductal florida associada à inflamação portal, mas sem sinais de fibrose.\n\nConsiderando a hipótese diagnóstica mais provável, assinale a alternativa ERRADA:","options":{"A":"Apresenta início insidioso.","B":"Há risco aumentado de apresentar baixa densidade óssea.","C":"Não se associa a doenças reumatológicas.","D":"Podem ocorrer lesões xantomatosas na pele e tendões."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-149847","number":"149847","sourceNumber":"149847","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 60 anos procura auxílio médico com queixa de fadiga crônica e prurido\ngeneralizado de leve intensidade. Tem\nhistória de tireoidite autoimune e recentemente foi\ndiagnosticada com síndrome de Sjögren. Refere ainda que a sua pele está escurecendo. Ao\nexame, constata-se hepatomegalia moderada, sendo o fígado de consistência firme e indolor.\nAlbumina, aminotransferases e coagulograma estavam dentro dos limites de referência, mas havia\nelevação da fosfatase alcalina e da gamaglutamiltransferase (cerca de 3 a 4 vezes o limite superior\ndo normal), e os níveis de bilirrubina direta e indireta estavam um pouco acima do valor de\nreferência. Constatou-se ainda hipercolesterolemia com elevação do HDL, LDL e VLDL. A\nultrassonografia abdominal evidenciou hepatomegalia inespecífica e ausência de alterações das\nvias biliares extra-hepáticas. Assinale a alternativa com os anticorpos que provavelmente estão\npresentes no soro deste paciente:","options":{"A":"Antimitocôndria.","B":"Antimúsculo liso.","C":"Anti-DNA de dupla hélice.","D":"Antivírus da hepatite C."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-127542","number":"127542","sourceNumber":"127542","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"F.Q.L., 58 anos, gênero masculino, pintor, alcoolista, queixa-se de dor abdominal e\nfebre. Ao exame, nota-se ascite volumosa, sendo indicada paracentese. A análise do líquido\nascítico revelou 400 neutrófilos/mm³ e baixo teor de albumina. Em relação a este caso e com seu\nconhecimento sobre o assunto, assinale a alternativa CORRETA:","options":{"A":"A administração de albumina não altera o prognóstico nesse tipo de paciente.","B":"A baixa concentração prévia de proteínas no líquido ascítico impede o eficaz clearance de\nbactérias pelos macrófagos e neutrófilos.","C":"Certamente, ele é portador de cirrose hepática, já que outras causas de ascite como ICC e\nsíndrome nefrótica não evoluem esse quadro.","D":"Em paciente que responde mal à antibioticoterapia, o isolamento de flora mista, particularmente\ncom organismos Gram-negativos entéricos, é típico de\nperitonite bacteriana espontânea."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-112657","number":"112657","sourceNumber":"112657","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente psiquiátrico ingere acidentalmente 20 comprimidos (500 mg) de paracetamol.\nQual o antídoto para intoxicação por\nparacetamol?","options":{"A":"Flumazenil.","B":"Naloxona.","C":"N-acetilcisteína.","D":"Dantrolene."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-101815","number":"101815","sourceNumber":"101815","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"H.S.W., 48 anos, sexo masculino, alcoolista crônico, com cirrose hepática etanólica\ndescompensada e ascite volumosa, dá entrada no pronto atendimento com dor abdominal difusa e\nmelena. Para pesquisa de Peritonite Bacteriana Espontânea (PBE) foram solicitados exames do\nlíquido ascítico, que evidenciaram: dosagem de proteínas de 0,3 g/dl e ausências de bactérias\ncoráveis pelo Gram. A citometria revelou predomínio de polimorfonucleares (mais que 50%) com\n450 céls/ml. Cultura em andamento. Sobre este caso, assinale a alternativa CORRETA:","options":{"A":"Essa dosagem de proteínas exclui o diagnóstico de PBE.","B":"A melena não tem influência no aparecimento da PBE.","C":"O resultado do Gram exclui o diagnóstico de PBE.","D":"O predomínio de polimorfonucleares (mais que 50%) com mais de 250 céls/ml presume PBE."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-55313","number":"55313","sourceNumber":"55313","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação às doenças hepáticas crônicas da criança e do adolescente, assinale a\nafirmativa INCORRETA:","options":{"A":"A fibrose hepática congênita se distingue da cirrose hepática pela inexistência de disfunção\nhepática na primeira.","B":"O paciente cirrótico que tem como complicação peritonite bacteriana espontânea tem indicação\nde transplante hepático.","C":"A cefotaxima é a droga de primeira escolha para o tratamento da peritonite bacteriana\nespontânea e da colangite pós-operatória.","D":"A doença de Wilson, uma das causas metabólicas da cirrose hepática, tem prognóstico\nreservado em razão do tratamento específico\npouco eficaz."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-31485","number":"31485","sourceNumber":"31485","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Mulher de 60 anos, obesa (IMC = 30), hipertensa, portadora de dislipidemia,\nintolerância à glicose e hiperuricemia.\nQueixa-se, há dois anos, de boca amarga e de dor no\nhipocôndrio direito de caráter recorrente, de intensidade leve e sem fatores desencadeantes. Nega\netilismo e uso de medicamentos. Sua ultrassonografia abdominal evidencia pequeno aumento do\nfígado, esteatose hepática e ausência de colelitíase. São afirmações pertinentes sobre o caso\ndescrito acima, EXCETO:","options":{"A":"A doença hepática gordurosa não alcoólica é condição benigna sem possibilidade de evoluir\npara cirrose hepática e carcinoma hepatocelular.","B":"A paciente apresenta elementos da síndrome metabólica e o diagnóstico de doença hepática\ngordurosa não alcoólica deve ser considerado.","C":"Dor no hipocôndrio direito usualmente não faz parte das manifestações clínicas das\nhepatopatias crônicas.","D":"Hepatite crônica viral, doenças hepáticas metabólicas ou autoimunes fazem parte do diagnóstico\ndiferencial, podendo apresentar aspecto ultrassonográfico semelhante."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-355397","number":"355397","sourceNumber":"355397","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Os transplantes são atos nos quais partes do corpo humano podem ser retiradas de\npessoas vivas ou falecidas (doadores), para\nserem usadas no tratamento de outras pessoas\n(receptores), com o objetivo de restaurar as funções de um órgão ou tecido doente. Sobre a lei que\nregulamenta a remoção de órgãos, tecidos e partes do corpo humano para fins de transplante e\ntratamentos no Brasil, é correto afirmar:","options":{"A":"é permitida à pessoa juridicamente capaz dispor gratuitamente de tecidos, órgãos e partes do\npróprio corpo vivo, para fins terapêuticos ou para transplantes em cônjuges ou parentes\nconsanguíneos até o quarto grau, ou em qualquer outra pessoa, mediante autorização judicial,\ndispensada esta em relação à medula óssea.","B":"a remoção post mortem de tecidos, órgãos ou partes do corpo de pessoas não identificadas\npoderá ser feita desde que precedida de\ndiagnóstico de morte encefálica, constatada e registrada\npor dois médicos não participantes das equipes de remoção e transplante.","C":"a retirada post mortem de tecidos, órgãos ou partes do corpo humano destinados a transplante\ndeverá ser precedida de diagnóstico de morte\nencefálica, constatada e registrada por dois médicos,\nsendo um deles participante de equipe de remoção e transplante.","D":"salvo manifestação de vontade em contrário, presume-se autorizada a doação de tecidos,\nórgãos ou partes do corpo humano, para\nfinalidade de transplantes ou terapêutica post mortem,\ndesde que os testes de triagem para diagnóstico de infecção e infestação exigidos em normas\nregulamentares sejam realizados."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369721","number":"369721","sourceNumber":"369721","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com ascite é submetido a paracentese com dosagem de albumina de 1,8g/dL\ne glicose 45mg/dL. A dosagem sérica de albumina\né de 2,8g/dL. Entre as hipóteses diagnosticas\npodem-se incluir:","options":{"A":"Cirrose hepática, síndrome de Budd-Chiari, insuficiência cardíaca","B":"Síndrome nefrótica, carcinomatose","C":"Apendicite complicada e diverticulite aguda","D":"Tuberculose e pericardite constritiva"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-359318","number":"359318","sourceNumber":"359318","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, de 48 anos, nasceu na Itália, mas vive em Belo Horizonte\nhá 25 anos. Comparece a uma consulta com\nqueixas de cansaço nos últimos meses que atribuía, a\nprincípio, ao seu \"estresse diário\" e a dores articulares. Assustou-se ao se perceber \"bronzeada\"\nmesmo tendo aversão a sol e calor. Não tinha antecedentes pessoais significativos; sua mãe\nmorreu de cirrose hepática. Sua última menstruação ocorreu aos 41 anos. Ao exame físico,\nobservava-se uma pele cor de bronze sem outras alterações dignas de nota. Traz consigo vários\nexames de consultas médicas, todos normais, mas com ferritina de 7.000 mcg/L. O ferro sérico e a\neletroforese de proteínas foram normais, as mutações genéticas do HFE para hemocromatose\nforam negativas e a dosagem de hepcidina não era realizada por nenhum dos laboratórios\nconsultados pela paciente. A saturação da transferrina era alta (70%), e a ressonância magnética\nmostrou acúmulo expressivo de ferro no fígado, baço e pâncreas. A paciente recusou-se a fazer\nbiópsia de fígado, pois considerou o exame muito agressivo. Assinale a alternativa que apresenta o\ndiagnóstico MAIS provável.","options":{"A":"Hemocromatose.","B":"Mielodisplasia.","C":"Porfiria cutânea tardia.","D":"Talassemia major."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369752","number":"369752","sourceNumber":"369752","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em um paciente portador de cirrose hepática com ascite, na peritonite bacteriana\nespontânea que porventura se estabeleça, a bactéria atinge o liquido peritoneal a partir de:","options":{"A":"Diretamente da luz intestinal","B":"Diretamente dos linfáticos","C":"Pele e mucosas","D":"Circulação sistêmica"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-361747","number":"361747","sourceNumber":"361747","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dentre as causas abaixo, assinale a alternativa que corresponda a uma causa de\npaciente com ascite e GASA (Gradiente Albumina Soro-Ascite) aumentada.","options":{"A":"ascite biliar","B":"vazamento linfático pós-operatório","C":"infarto intestinal.","D":"fígado esteatótico da gravidez."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-330291","number":"330291","sourceNumber":"330291","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"É CORRETO afirmar que o tratamento de varizes gástricas em hemorragia, no contexto\nde uma hipertensão porta esquerda, deve ser\nrealizado com:","options":{"A":"Derivação mesocava.","B":"Derivação portossistêmica intra-hepática transjugular.","C":"Gastrectomia.","D":"Esplenectomia."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-325990","number":"325990","sourceNumber":"325990","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 46 anos de idade, morador de região rural, é portador de\nEsquistossomose Mansônica na sua forma hepatoesplênica. Apresentou um sangramento intenso\ndas varizes gástricas, com choque hipovolêmico tratado com balão de Sengstaken Blakemore,\ntransfusão sanguínea e encaminhamento a um centro hospitalar de cuidados médicos avançados.\nCom relação ao quadro clínico descrito acima, assinale a alternativa que apresenta a conduta\nCORRETA no hospital de cuidados médicos avançados.","options":{"A":"Incluir o paciente no programa de transplante hepático e manter controle clínico.","B":"Realizar acompanhamento com esclerose endoscópica das varizes sucessivas.","C":"Submeter o paciente a esplenectomia total associada com ressecção das varizes.","D":"Operação esplênica com desconexão portavarizes perigástricas e intragástricas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-326002","number":"326002","sourceNumber":"326002","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, procurou atendimento médico com\nquadro de fadiga, náusea e icterícia de\naparecimento há 10 dias. Nega dor abdominal e\nemagrecimento relevante. Nega comorbidades prévias e uso de medicamentos nos últimos 3\nmeses. A mãe da paciente tem o diagnóstico de Artrite Reumatoide. Realizou ultrassonografia\nabdominal que não mostrou dilatação de vias biliares. Com relação ao quadro clínico descrito\nacima, assinale a conduta CORRETA para manejo do quadro.","options":{"A":"Realização de CPRE (Colangiopancreatografia Retrógrada Endoscópica) para melhor\ninvestigação de icterícia.","B":"Realização de biópsia hepática para melhor investigação.","C":"Avaliação de exames hepáticos, sorologia de hepatites virais e doenças autoimunes.","D":"Internação para melhor avaliação de transplante hepático."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-301018","number":"301018","sourceNumber":"301018","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual das terapias a seguir está associada à melhora de desfechos em pacientes com\nhepatite alcoólica?","options":{"A":"Expansão volêmica com albumina.","B":"Uso de betabloqueadores não seletivos.","C":"Terapia nutricional.","D":"Profilaxia com antimicrobianos."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-259388","number":"259388","sourceNumber":"259388","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 52 anos vai ao pronto atendimento queixando-se de dor e aumento do\nvolume abdominal há 2 dias. É portador de cirrose por hepatopatia alcoólica e faz uso de\npropranolol 40 mg 2x ao dia. Ao exame físico, PA = 100/70 mmHg, FC = 58 bpm, FR = 16 ipm,\nSpO? 97% (em ar ambiente), TAx = 38,1°C. Apresenta-se alerta, desorientado no tempo e no\nespaço. As mucosas estão coradas e ictéricas. O abdome apresenta-se globoso, distendido, com\nsubmacicez móvel e esplenomegalia. Há edema simétrico e depressível dos membros inferiores.\nRealizou-se paracentese com retirada de 20 ml de líquido ascítico.\n\nExames de laboratório: Hb = 10,5 g/dl; LG = 11.670/mm³; NS = 8.650/mm³; Plq = 120.000/mm³;\nAST = 83 U/L; ALT = 57 U/L; RNI = 1,6; BT\n3,4 mg/dl; Cr = 0,9 mg/dl; albumina = 1,8 g/dl; proteína\nC-reativa = 94 mg/L.\n\nExame do líquido ascítico: células nucleadas 900/mm³; neutrófilos 40%; albumina = 0,4 g/dl. No\nmanejo clínico inicial deste paciente, a seguinte conduta está INADEQUADA:","options":{"A":"Administração de albumina parenteral.","B":"Prescrição de ceftriaxona.","C":"Suspensão do betabloqueador.","D":"Prescrição de furosemida e espironolactona."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-260254","number":"260254","sourceNumber":"260254","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 45 anos de idade, sexo feminino, etilista pesada, com interrupção do hábito\nhá seis meses, é admitida no pronto-socorro\ncom quadro de confusão mental, ascite e icterícia.\n\nSegundo relato dos familiares, a paciente é portadora de cirrose hepática alcoólica e iniciou com\ndiarreia e dor abdominal difusa há três dias, evoluindo, posteriormente, com confusão mental e\nrebaixamento do nível de consciência. De acordo com esse caso clínico, assinale a alternativa\nincorreta.","options":{"A":"A ascite da paciente é secundária à hipertensão portal, cujo gradiente entre a albumina sérica e\na do líquido ascítico é inferior a 1,1\ng/dL.","B":"A paciente encontra-se em encefalopatia hepática, provavelmente desencadeada por distúrbio\nhidroeletrolítico subjacente, devendo-se considerar a possibilidade de peritonite bacteriana\nespontânea (PBE).","C":"Para o cálculo do escore de MELD (modelo de disfunção hepática em estágio final) da paciente,\nutilizam-se as seguintes variáveis: creatinina, bilirrubina e RNI séricos.","D":"O diagnóstico de PBE é obtido quando a contagem de polimorfonucleares, no líquido ascítico,\nfor superior a 250 células/mm³."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-262937","number":"262937","sourceNumber":"262937","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Analise as s afirmativas a seguir sobre cirrose hepática e insuficiência hepática. I. A\nesteatose hepática não alcoólica pode evoluir para acúmulo progressivo de cicatrizes fibróticas e\nlevar à cirrose. Nesses casos, a incidência anual de surgir hepatocarcinoma primário chega a 3%\nou mais. II. Dos pacientes expostos ao vírus da hepatite C, apenas 10% desenvolvem hepatite\ncrônica, ao contrário dos expostos à hepatite B ? para a qual existe vacina eficaz ?, quando mais\nde 50% desenvolvem a forma crônica. III. O transplante hepático é o tratamento de escolha para\npacientes com cirrose descompensada devido à colangite biliar primária. A maioria são mulheres\nem torno dos 50 anos de idade, sem história de etilismo. Estão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-239812","number":"239812","sourceNumber":"239812","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher de 50 anos de idade apresenta-se para acompanhamento no ambulatório\nde clínica médica. Queixa-se de dor em\nquadrante superior direito do abdome de início há alguns\nmeses. Iniciou investigação ambulatorial por medo de hepatopatia, visto que o pai morreu de\ncirrose (não sabe a causa) e ela não queria deixar de beber. Refere consumo de 2 latas de cerveja\n(350 ml), apenas aos sábados. A avaliação inicial mostra uma paciente de 1,50 m de altura e 88 kg.\nEla traz exames laboratoriais do último mês: RNI 1; glicemia de jejum de 180 mg/dl; bilirrubinas\ntotais de 1 mg/dl (VR até 1.2); fosfatase alcalina de 178 (VR até 110); Aspartato Aminotransferase\n(AST) 130 (VR até 42) e Alanina Aminotransferase (ALT) de 150 (VR até 44). Ultrassonografia,\nrealizada há 1 ano, demonstra aumento de ecogenicidade do fígado, com trato biliar normal. A\npaciente traz biópsia hepática, realizada no contexto de acompanhamento com médico\nespecialista: esteatose macro e microvesicular, fibrose portal e lobular, leucócitos\npolimorfonucleares difusos, hialina de Mallory. Colorações para ferro são negativas. Em relação ao\ncaso hipotético acima, qual o diagnóstico MAIS PROVÁVEL:","options":{"A":"Doença hepática alcoólica.","B":"Hepatite C.","C":"Esteato-hepatite não alcoólica (NASH).","D":"Hepatite autoimune."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-253908","number":"253908","sourceNumber":"253908","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Considere um homem de 48 anos de idade com cirrose hepática CHILD C, MELDNa-16\npor HCV, diabetes tipo 2, hipertensão e\ndislipidemia. Vem em uso de: atorvastatina 20 mg/dia,\nglibenclamida 10 mg/dia, propranolol 60 mg/dia e gliclazida MR 90 mg/dia (há 2 semanas). Foi\nadmitido no pronto socorro por hemorragia digestiva alta varicosa, hipoglicemia recorrente e piora\nde sua função hepática (MELD = 32). Além do tratamento endoscópico, a droga com melhor\nprobabilidade de controle do sangramento e da hipoglicemia é:","options":{"A":"Noradrenalina","B":"Terlipressina","C":"Octreotide","D":"Midodrina"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-200466","number":"200466","sourceNumber":"200466","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a principal causa de transplante hepático, atualmente no Brasil:","options":{"A":"Cirrose por álcool.","B":"Cirrose por hepatite B.","C":"Cirrose por hepatite C.","D":"Cirrose por esteatose hepática não alcoólica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-200485","number":"200485","sourceNumber":"200485","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A hipertensão porta resulta da obstrução do fluxo sanguíneo portal e é classificada de\nacordo com o nível da obstrução. A principal alteração fisiopatológica do evento é o surgimento de\nvias venosas que contornam o obstáculo e alcançam o sistema ázigos, levando ao aparecimento\ndas varizes esofágicas. Na esquistossomose, assinale a principal via hepatofugal que alimenta as\nvarizes esofágicas:","options":{"A":"Veia gastro-omental esquerda.","B":"Veia umbilical recanalizada.","C":"Vasos gástricos curtos.","D":"Veia gástrica esquerda."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217189","number":"217189","sourceNumber":"217189","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente cirrótico dá entrada no setor de emergência com dor abdominal. O cirurgião\ncolhe ascite e obtém um valor de albumina igual\na 2,5 g/dl. Sabendo que o valor da albumina sérica\né de 3,75 g/dl pode-se concluir que:","options":{"A":"Peritonite secundária é provável e o paciente deve ser submetido a laparotomia.","B":"Tuberculose abdominal é provável. Instituir esquema RIP.","C":"Provável carcinomatose. Enviar material para pesquisa de células neoplásicas.","D":"Os valores são compatíveis com cirrose e hipertensão porta, avaliar leucometria diferencial para\ndecidir tratar peritonite primária."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-201618","number":"201618","sourceNumber":"201618","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Adolescente, filho de pais consanguíneos, é internado com quadro de hepatopatia\ncrônica e presença de anéis de\nKayser-Fleischer ao exame oftalmológico. O diagnóstico mais\nprovável é:","options":{"A":"Hepatite autoimune.","B":"Doença de Wilson.","C":"Colangite esclerosante primária.","D":"Fibrose hepática congênita."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-211947","number":"211947","sourceNumber":"211947","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Peritonite Bacteriana Espontânea (PBE) é definida como infecção bacteriana do\nlíquido ascítico na ausência de uma fonte\nintra-abdominal de infecção tratável cirurgicamente. Com\nrelação a esta patologia, assinale a alternativa INCORRETA:","options":{"A":"A PBE pode ocorrer em pacientes com síndrome nefrótica, a menos comumente, na insuficiência\ncardíaca congestiva.","B":"É extremamente raro que os pacientes com líquido ascítico contendo alta concentração de\nproteínas desenvolvam PBE, tais como aqueles com carcinomatose peritoneal.","C":"Os patógenos mais comuns em adultos com PBE são os germes aeróbicos como o\nStreptococcus pneumoniae e o Staphylococcus aureus.","D":"Acredita-se que a translocação bacteriana do trato gastrointestinal é um passo importante na\npatologênese da PBE."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-203939","number":"203939","sourceNumber":"203939","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a cirrose hepática e suas complicações, assinale a alternativa INCORRETA:","options":{"A":"O diagnóstico da síndrome hepatorrenal deve ser considerado em um paciente com insuficiência\nrenal associada à doença hepática avançada,\ndevendo-se, porém, excluir outras causas de\ninsuficiência renal aguda.","B":"As variáveis utilizadas para o cálculo do escore de MELD (modelo de disfunção hepática em\nestágio final) são RNI, creatinina, bilirrubina e albumina séricas.","C":"A Peritonite Bacteriana Espontânea (PBE) é uma complicação grave dos pacientes cirróticos e\ncaracteriza-se pela contagem absoluta de neutrófilos, superior a 250 céls/mm3, no líquido ascítico.","D":"A diferença entre a dosagem da albumina sérica e a do líquido ascítico, quando superior a 1,1\ng/dl, sugere que a causa da ascite seja a hipertensão portal."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-200475","number":"200475","sourceNumber":"200475","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 50 anos de idade, portador de hepatopatia alcoólica (cirrose hepática)\né levado ao serviço de emergência com quadro\nde letargia, desorientação, comportamento\ninapropriado e alteração da personalidade. O exame físico mostra um paciente com ascite, icterícia\ne aranhas vasculares. Importante no seu exame laboratorial é a presença hiponatremia (sódio de\n128 mEq/L) e amônia sérica aumentada. Sistema hemodinâmico e respiratório preservado.\n\nTomografia computadorizada (TC) do cérebro sem contraste evidencia atrofia leve generalizada.\nEm relação ao quadro clínico descrito acima,\nassinale o tratamento mais apropriado:","options":{"A":"Administrar lactulose.","B":"Usar ácidos graxos de cadeia curta.","C":"Usar flumazenil (antagonista de benzodiazepínicos endógenos).","D":"Infundir cloreto de sódio a 3% para corrigir rapidamente o quadro hiponatrêmico."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-211963","number":"211963","sourceNumber":"211963","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à peritonite associada à Diálise\nPeritoneal Ambulatorial Crônica (DPAC):","options":{"A":"A peritonite é uma das complicações mais comuns da DPAC.","B":"A peritonite associada à DPAC é tratada pela administração intraperitoneal de antibióticos, mais\ncomumente a vancomicina injetada através do cateter de diálise.","C":"Os pacientes apresentam-se com dor abdominal, febre e dialisado peritoneal turvo contendo\nmais de 100 leucócitos/mm3, com mais de 50%\ndas células sendo neutrófilos.","D":"Cerca de 75% das infecções devem-se a micro-organismos Gram-positivos, com\nStaphylococcus epidermidis respondendo por 30-50% dos casos."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-211953","number":"211953","sourceNumber":"211953","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite é o acúmulo patológico de fluidos dentro da cavidade peritoneal. Assinale a\nalternativa INCORRETA com relação a esta patologia:","options":{"A":"A ascite é complicação mais comum de cirrose, com aproximadamente 50% dos pacientes\ncirróticos compensados desenvolvendo ascite após 10 anos de diagnóstico.","B":"O aparecimento de ascite é um fator prognóstico importante para um resultado desfavorável em\npacientes com cirrose devido à sua associação com a ocorrência de peritonite bacteriana\nespontânea, insuficiência renal, pior qualidade de vida e maior probabilidade de morte dentro de\ndois a cinco anos.","C":"Os dois principais fatores por trás da formação de ascite nos pacientes cirróticos são a trombose\nvenosa mesentérica crônica e a hipertensão\nportal.","D":"A retenção renal de sódio é induzida pela ativação de renina-angiotensina-aldosterona e\nsistemas nervosos simpáticos, que promovem reabsorção de sódio pelo túbulo renal proximal e\ndistal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217173","number":"217173","sourceNumber":"217173","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente vítima de tentativa de auto-extermínio com 2 caixas de paracetamol dá\nentrada no setor de emergência. A respeito do tratamento adequado pode-se afirmar:","options":{"A":"Hemoperfusão ou hemodiálise consistem na melhor terapia.","B":"Uso de n-acetilcisteína via oral ou endovenosa é a conduta correta.","C":"Uso de azul de metileno endovenoso.","D":"Utilizar apenas carvão ativado."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-217227","number":"217227","sourceNumber":"217227","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa que apresenta um sinal de alerta da insuficiência hepática aguda\nprogressiva:","options":{"A":"Diminuição do tamanho do fígado.","B":"Diminuição das bilirrubinas.","C":"Acidose respiratória.","D":"Sangramento digestivo."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-219478","number":"219478","sourceNumber":"219478","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O processo obstrutivo do sistema venoso portal provoca a elevação da pressão venosa\nportal para níveis > 10 mmHg. Em relação a fisiopatologia da hipertensão portal podemos afirmar:","options":{"A":"O nível de obstrução do sistema venoso portal interfere radicalmente na resistência ao fluxo\nvenoso portal.","B":"A pressão da veia hepática Ocluída é igual tanto na cirrose como na esquistossomose.","C":"Na síndrome de Budd-Chiari, a pressão sinusoidal está normal.","D":"O sistema venoso portal é avalvular."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-184569","number":"184569","sourceNumber":"184569","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente 50 anos, sexo masculino, apresentou hematêmese. Realizou endoscopia\ndigestiva alta e submetido a ligadura elástica\nde varizes gástricas. Está recebendo a seguinte\nsolução venosa no hospital: Salina 0,9% 1L/8h; Glicose 5% 1L/8h; Salina 0,9% 1L + 20mmol\nKCL/8h; O preceptor da residência explica ao residente que há um erro na solução acima. Qual a\nexplicação mais provável dada ao jovem médico?","options":{"A":"Paciente possivelmente está hipocalêmico e deve receber mais potássio.","B":"Paciente já apresenta tendência a sódio elevado e necessita solução glicosada.","C":"Paciente sofreu muitas perdas e necessita de reposição rápida.","D":"Paciente com propensão a edema, volume deve ser restrito."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181292","number":"181292","sourceNumber":"181292","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O transplante hepático é, hoje, um procedimento mundialmente aceito como\nmodalidade terapêutica para doenças hepáticas\ngraves e outras patologias metabólicas que\nimplicam perda de qualidade de vida. A seleção de receptores para o transplante de fígado no país\ndepende de sua pontuação no escore MELD. Considerando os critérios dessa doença, assinale a\nalternativa que não apresenta um dos exames necessários para a confirmação diagnóstica.","options":{"A":"Creatinina.","B":"INR.","C":"Albumina.","D":"Bilirrubina."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181034","number":"181034","sourceNumber":"181034","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente 42 anos, sexo feminino, portadora de cirrose hepática relacionada à Hepatite\nC e etilismo, apresenta ascite com\nnecessidade de paracenteses frequentes de grande volume.\n\nSobre as terapias indicadas abaixo, marque a alternativa INCORRETA.","options":{"A":"TIPS (Transjugular Intrahepatic portosystemic shunt) se tratamento clínico falhar.","B":"Restrição hídrica para menos de 2 litros ao dia.","C":"Restrição de sódio para menos de 2g/dia.","D":"Espirolactona 100mg/dia."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-182006","number":"182006","sourceNumber":"182006","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente grave, inconsciente, sem antecedentes mórbidos conhecidos, dá entrada na\nUTI com ascite volumosa e dor abdominal a palpação em todos os quadrantes. Você é chamado\npara realização de paracentese cujo resultado mostra albumina da ascite de 1,0g/dL. A albumina\nsérica é de 2,2g/dL. Podemos afirmar que corresponde a:","options":{"A":"Transudato pois GASA maior que 1,1.","B":"Transudato pois GASA menor que 1,1.","C":"Exsudato pois GASA maior que 1,1.","D":"Exsudato pois GASA menor que 1,1."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-179220","number":"179220","sourceNumber":"179220","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com encefalopatia hepática que se apresenta apático, letárgico, desorientado\ne com fala comprometida. De acordo com os\ncritérios de West Haven de gradação clínica de\nencefalopatia hepática, assinale a alternativa que apresenta o estágio que MELHOR descreve o\nestado clínico desse paciente.","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-179068","number":"179068","sourceNumber":"179068","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, sexo masculino, 60 anos, etilista crônico, procura o posto de saúde de seu\nbairro devido a fraqueza e aumento importante do volume abdominal nos últimos 2 meses. Edema\nde membros inferiores e icterícia progressiva percebidos na última semana. O médico realizou o\nexame físico. Qual dos sinais abaixo pode ter sido encontrado e qual a explicação fisiopatológica\nCORRETA para tal achado?","options":{"A":"\"Flapping\" devido à encefalopatia hepática com redução da metabolização hepática de\ncompostos nitrogenados absorvidos no intestino.","B":"Circulação colateral tipo porta com fluxo centrípeto devido a recanalização da veia umbilical.","C":"Ginecomastia e atrofia testicular devido a redução da metabolização da prolactina e testosterona\npelo fígado.","D":"Telangiectasias em tronco e membros superiores devido a redução da produção de fatores de\ncoagulação pelo fígado."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-184601","number":"184601","sourceNumber":"184601","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O fator mais estreitamente relacionado à mortalidade por sangramento de varizes\nesofágicas é:","options":{"A":"Contagem de plaquetas.","B":"Comorbidades associadas.","C":"Reserva funcional hepática.","D":"Etiologia da hipertensão portal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158271","number":"158271","sourceNumber":"158271","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente cirrótico com ascite volumosa é atendido no setor de emergência do hospital\ncom dor abdominal a palpação superficial e\nprofunda em todos os quadrantes. Os exames mostram\nalbumina sérica de 2,8 g/dl e albumina da amostra de ascite de 4,0 g/dl. Desta forma podemos\nafirmar que corresponde a:","options":{"A":"Exsudato, pois GASA menor que 1,1;","B":"Exsudato, pois GASA maior que 1,1;","C":"Transudato, pois GASA menor que 1,1;","D":"Transudato, pois GASA maior que 1,1."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-155221","number":"155221","sourceNumber":"155221","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a abordagem do sangramento por varizes esofágicas no cirrótico portador de\nhipertensão portal, e também sobre a profilaxia primária e secundária de hemorragia digestiva\nnestes pacientes, marque a alternativa INCORRETA.","options":{"A":"A profilaxia secundária é realizada com ligaduras elásticas, que devem ser repetidas até a\nerradicação total destas varizes, além da administração de beta bloqueadores.","B":"O uso do balão de Sengstaken-Blakemore deve ser reservado apenas para pacientes que não\ntem acesso à endoscopia imediatamente ou que necessitam estabilização clínica antes do\nprocedimento endoscópico.","C":"A profilaxia primária com betabloqueadores ou ligadura elástica está indicada apenas para\npacientes com cirrose moderada a avançada.","D":"O uso do octreotide deve ser considerado em todos os pacientes cirróticos que apresentam\nsangramento por varizes esofageanas."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-163952","number":"163952","sourceNumber":"163952","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com diagnóstico de cirrose hepática com varizes esofagianas apresenta\nquadro de hemorragia digestiva alta com\ninstabilidade hemodinâmica (PA = 90 x 50 mmHg; FC =\n128 bpm). A conduta a ser tomada inicialmente é:","options":{"A":"Introdução de lactulona para profilaxia de encefalopatia, transfusão de plasma e plaquetas,\nseguida de endoscopia digestiva alta.","B":"Reposição volêmica cuidadosa, introdução de droga vasoconstritora (terlipressina ou octreotida)\ne solicitar endoscopia digestiva alta após\nestabilização.","C":"Introdução de omeprazol endovenoso, expansão plasmática com solução salina e droga\nvasoconstritora (noradrenalina).","D":"Passagem de balão gastroesofágico (Sengstaken-Blakemore) e utilização de drogas vasoativas\naté estabilização hemodinâmica."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158231","number":"158231","sourceNumber":"158231","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente admitido na enfermaria do hospital com quadro de letargia, aumento do\nvolume abdominal, icterícia e edema de membros\ninferiores. Etilista diário de 1 litro de cachaça.\nNega febre, disúria, dor abdominal, tosse ou qualquer outro sintoma infeccioso. Ao exame clínico\napresenta-se com abdome volumoso com sinal do piparote positivo, edema importante de membros\ninferiores, teleangiectasias e ginecomastia. Nega internações prévias. Exames laboratoriais\nrevelam plaquetas de 100.000 mm3, TGO 280 UI/L, TGP 100 UI/L, bilirrubina total: 8,4 mg/dl, RNI:\n1,53. Considerando o quadro clínico descrito, assinale a alternativa CORRETA.","options":{"A":"O paciente apresenta contraindicação absoluta a realização de paracentese devido a\nplaquetopenia e distúrbio de coagulação com alto risco de complicação.","B":"O paciente apresenta indicação de norfloxacino para profilaxia de peritonite bacteriana\nespontânea.","C":"O paciente apresenta indicação de hidroclorotiazida ou clortalidona associado a espironolactona\npara tratamento da ascite.","D":"O paciente apresenta indicação de endoscopia digestiva alta para avaliação de presença de\nvarizes esofágicas."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158233","number":"158233","sourceNumber":"158233","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente admitido na enfermaria do hospital com quadro de letargia, aumento do\nvolume abdominal, icterícia e edema de membros\ninferiores. Etilista diário de 1 litro de cachaça.\nNega febre, disúria, dor abdominal, tosse ou qualquer outro sintoma infeccioso. Ao exame clínico\napresenta-se com abdômen volumoso com sinal do piparote positivo, edema importante de\nmembros inferiores, teleangiectasias e ginecomastia. Nega internações prévias. Exames\nlaboratoriais revelam plaquetas de 100.000mm3, TGO 280UI/L, TGP 100UI/L, bilirrubina total:\n8,4mg/dL, RNI:1,53. Considerando o quadro clínico descrito, assinale a alternativa INCORRETA.","options":{"A":"O paciente apresenta quadro clínico laboratorial sugestivo de hepatite alcoólica sobreposta a\ncirrose hepática.","B":"No caso desse paciente apresentar índice de Maddrey maior que 16, está indicado o tratamento\nmedicamentoso para hepatite alcoólica.","C":"No caso de o paciente evoluir com piora progressiva devido a piora dos critérios de falência\nhepática, ele ainda assim não seria candidato a transplante hepático.","D":"No caso desse paciente, se for necessário, o corticoide é a droga de escolha no tratamento da\nhepatite alcoólica."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-158136","number":"158136","sourceNumber":"158136","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente portador de cirrose hepática (Child-Pugh B9) por causa de hepatite C\ncompareceu ao serviço de urgência com\nqueixa de intolerância ao exercício e dispneia aos\nesforços, além de fezes escurecidas com aspecto de borra de café havia 2 dias. Ao exame físico,\napresentava PA de 120/70 mmHg, FC 93 bpm e FR 18 ipm. Estava hipocorado, hidratado, alerta e\norientado quanto ao tempo e espaço. Os exames respiratório e cardiovascular estavam normais. O\nexame do abdômen revelava esplenomegalia e circulação colateral do tipo cabeça de medusa, e\nnão havia sinais clínicos de ascite. Considerando o caso descrito, é INCORRETO afirmar que:","options":{"A":"A octreotide é uma opção farmacológica para controle do sangramento em varizes de esôfago e\ndeve ser iniciado mesmo antes da\ngastroduodenoscopia.","B":"O bloqueador de bomba de prótons intravenoso em altas doses deve ser iniciado no momento\nda admissão e mantido pelo menos até o\nesclarecimento etiológico da hemorragia.","C":"A transfusão de concentrado de hemácias deve ser realizada se necessária, visando manter os\nníveis de hemoglobina no sangue em torno de 7 a 8 g/dl.","D":"A antibioticoterapia profilática para peritonite bacteriana espontânea com ceftriaxona não está\nindicada neste caso, pois o paciente não apresenta ascite."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-159486","number":"159486","sourceNumber":"159486","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente que não usa medicamentos e apresenta icterícia discreta exibe o seguinte\npadrão laboratorial: hiperbilirrubinemia\npredominantemente direta, fosfatase alcalina muito elevada,\ntransaminases levemente elevadas (1,5 x), albumina normal. Assinale a alternativa que apresenta,\nCORRETAMENTE, a investigação que deve ser feita para esse caso.","options":{"A":"Embora esse padrão laboratorial seja atípico nas hepatites virais, devido à elevada prevalência\ndestas, a investigação deve ser iniciada\ncom as sorologias para hepatite B e C.","B":"A investigação deve ser iniciada com a Ultrassonografia (US) e, caso esta não revele dilatação\ndos ductos biliares, a Colangiopancreatografia\nEndoscópica Retrógrada (CPER) é o próximo passo,\npor ser mais sensível que a US.","C":"Uma vez excluído coledocolitíase na US, o paciente deverá ser submetido à biópsia hepática.","D":"Se a US for normal, Anticorpos Anti-Mitocôndria (AMA) devem ser solicitados e, nesse caso,\nAMA positivo constitui indicação de biópsia hepática."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-129235","number":"129235","sourceNumber":"129235","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 48 anos, internado devido à cirrose hepática descompensada com ascite,\nevoluiu com encefalopatia hepática, com\nqueda do leito e entorse do cotovelo direito, cursando com\ndor importante. Ultrassonografia abdominal revelou fígado diminuído de tamanho com bordas\nirregulares, ascite volumosa e veia porta de calibre normal. Endoscopia digestiva alta sem\nalterações. Paracentese diagnóstica revelou proteína total do líquido ascítico de 1 g/dl sem sinais\nde Peritonite Bacteriana Espontânea (PBE). Albumina sérica de 2,5 g/dl. Sem relato de PBE\nanteriormente. Sobre o caso clínico descrito, assinale a alternativa CORRETA:","options":{"A":"A analgesia deve ser realizada devido a entorse de cotovelo com anti-inflamatório não\nesteroidal.","B":"A presença de veia porta de calibre normal e a ausência de varizes esofagianas exclui a\npossibilidade de hipertensão portal.","C":"A profilaxia primária para PBE pode beneficiar esse paciente.","D":"A albumina deve ser infundida após toda paracentese independentemente da quantidade de\nlíquido retirada com impacto na redução da disfunção renal aguda."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-131735","number":"131735","sourceNumber":"131735","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Osmar, 62 anos, portador de cirrose hepática de etiologia indeterminada, vem\napresentando alterações do comportamento nas\núltimas semanas. Com relação à encefalopatia\nhepática, assinale a alternativa INCORRETA:","options":{"A":"Confusão mental e alteração do ciclo sono-vigília são sintomas comuns.","B":"Os sintomas podem ser classificados em subclínicos e de graus 1 a 4.","C":"Sangramento do trato gastrointestinal e presença de infecções são causas comuns.","D":"A utilização de antibióticos via oral não absorvíveis ainda é controversa, devendo ser utilizados\napenas em casos especiais.","E":"O uso de lactulose está indicado, pois acarreta redução de compostos ricos em amônia a nível\ncerebral."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-129243","number":"129243","sourceNumber":"129243","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a cirrose hepática e suas causas, assinale a alternativa CORRETA.","options":{"A":"A cirrose biliar primária acomete predominantemente homens e é caracterizada por prurido,\nfadiga e\n\nicterícia. O anticorpo anti-mitocôndrias é positivo.","B":"A hemocromatose hereditária ocorre predominantemente em homens podendo cursar com\nartralgia e\n\naumento de aminotransferases. A saturação de transferrina costuma ser maior que 50%.","C":"A hepatite autoimune é mais comum em homens e cursa com hipergamaglobulinemia e\npositividade\n\ndo fator antinuclear.","D":"A esteato-hepatite não alcoólica pode progredir para cirrose hepática e o diagnóstico é\nconfirmado por\n\nbiopsia hepática evidenciando lesões centrolobulares que é patognomônico da doença."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-109885","number":"109885","sourceNumber":"109885","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quais são os critérios de Child-Turcotte modificados por Pugh para prognosticar a\ncirrose hepática?","options":{"A":"TAP, albumina, bilirrubinas, ascite e encefalopatia.","B":"AST, ALT, GGT, TAP e fosfatase alcalina.","C":"Ascite, síndrome hepatorrenal, GGT, TAP e bilirrubinas.","D":"Encefalopatia, TAP, albumina, bilirrubinas e ALT."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-103094","number":"103094","sourceNumber":"103094","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 56 anos, portador de hepatite C há 10 anos, é levado ao Pronto\nAtendimento (PA) devido ao aumento de volume\nabdominal acompanhado de confusão mental e\nletargia com 1 semana de evolução. Fazia uso domiciliar de furosemida 80 mg há 1 ano. Realizou\nendoscopia digestiva há 1 mês, por solicitação do médico assistente, que revelou varizes\nesofágicas de grosso calibre. O paciente apresentou-se estável hemodinamicamente, pálido, com\npresença de aranhas vasculares, ginecomastia e com abdome com ascite volumosa, sendo\nrealizado paracentese propedêutica, que revelou: celularidade = 370 leucócitos, sendo 55% de\npolimorfonucleares; gradiente soro-ascite de albumina > 1; glicose = 70 mg/dl. Considerando o caso\nclínico descrito, assinale a alternativa CORRETA:","options":{"A":"Realizar paracentese total, infundir albumina conforme a quantidade de líquido retirada, iniciar\nceftriaxona para tratamento de peritonite bacteriana espontânea e internar o paciente com\nassociação de furosemida, espironolactona e lactulose.","B":"Rastrear a causa da descompensação da ascite, sendo, nesse caso, mais provável o mau uso\ndo diurético ou a necessidade de aumento de\ndose ou associação de fármaco.","C":"Internar para investigação da encefalopatia e piora da ascite. Rastreio infeccioso, de hemorragia\ndigestiva e de distúrbio eletrolítico, além de suspensão inicial dos diuréticos, início de\nlactulose e\nultrassom abdominal são medidas a serem realizadas para investigação e tratamento do quadro\nclínico em questão.","D":"Indicar profilaxia primária para sangramento varicoso e a droga de escolha deve ser os\nbetabloqueadores, a exemplo do metoprolol."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-109899","number":"109899","sourceNumber":"109899","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O tratamento de escolha para a litíase da vesícula biliar é a colecistectomia. Qual das\nsituações clínicas a seguir não faz parte das indicações de colecistectomia em portadores\nassintomáticos de colelitíase?","options":{"A":"Vesícula calcificada","B":"Cálculos maiores que 2,5 cm","C":"Anemia falciforme","D":"Cirrose hepática"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-88273","number":"88273","sourceNumber":"88273","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma mulher de 50 anos de idade vai a uma clínica devido a testes hepáticos anormais.\nAo exame físico: estatura = 160 cm; peso = 107\nkg e índice de massa corporal = 43 kg/m². Relata\nexcesso de peso durante a maior parte de sua vida e nega uso de álcool. Foi diagnosticado\ndiabetes mellitus insulino-dependente. Exames laboratoriais: albumina = 3,5 g/dl; bilirrubina = 0,9\nmg/dl; fosfatase alcalina = 148 U/L; AST = 99 U/L; ALT = 72 U/L; e gama GT = 359 U/L. Níveis de\nglicose variam de 110 a 260 mg/dl. Testes sorológicos para vírus negativos. Ultrassom de fígado:\nesteatose grau II. Assinale a alternativa INCORRETA:","options":{"A":"Elevações de enzimas hepáticas devem ser investigadas, principalmente na ausência de doença\nhepática prévia, uso abusivo de álcool e medicamentos.","B":"No caso da paciente acima, a obesidade e o diabetes podem estar contribuindo no quadro de\nesteato-hepatite apresentada pela paciente.","C":"A existência de uma entidade nosológica esteato-hepatite não alcoólica (NASH) pode ser\ndiagnosticada na paciente acima, muito embora seja uma doença de exclusão.","D":"Os achados histológicos de esteatose, infiltrado celular polimorfonuclear, necrose e fibrose na\nbiópsia hepática levam ao diagnóstico de NASH.","E":"A redução de peso, o controle do diabetes, o tratamento da hiperlipidemia e a atividade física\naeróbica, mostraram ser mais eficazes que o uso\nde medicamentos como o ácido ursodesoxicólico\nna redução das enzimas e na progressão para a cirrose."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-69410","number":"69410","sourceNumber":"69410","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Uma paciente de 48 anos, alcoólatra (média de 80 g/dia de álcool, durante 10 anos),\nchega ao PS com ascite, dor abdominal em\nHCD, icterícia e piora muito rápida do estado geral. Os\nexames revelaram: HB: 12,8 g/dl, leucócitos: 22.000 e acentuado desvio à E. TGO: 400 U/L, TGP:\n\n290. Neste momento, o principal diagnóstico, para este paciente, é:","options":{"A":"Cirrose hepática descompensada.","B":"Infecção do líquido ascítico em paciente cirrótica.","C":"Hepatite alcoólica.","D":"Provável hepatite viral aguda em paciente portadora de cirrose alcoólica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-48586","number":"48586","sourceNumber":"48586","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, 45 anos de idade, etilista desde os 20 anos, apresenta há\ncerca de 4 meses quadro de mal-estar associado a náuseas com alguns episódios de vômitos.\n\nRefere ainda febrícula. Na investigação, observou-se níveis de Aspartato Aminotransferase (ATS) 3\nvezes os valores de referência, a Alanina Aminotransferase (ALT) nos limites da normalidade e\naumento nos níveis de gamaglutamil transpeptidase. Proteína C-reativa aumentada. Assinale a\nalternativa INCORRETA:","options":{"A":"Pacientes portadores de hepatopatia alcoólica frequentemente têm outros órgãos acometidos,\ncomo coração, músculos e nervos, sendo o\npâncreas o órgão mais acometido.","B":"Na hepatite alcoólica grave, recomenda-se o uso do corticoide, com o objetivo de aumentar a\nregeneração de hepatócitos e suprimir a inflamação nos pacientes com lesão hepática grave.","C":"A abstinência alcoólica é a conduta mais importante nos pacientes com hepatopatia alcoólica.","D":"Recomenda-se uma dieta adequada com ingestão calórica de 35-40 kcal/kg.","E":"O consumo adequado de proteínas na hepatopatia alcoólica deve ser restrito."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-33849","number":"33849","sourceNumber":"33849","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com relação à hepatopatia alcoólica, é INCORRETO afirmar que:","options":{"A":"Na hepatopatia alcoólica, as transaminases mostram-se elevadas, habitualmente > 400 UI e a\nrelação AST/ALT > 1.","B":"Menos de um terço dos etilistas desenvolvem hepatopatia alcoólica.","C":"As mulheres apresentam maior susceptibilidade à lesão hepática alcoólica quando comparadas\naos homens.","D":"Os pacientes com hepatite alcoólica grave, definida por uma função discriminativa > 32, são\ncandidatos ao tratamento com glicocorticoides ou pentoxifilina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-23202","number":"23202","sourceNumber":"23202","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na hepatite alcoólica usa-se o seguinte critério para a indicação de tratamento com\ncorticosteroide:","options":{"A":"A chamada função discriminante (FD), pela fórmula: FD = 4,6 x [(TPp ? TPc) + BT] com o\nresultado sendo maior que 32. Onde: TPp =\nTempo de protrombina do paciente ( em segundos); T\nPc = Tempo de Protrombina controle (em segundos); BT = Bilirrubina sérica total (mg/dL).","B":"A dosagem sérica da enzima aspartato aminotransferase (AST) maior que 4 (quatro) vezes o\nvalor de referência.","C":"Febre acima de 38,0º C e anemia com valor de hemoglobina < 9,0 g/dL associadas a dosagem\nde gama- glutamil transpeptidase ( GT) acima\nde 600 mg/ dL.","D":"Líquido ascítico com contagem de leucócitos acima de 500 células / µL, sendo que destes mais\nde 250 células /µL são mononucleares."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-349133","number":"349133","sourceNumber":"349133","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 43 anos procura a unidade de pronto atendimento por aumento do\nvolume abdominal há 4 semanas, associado a edema\nde membros inferiores. Ele nega ingestão de\nbebida alcoólica. Não possui alteração do hábito intestinal ou sintomas dispépticos. Relata que,\nquando tinha 22 anos, sofreu um atropelamento com fratura de tíbia e recebeu 2 unidades de\nconcentrado de hemácias, quando foi diagnosticado com hepatite por vírus C. Não possui histórico\nmédico familiar relevante. Ao exame físico, apresenta sinais vitais normais, mucosas hipocoradas\n\n+/4+ e icterícia +/4+. Os exames do aparelho cardiovascular e respiratório estão normais. O\nabdome apresenta-se globoso, com ruídos\nhidroaéreos presentes, indolor à palpação e com sinal\nde Piparote e macicez móvel positivos. Presença de edema em membros inferiores; pulsos arteriais\npresentes bilateralmente. Uma paracentese de alívio foi realizada com a drenagem de 2 litros de\nlíquido ascítico de aspecto amarelo citrino. A contagem de células veio com 450 leucócitos por\nmm³, sendo 320 polimorfonucleares. Não houve acidente de punção e o diferencial entre a\nalbumina sérica e ascítica teve resultado de 1,3. Considerando o caso clínico apresentado, a\nconduta terapêutica mais adequada para tratamento dessa complicação é prescrever:","options":{"A":"Ceftriaxona.","B":"Gentamicina.","C":"Levofloxacino.","D":"Penicilina cristalina."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-352577","number":"352577","sourceNumber":"352577","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Jovem, sexo feminino, 18 anos, procura atendimento devido quadro de icterícia que\nnotou há 2 dias. Vinha investigando há 2\nsemanas quadro de dor abdominal em hipocôndrio direito\nque irradiava para o dorso. Relata muita sonolência. Nega uso de qualquer tipo de medicação ou\nfitoterápico. Tem USG de abdome recente sem alterações. Ao exame físico Glasgow 15, nota-se\nicterícia 4+/4, abdome doloroso em hipocôndrio e epigástrio, Murphy e DB negativos. Flapping\nnegativo. Edema 2+/4 em MMII. Exames da admissão: Sorologias: HBsAg: não reagente; Anti-HBs:\nreagente; Anti-HBc total: reagente; Anti-HCV: não reagente; Anti-HAV IgM: não reagente; anti-HAV\nIgG: reagente. A melhor conduta para essa paciente seria:","options":{"A":"Fazer novo exame de imagem, pois icterícia tem padrão obstrutivo.","B":"Iniciar tratamento com tenofovir para hepatite B aguda grave.","C":"Prescrever sintomáticos, paciente encontra-se em curso de hepatite A.","D":"Investigar sangramentos espontâneos e solicitar FAN, anti-KLM1 e AML."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":["question_bank/media/medcurso/medcurso-hepato-hep-2/352577.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369435","number":"369435","sourceNumber":"369435","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, ribeirinho, 43 anos, etilista, em consulta ambulatorial com queixa\nde dor abdominal em hipocôndrio direito, com\nirradiação para ombro ipsilateral, há 7 dias,\nacompanhada de náuseas, ortopneia e edema de membros inferiores. Refere que procurou\natendimento médico há alguns dias, e que recebera o diagnóstico de \"doença do fígado\". Nega\nfebre ou outros sintomas sistêmicos. Sobre este caso, e a propedêutica das doenças hepáticas, é\ncorreto afirmar que:","options":{"A":"a impressão diagnóstica provavelmente está equivocada, caso o paciente apresente refluxo\nhepatojugular no exame físico. Um diagnóstico provável é insuficiência cardíaca.","B":"a impressão diagnóstica provavelmente está equivocada, caso consistência do fígado seja firme\nou duro à palpação, e desta forma um diagnóstico improvável é cirrose hepática.","C":"a impressão diagnóstica provavelmente está correta, e deve se tratar de coledocolitíase, caso o\npaciente não apresente icterícia, já que o paciente é etilista.","D":"a impressão diagnóstica provavelmente está incorreta, e deve se tratar de doença de Chagas,\numa vez que à palpação o fígado esteja com\ntamanho diminuído.","E":"a impressão diagnóstica provavelmente está correta, caso o paciente sinta dor à palpação\nhepática, o que não acontece em quadros de\nhepatite viral e de insuficiência cardíaca congestiva."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-369365","number":"369365","sourceNumber":"369365","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale a alternativa que contém a correspondência correta entre o sinal e a patologia.","options":{"A":"Sinal de Chandelier - apendicite.","B":"Sinal de Courvoisier - colecistite.","C":"Sinal de Danforth - doença inflamatória pélvica.","D":"Sinal de Aaron - hemoperitônio.","E":"Sinal de Cruveilhier - hipertensão portal."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-343681","number":"343681","sourceNumber":"343681","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 53 anos é internado com quadro de ascite com evolução de 3 meses.\nNo exame físico: aumento do volume abdominal,\nmacicez móvel e leve desconforto à palpação\nsuperficial do abdome, sendo realizada paracentese diagnostica. A análise do líquido ascítico\nmostra, proteína total= 3.5g/dl e albumina 2.2g/dl. A dosagem de albumina sérica é de 3.6g/dl.\n\nEsses achados são compatíveis com os seguintes diagnósticos, EXCETO:","options":{"A":"Síndrome de Buddi-Chiari.","B":"Síndrome de Meigs.","C":"Cirrose.","D":"Metástases Hepáticas.","E":"Síndrome Nefrótica."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-343691","number":"343691","sourceNumber":"343691","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Leia o texto abaixo para responder a questão 37. ?Há doenças piores que as doenças,\nHá dores que não doem, nem na alma Mas que\nsão dolorosas mais que as outras. Há angústias\nsonhadas mais reais Que as que a vida nos traz, há sensações Sentidas só com imaginá-las Que\nsão mais nossas do que a própria vida.? Trecho de ?H doenças piores que as doenças? Fernando\nPessoa (Cancioneiro); O poema acima, cujo autor foi vítima de cirrose hepática doença ainda muito\nestigmatizada, requer avaliação do grau de acometimento secundário da encefalopatia. Neste\nsentido, o estágio da encefalopatia hepática é melhor graduado através da/do:","options":{"A":"escala de coma de Glasgow.","B":"escala de Ramsay.","C":"classificação de West-Haven.","D":"modelo para Doença Hepática Terminal (do inglês, Model for End-Stage Liver Disease - MELD).","E":"classificação de Child-Pugh."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-302536","number":"302536","sourceNumber":"302536","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 50 anos vem à consulta médica devido a aumento de volume abdominal\nprogressivo nos últimos 6 meses. Nega\nfebre, tosse ou alteração do hábito intestinal. Ao exame,\napresenta-se emagrecido, com telangiectasias no tórax e eritema palmar, além do abdome ascítico.\nA albumina sérica do paciente foi de 2g/dl, enquanto a paracentese diagnóstica realizada no\nserviço de pronto atendimento mostrou albumina de 0,5 g/dl. Como etiologia para a ascite, os\ndados indicam","options":{"A":"tuberculose.","B":"câncer de cólon.","C":"câncer de próstata.","D":"câncer de testículo.","E":"cirrose hepática."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-302541","number":"302541","sourceNumber":"302541","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a doença hepática gordurosa não alcoólica, é correto afirmar:","options":{"A":"Atualmente é a causa mais frequente de doença hepática crônica, em que 50% dos casos de\nesteatose evoluem para cirrose hepática, sendo mais comum entre os hispânicos e população de\norigem ocidental.","B":"Dentro da fisiopatogenia da doença, refere-se ao estresse oxidativo, em que o metabolismo da\nperoxidação lipídica, do mecanismo indutor do FAS e do FAS-ligante e a indução de grupos de\ncitocinas inflamatórias e fibrogênicas são aspectos de interesse.","C":"Um número expressivo de pacientes possui uma doença sintomática com quadro de desconforto\nem hipocôndrio direito, fadiga, hepatomegalia e\nsinais indicativos de doença hepática crônica\ncirrogênica.","D":"A presença de achados histopatológicos hepáticos de balonização e corpúsculos de Mallory são\ncaracterísticos somente da doença hepática gordurosa não alcoólica, considerada padrão ouro\npara o diagnóstico da doença.","E":"Dentro dos aspectos terapêuticos, as mudanças do estilo de vida não possuem tanta eficácia,\nsendo necessário o uso de medicações que diminuam a balonização e o estresse tecidual\noxidativo."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-2-302542","number":"302542","sourceNumber":"302542","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"São característicos de peritonite bacteriana espontânea em pacientes portadores de\ncirrose hepática:","options":{"A":"GASA < 1,1; aumento do DHL e de mononucleares acima de 250 células/mm3 no líquido\nascítico; cultura monobacteriana com rendimento acima de 50%.","B":"GASA < 1,1; glicose baixa, celularidade acima de 250 células/mm3 de segmentados no líquido\nascítico, pH baixo.","C":"GASA > 1,1; pH baixo, glicose normal, polimorfonucleares acima de 250 células/mm3 no líquido\nascítico; cultura frequentemente negativa.","D":"GASA > 1,1; glicose normal, DHL baixo, mononucleares acima de 250 células/mm3 no líquido\nascítico; cultura positiva.","E":"GASA < 1.1; pH normal, DHL elevado, presença de celularidade elevada, às custas de\nmononuclear."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-311410","number":"311410","sourceNumber":"311410","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente, masculino, 48 anos, pessoa em situação de rua, é trazido para atendimento\npelo SAMU após ser encontrado desacordado por\npopulares próximo ao Bar do Parque.\n\nImediatamente após a entrada na unidade de graves, o paciente vomita restos alimentares\nmisturados com laivos de sangue. Ao exame\nfísico: paciente emagrecido, desidratado, ictérico,\nacianótico, mucosas hipocoradas. Consciente e desorientado em tempo e espaço, Glasgow = 13.\nAusculta respiratória: murmúrios vesiculares presentes, bilateralmente, com estertor crepitante em\nbase direita. Ausculta cardíaca: bulhas normofonéticas, ritmo regular. Abdome: semigloboso,\nflácido, indolor à palpação, piparote positivo. Extremidades: sem edema. Sinais vitais: PAS 97\nmmHg, PAD 55 mmHg, PAM 69, FC 101 bpm, FR 20 irpm, Glicemia Capilar 74 mg/dL, Sat. O? 94%\nem ar ambiente, temperatura axilar 37,3ºC. Considerando-se o quadro acima e a melhor\nabordagem inicial do paciente no departamento de emergência, é correto afirmar que:","options":{"A":"deve ser prescrita furosemida 20 mg endovenosa após a expansão volêmica em paciente\nascítico com choque séptico.","B":"o paciente está em choque hipovolêmico, e deve receber noradrenalina endovenosa antes da\nressuscitação volêmica com coloide.","C":"história de doença hepática ou cardíaca indicam a realização de endoscopia digestiva alta,\npreferencialmente nas primeiras 12h.","D":"a presença de ascite contraindica a ressuscitação hemodinâmica com a infusão de cristaloide.","E":"a hipoglicemia indica intoxicação por metanol, devendo-se prescrever o uso de carvão ativado\nou lavagem gástrica."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-320199","number":"320199","sourceNumber":"320199","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 53 anos, masculino, viúvo, motorista, é levado pela filha para a Emergência\ncom história de melena, seguido de hematêmese\nvolumosa, há cerca de 24 horas. Refere vômito\nborráceo, com odor de ferro, sem presença de restos alimentares ou outros elementos. A melena\nfoi caracterizada pelo paciente como pastosa, escura, parecida com borra de café e odor\nconsideravelmente fétido. Nega outros sintomas. Diz ter diagnóstico há 2 anos de doença\nparenquimatosa crônica do fígado, sendo atualmente acompanhado no ambulatório de centro de\nreferência de seu município. Ademais, conta seguir as orientações médicas, não apresentando,\ndesde o início do diagnóstico, outros problemas advindos dessa doença. Nega uso de medicações,\ncirurgias e outras patologias. Acusa etilismo há 15 anos aos finais de semanas. Exame físico de\nadmissão com sinais vitais: Pressão Arterial 120 × 70 mmHg, FC 90 bpm, FR 18 irpm, Temperatura\naxilar: 37,4°C, SpO2: 97%. Dados antropométricos: 68 kg; 1,70 m; IMC 23,52 kg/m². Exame físico\ngeral: paciente em regular estado geral, lúcido e orientado no tempo e espaço, mucosas\nanictéricas, hidratadas e hipocoradas (+/++++), fácies atípica. Exame de pele, aparelho\ncardiovascular e aparelho respiratório sem anormalidades. Exame do abdome: semigloboso,\nflácido, cicatriz umbilical de conformação normal, sem cicatrizes cirúrgicas, sem ondas\nperistálticas\nvisíveis e com discreta circulação colateral periumbilical do tipo caput medusae. Ruídos hidroaéreos\nnormofonéticos e bem distribuídos nos quatro quadrantes abdominais. À hepatimetria, notou-se\nfígado diminuto. À palpação, borda normal e textura rígida. Traube livre. Baço não palpável à\nmanobra de Schuster. Ausência de dor na compressão de ponto cístico à inspiração. Exames\nlaboratoriais relevantes: TGO 54 (ref: 0?45), TGP 61 (ref: 0?50) TP 15s (ref: 10?14s) RNI 1,5 (ref:\n1?1,4). O diagnóstico mais provável e a melhor conduta a ser tomada, neste caso, são:","options":{"A":"Úlcera Duodenal: Omeprazol 20 mg em jejum, Dieta, Endoscopia Digestiva Alta.","B":"Varizes Esofágicas: Hidratação, Antibiótico, Vasopressor, Endoscopia Digestiva Alta.","C":"Úlcera Gástrica: Omeprazol 20 mg 12/12 horas, Endoscopia Digestiva Alta.","D":"Síndrome de Mallory-Weiss: Hidratação, Antibiótico, Endoscopia Digestiva Alta.","E":"Tumor de Estômago: Hidratação, Endoscopia Digestiva Alta."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-311425","number":"311425","sourceNumber":"311425","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na avaliação de um paciente obeso com esteatose hepática grau III associada a um\naumento de transaminases, o médico assistente aventou a possibilidade de se tratar da\n\nesteato-hepatite Metabólica (EHM ou \"MASH\", em inglês). Sobre este caso, assinale a alternativa\nCORRETA.","options":{"A":"Exames de imagem, como ultrassom e ressonância magnética abdominais são capazes de\navaliar a extensão (grau) da infiltração gordurosa hepática e distinguir esteatose de\n\nesteato-hepatite.","B":"Biópsia hepática é uma exame mandatório para confirmar diagnóstico em todos os casos e para\no screening de carcinoma hepatocelular,\ncomplicação mais precoce desta condição clínica.","C":"A metformina é recomendada como tratamento específico padrão-ouro para MASH, pois\ndiversos estudos têm demonstrado sua eficácia na melhora histológica do grau de fibrose.","D":"No manejo deste paciente, é prudente investigar também outras condições clínicas, como\nhepatites virais e doença hepática alcoólica, bem como marcadores e critérios da síndrome\nmetabólica.","E":"Trata-se de uma condição clínica muito prevalente, mas não se tem observado sua associação\ncom cirrose hepática. Componentes antioxidantes,\ncomo a silimarina, são o tratamento de escolha."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-277730","number":"277730","sourceNumber":"277730","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 38 anos foi internado para a investigação de ascite. O paciente relata que\nvem ocorrendo aumento progressivo do volume\nabdominal há 3 meses, acompanhado de perda de\npeso (habitual: 70 kg; atual: 60 kg) e episódios febris há 2 meses, geralmente no final da tarde,\ncom\ntemperatura entre 37,8° C e 38,5° C. Os exames iniciais demonstram anemia ferropriva, albumina\nsérica de 4 g/dL (referência 3,5 a 4,7g/dL), albumina no líquido ascítico de 3,4g/dL. A hipótese\ndiagnóstica a ser considerada é","options":{"A":"hepatopatia crônica.","B":"insuficiência cardíaca congestiva.","C":"tumor de Wilms.","D":"insuficiência renal crônica.","E":"tuberculose."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-276692","number":"276692","sourceNumber":"276692","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Cirrose hepática pode ser uma evolução clínica de pacientes com doença hepática\navançada, inúmeras sequelas podem ser\nmanisfestadas, entre elas a Hipertensão Portal (HP). Com\nrelação a HP é correto afirmar que:","options":{"A":"a hipertensão portal resulta, mas comumente, da diminuição da resistência do fluxo sanguíneo\nporta.","B":"a pressão normal da veia porta é baixa (10 a 15 cm de solução salina) porque a resistência\nvascular nos sinusóides hepáticos é mínima.","C":"a HP também pode decorrer de um aumento do fluxo da porta, mas a alta resistência ao fluxo de\nsaída do fígado normal faz com que este seja um problema clínico comum.","D":"a oclusão da veia porta pode resultar em hematêmese maciça decorrente de varizes gástricas.","E":"a presença de válvulas no sistema venoso porta facilita o fluxo sanguíneo retrógrado\n(hepatofugal) do sistema venoso porta de alta\npressão para a circulação venosa sistêmica de baixa\npressão."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-269777","number":"269777","sourceNumber":"269777","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A esteatose hepática e a esteato-hepatite não alcoólica (NASH) fazem parte do quadro\nchamado doença gordurosa não alcoólica, com a\nsigla em inglês NAFLD. Essa situação é\naltamente prevalente na sociedade atual. A respeito de tal doença, identifique as afirmativas a\nseguir como verdadeiras (V) ou falsas (F): ( ) Como a prevalência de sobrepeso/obesidade cresce\nem todos os países, é possível que NASH se torne uma das maiores causas de doença hepática\nterminal e de hepatocarcinoma no mundo. ( ) Cirrose hepática devido a NASH pode ocorrer na\npopulação obesa com maior frequência do que na população não- obesa. ( ) A esteatose\nmacrogoticular encontrada na NAFLD também é vista em outras doenças, como por exemplo na\ndoença hepática alcóolica. ( ) NAFLD é a manifestação hepática da síndrome metabólica. A\nalternativa que apresenta a sequência correta de cima para baixo, é:","options":{"A":"V, V, V, V","B":"F, V, F, F","C":"F, V, F, V","D":"V, F, V, F","E":"F, F, F, F"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-227628","number":"227628","sourceNumber":"227628","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A cirrose hepática é o estágio final da fibrose hepática progressiva, caracterizada pela\ndistorção da arquitetura do parênquima e formação de nódulos de regeneração, sendo estas lesões\nconsideradas irreversíveis em estágios avançados. Pacientes cirróticos possuem expectativa de\nvida reduzida, e estão sujeitos a diversas complicações, como síndrome hepatorrenal, carcinoma\nhepatocelular e Peritonite Bacteriana Espontânea (PBE); quanto a esta última, é CORRETO afirmar\nque:","options":{"A":"Entre as manifestações clínicas estão febre, dor abdominal, rash cutâneo e alteração do estado\nmental.","B":"Alguns fatores de risco estão associados a uma maior incidência da complicação, como\nbilirrubina total maior que 2,5 mg/dl, Child acima de 9 e excesso de proteínas na dieta.","C":"Como medidas de profilaxia estão indicadas uso de diuréticos, identificar e tratar infecções\nlocalizadas, restringir o uso de inibidores de\nbomba de prótons e manter uso de betabloqueadores.","D":"Terapia antimicrobiana empírica deve ser iniciada em pacientes que não tenham diagnóstico\nconfirmado, mas que apresentem dor abdominal, modificações do estado mental, contagem de\npolimorfonucleares acima de 250/mm³ e temperaturas acima de 37,8ºC.","E":"A dor abdominal relacionada à PBE costuma ser de forte intensidade, localizada em hipocôndrio\ndireito e irradiada para o mesogástrio."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-240476","number":"240476","sourceNumber":"240476","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 72 anos, gênero masculino, internado há 2 semanas por hemorragia\ndigestiva varicosa, complicação de cirrose\nhepática pelo vírus da hepatite C. Encontrava-se estável\napós o tratamento instituído, em que pese a ascite moderada, porém começou a ter rebaixamento\ndo nível de consciência, presença de flapping e elevação das escórias nitrogenadas no sangue. A\nconduta CORRETA a ser instituída a seguir é:","options":{"A":"Realizar a paracentese diagnóstica para investigar a presença da peritonite bacteriana\nespontânea.","B":"Iniciar o uso da terlipressina e albumina, pois trata-se de um caso de síndrome hepatorrenal.","C":"Administrar a lactulose e o metronidazol e aguardar 5 dias se haverá resposta ou não, para só\nentão seguir com as demais investigações.","D":"Realizar a paracentese de alívio e iniciar o uso da noradrenalina e albumina, evitando a piora da\ndisfunção renal.","E":"Introduzir antibioticoterapia empírica, pois deve estar com uma infecção que precipitou a\nencefalopatia hepática."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-203716","number":"203716","sourceNumber":"203716","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação à hepatopatia crônica, analise as assertivas abaixo. I. Na colangite biliar\nprimária, os anticorpos antimitocôndria estão\npresentes em 90% dos casos; II. A hepatite autoimune\ntipo 2 tem o anti-LKM-1 positivo; III. A colangite esclerosante primária apresenta associação com\nantígenos HLA-DR3 e DR13; IV. Varizes de esôfago de pequeno calibre com marcas vermelhas\nnecessitam de profilaxia com propranolol. Estão CORRETAS:","options":{"A":"I e II, apenas.","B":"IV, apenas.","C":"I, II e IV, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181866","number":"181866","sourceNumber":"181866","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ascite é a presença de líquido livre na cavidade abdominal. Vários fatores devem ser\nconsiderados no mecanismo fisiopatológico com importância variada de acordo com a causa da\nascite. Como causa(s) de ascite relacionada(s) com a hipertensão portal (gradiente de albumina\nsoro-ascite > 1,1g/dL) a alternativa correta é:","options":{"A":"metástase hepática, Síndrome de Budd-Chiari","B":"pancreatite, ascite biliar","C":"síndrome nefrótica, peritonite","D":"síndrome de Meigs","E":"serosite por doença do tecido conjuntivo"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-175220","number":"175220","sourceNumber":"175220","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, 52 anos, chega à emergência com história de hematêmese\ne melena há 1 dia, sem outros quadros\nsemelhantes anteriores. O exame físico revela icterícia\n\n++/4+, mucosas hipocoradas +++/4+, presença de telangiectasias, eritema palmar, pulsos céleres,\nFC = 100 bpm e PA = 100 x 60 mmHg.\nAssinale a alternativa CORRETA quanto à abordagem\nterapêutica desta paciente.","options":{"A":"Ressuscitação volêmica vigorosa, mantendo níveis pressóricos acima de 120 mmHg de sistólica.","B":"Início precoce de terlipressina e realização de endoscopia digestiva dentro das primeiras 12\nhoras.","C":"Pelo fato de a principal suspeita ser hemorragia digestiva varicosa, deve-se iniciar propranolol\ne\nrealizar endoscopia digestiva.","D":"Deve-se realizar profilaxia para síndrome hepatorrenal com uso de cristaloides e albumina\nhumana.","E":"Transfusão de concentrado de hemácias, com alvo de hemoglobina em torno de 13 g/dl e\nhematócrito entre 35 e 40%."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-181792","number":"181792","sourceNumber":"181792","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na avaliação funcional de cirróticos para determinar a gravidade, é utilizada a\nclassificação de Child-Pugh que inclui cinco variáveis. Outro escore funcional adotado para a\ndoença hepática é o MELD (Modal for End-Stage Liver Disease), mais simples e com melhor\ncapacidade de prever a sobrevida em hepatopatas, quando comparado à classificação de\n\nChild-Pugh. O escore de MELD é calculado por uma equação logarítmica neperiana que utiliza as\nseguintes variáveis:","options":{"A":"Bilirrubinas ? INR - Creatinina","B":"Albumina ? Glicose ? Tempo de protrombina","C":"Ureia ? Sódio - Albumina","D":"Sódio ? INR ? Glicose","E":"Bilirrubina indireta ? Albumina - Creatinina"},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-159961","number":"159961","sourceNumber":"159961","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um paciente de 17 anos queixa-se de \"olhos amarelados\" e \"urina escura\" há uma\nsemana. Seus pais, que são primos, referem\nque o jovem apresenta também piora do\naproveitamento escolar e dificuldades para escrever nos últimos meses. Exames complementares\nmostraram os seguintes resultados: hemoglobina sérica = 9,5 g/dl; VCM e HCM normais; AST =\n970 U/L (normal até 38 U/L); ALT = 780 U/L (normal até 41 U/L); fosfatase alcalina = 90 U/L (normal\naté 130 U/L); bilirrubina total = 7,8 mg/dl (normal até 1,2 mg/dl); bilirrubina conjugada = 1,2\nmg/dl\n(normal até 0,4 mg/dl); anti-HCV negativo, HBsAg negativo; anti-HBc total negativo e anti-HAV total\npositivo; anti-HAV IgM negativo. Assinale a alternativa que contém o diagnóstico mais provável:","options":{"A":"Hepatite A.","B":"Doença de Wilson.","C":"Hepatite alcoólica.","D":"Intoxicação por paracetamol.","E":"Cirrose biliar primária."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-156683","number":"156683","sourceNumber":"156683","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 62 anos, masculino, internado com história de há 7 dias, após um esforço\nfísico, ter apresentado três episódios de\nvômitos sanguinolentos e fezes enegrecidas de odor fétido\nque perduraram por três dias. Encontra-se em acompanhamento ambulatorial para cirrose hepática\nalcoólica e refere episódios prévios de hemorragia digestiva. Ao exame físico: mucosas\nhipocoradas ++/4+; presença de telangiectasias e eritema palmar; hemodinamicamente estável;\nFC: 72 bpm; PA: 120 x 70 mmHg. A melhor conduta para o quadro é:","options":{"A":"Profilaxia primária com terlipressina associada ou não com ligadura elástica de varizes\nesofagianas.","B":"Profilaxia secundária com propranolol e ligadura elástica de varizes de esôfago.","C":"Profilaxia secundária com propranolol com ou sem mononitrato de isossorbida associada à\nescleroterapia de varizes esofagianas.","D":"Profilaxia primária com ligadura elástica, se houver contraindicação ou não resposta ao\npropranolol.","E":"Profilaxia secundária com terlipressina associada à escleroterapia de varizes esofagianas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-159920","number":"159920","sourceNumber":"159920","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente alcoólatra encaminhado para ambulatório de hepatologia apresentando sinais\nclínicos, exame físico e propedêutica laboratorial e de imagem compatível com hepatopatia crônica.\nFrente a gravidade do quadro clínico, faz-se necessária a classificação funcional. Para este caso\nclínico, a alternativa que expressa as classificações mais utilizadas é:","options":{"A":"Classificação MDRD e Gault.","B":"Classificação MDRD e MELD.","C":"Classificação de Gault e Child-Pugh.","D":"Classificação MELD e Child-Pugh.","E":"Classificação de Child-Pugh e Gault."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-134588","number":"134588","sourceNumber":"134588","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Ascite é a presença de líquido livre na cavidade abdominal. Relativo a esse conceito\na alternativa que explica um dos fatores que\ndevem ser avaliados no seu mecanismo\nfisiopatológico e:","options":{"A":"qualquer doença crônica que provoque anorexia, febre e perda de peso pode desenvolver\nascite.","B":"é causada pela diminuição da pressão coloidosmótica devido a hipoalbuminemia.","C":"a ascite se deve a diminuição da pressão hidrostática portal devido a baixa pressão no\nsistema porta.","D":"o aumento da drenagem linfática pelo sistema porta leva ao desenvolvimento de ascite.","E":"produção excessiva de Liquido peritoneal por transporte ativo."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-135469","number":"135469","sourceNumber":"135469","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação a evolução da doença hepática crônica é correto afirmar que:","options":{"A":"Na hipertensão portal, o gradiente de pressão portal está relacionado com o fluxo sanguíneo e a\nresistência oposta a este fluxo, sendo que o aumento do fluxo sanguíneo portal é consequência da\nvasoconstrição esplâncnica.","B":"O glucagon, produzido pelas células oxínticas do estômago e pelas células beta do pâncreas,\nestão\n\naumentadas no paciente cirrótico e são considerados potentes vasoconstritores.","C":"As células estrelares no fígado estão envolvidas no processo de fibrogênese hepática e fator de\nnecrose tumoral, TGF alfa, TGF beta podem estimular estas células a sintetizar colágeno.","D":"O desenvolvimento de peritonite espontânea bacteriana no cirrótico é usado como um critério de\npontuação na classificação de Child.","E":"A carga viral do vírus da hepatite B (HVB) não está implicada na evolução das formas crônicas\nda hepatite B."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-68449","number":"68449","sourceNumber":"68449","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Durante a colecistectomia videolaparoscópica para tratamento da colelitíase, a\ncolangiografia intraoperatória é dispensável principalmente em casos de:","options":{"A":"paciente com história de icterícia e colúria no pré-operatório.","B":"paciente portador de múltiplos microcálculos em vesícula.","C":"paciente com cálculo único de 2 cm e ducto cístico fino.","D":"cirurgia tecnicamente difícil, com intenso processo inflamatório da vesícula à árvore biliar\nextra-hepática.","E":"paciente que já havia sido internado previamente por pancreatite aguda biliar."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-371058","number":"371058","sourceNumber":"371058","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Doença Hepática Gordurosa associada a Disfunção Metabólica é considerada uma das\ndoenças hepáticas mais comuns no mundo, com uma\nprevalência relatada de 6 a 35 por cento.\n\nRecentemente, houve uma mudança na nomenclatura e definição, estabelecendo melhores seus\ncritérios e evitando a estigmatização associada à terminologia \"não alcoólica\". Desta forma,\nassinale a alternativa incorreta conforme esta nova atualização.","options":{"A":"Define-se pela evidência de acúmulo de gordura no fígado (esteatose hepática) através da\nanálise histológica (biópsia), imagem ou biomarcadores sanguíneos, associado a um dos três\ncritérios: Sobrepeso ou obesidade, peso normal ou baixo com evidência de desregulação\nmetabólica) e presença de diabetes tipo 2.","B":"A história de etilismo ou outras doenças hepáticas (hepatite viral, hepatite autoimune não exclui\no diagnóstico concomitante de doença hepática\ngordurosa associada a disfunção metabólica,\nsendo que nesse caso deve ser considerada a presença de ambos os fatores causais.","C":"Em pessoas com Diabetes e ultrassonografia abdominal sugestiva de DHGM, e/ou aumento de\naminotransferases, a utilização de escores clínico-laboratoriais (APRI, NAFLD fibrosis score ou\nFibrosis-4 index) de risco de fibrose avançada e/ou elastografia e/ou biópsia hepática é\nrecomendada para avaliação da presença de fibrose hepática.","D":"Recomenda-se a perda de peso com dieta e exercícios e terapia medicamentosa para todos\npacientes com Doença Hepática Gordurosa associada a Disfunção Metabólica, independente da\navaliação do grau de fibrose.","E":"Nenhuma das alternativas."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-371070","number":"371070","sourceNumber":"371070","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Na avaliação pré-operatória de candidatos a transplante de fígado pediátrico por atresia\nbiliar, qual das seguintes afirmativas é\nverdadeira em relação às contraindicações para o\nprocedimento?","options":{"A":"A presença de infecção por HIV é uma contraindicação absoluta ao transplante de fígado\npediátrico em todos os centros transplantadores.","B":"A síndrome hepatopulmonar é uma contraindicação ao transplante de fígado pediátrico quando o\nPaO2 melhora significativamente com a administração de 100% de oxigênio.","C":"A presença de hipertensão portopulmonar com pressões da artéria pulmonar abaixo de 50 mm\nHg é uma contraindicação absoluta ao\ntransplante.","D":"Trombose venosa portal é uma contraindicação relativa ao transplante de fígado pediátrico,\npodendo ser superada por meio de enxerto de ponte para a veia mesentérica superior.","E":"O compromisso contínuo com a imunossupressão pós-transplante é uma condição crítica e a\nincapacidade de aderir ao regime de imunossupressores é uma contraindicação ao transplante."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-371922","number":"371922","sourceNumber":"371922","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente com diagnóstico de Cirrose de etiologia hepática, dá entrada no Hospital\nRegional de Patos com ascite pequena,\nencefalopatia grau II, albumina sérica de 2,8g/dL, INR de\n1,9 e Bilirrubina total de 1,9. Com base nesses dados, qual score de Child-Pugh do paciente em\nquestão, a pontuação total estabelecida para a devida classificação","options":{"A":"Child - Pugh B, 11 pontos","B":"Child - Pugh A, 5 pontos","C":"Child - Pugh B, 9 pontos","D":"Child - Pugh B, 10 pontos","E":"Child - Pugh C, 11 pontos"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-345539","number":"345539","sourceNumber":"345539","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 48 anos de idade está internado por cirrose de etiologia alcoólica e\nhemorragia digestiva alta. Por conta do edema,\nestá em uso de furosemida 80 mg endovenosa por\ndia. Há dois dias passou a ter queda do volume urinário e piora da função renal. Ao exame: estado\ngeral regular, ictérico 2+/4, edemaciado, sonolento, com flapping presente. Sinais vitais: pressão\narterial de 90 x 60 mmHg, FC 96 de bpm e FR de 19 irpm. Ausculta pulmonar e cardíaca sem\nalteração. Abdome com ascite volumosa. Edema de membros inferiores de 2+/4+. Sobre a causa\nde injúria renal aguda (IRA) apresentada, é correto afirmar que:","options":{"A":"Esta paciente apresenta síndrome hepatorrenal.","B":"Para diferenciar causa pré-renal de hepatorrenal, deve-se dosar a fração de excreção de ureia.","C":"Nesta paciente, a IRA é causada por uma síndrome compartimental abdominal.","D":"Esta paciente não apresenta IRA pré-renal, pois encontra-se em anasarca.","E":"Para afastar causa pré-renal, deve-se suspender o diurético e iniciar expansão com albumina."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-344831","number":"344831","sourceNumber":"344831","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A origem de muitos sangramentos gastrointestinais pode ser suspeitada pela história\nclínica e pelo exame físico e ser confirmada\npela endoscopia superior ou inferior. O tratamento\ninicial da HDA é focado na reanimação clínica, seguida pelo diagnóstico etiológico (geralmente\nendoscópico) e por intervenções que visem cessar o sangramento agudo e evitar um sangramento\nrecorrente. A terapia farmacológica está desempenhando um papel de importância crescente no\ntratamento de sangramentos por úlceras pépticas e varizes. Analise as afirmativas a seguir sobre a\nHDAV (Hemorragia Digestiva Alta Varicosa): I. O tratamento farmacológico da HDAV com\nmedicamentos vasoconstritores é eficaz na contenção do sangramento agudo. II. A erradicação\ncompleta das varizes é necessária para evitar recidiva da hemorragia no paciente que já\napresentou, pelo menos, um episódio de sangramento varicoso prévio. III. O balão de\n\nSengstaken-Blakemore pode permanecer insuflado por até 24 horas, como ponte para um\ntratamento definitivo. IV. O propranolol deve ser\niniciado dentro das primeiras 12 horas para reduzir\no risco de ressangramento. Qual(is) está(ão) correta(s)?","options":{"A":"Apenas a II.","B":"Apenas a III.","C":"Apenas a II e a III.","D":"Apenas a I, a II e a III.","E":"Apenas a I, a II e a IV."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-344833","number":"344833","sourceNumber":"344833","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 51 anos, cor branca, proveniente do domicílio, com\ndiagnóstico já estabelecido de cirrose\nhepática por álcool, abstinente há um ano e meio. O paciente\nfoi levado ao pronto atendimento (PA) médico por apresentar quadro de febre, queda do estado\ngeral, dor abdominal e constipação há três dias, sendo que evoluiu com sonolência e desorientação\nno tempo e no espaço nas últimas 24 horas. Segundo a esposa, o paciente estava em uso de\ndiuréticos há 15 dias, iniciado após consulta com hepatologista por ascite e edema em membros\ninferiores. Além dos diuréticos, fazia uso de anti-hipertensivo da classe dos inibidores da enzima\nconversora da angiotensina (IECAs) por hipertensão arterial (HA) de longa data. O paciente foi\nrecebido em uma cadeira de rodas, em mau estado geral, desidratado, com mucosas hipocoradas\n\n+/4, ictérico +/4 e acianótico. Observe as afirmativas a seguir sobre o caso acima: I - O quadro\nneurológico inicial do paciente é\ncaracterístico de Encefalopatia Hepática. II - Os fatores\nprecipitantes deste quadro de cirrose descompensada com sinais de infecção devem ser\ninvestigados, devido ao risco de agravamento e de irreversibilidade do quadro. III - Um diagnóstico\na ser considerado neste caso é a possibilidade de PBE. A PBE é sintomática na grande parte dos\npacientes, apenas 5% deles são totalmente assintomáticos. IV- O diagnóstico de Necrose Tubular\nAguda pode ser sugerido pelos indícios de hipovolemia, principalmente, pelo resgate dos seguintes\nexames: sódio urinário acima de 40 mEq/L e osmolalidade urinária superior a 350mOsm/kg,\nembora não sejam achados totalmente específicos. Quais estão corretas?","options":{"A":"Apenas a I, a II e IV.","B":"Apenas a I, e a III e IV","C":"Apenas a II e a III.","D":"Apenas I, a II e a III.","E":"Nenhuma das alternativas."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-315952","number":"315952","sourceNumber":"315952","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem cirrótico de 55 anos está internado na enfermaria de um hospital secundário,\nonde está sendo investigado e tratado para\nquadro de encefalopatia hepática, quando percebe-se\ngrande quantidade de sangue enegrecido, parcialmente digerido, pegajoso e de odor fétido. Em\nrelação ao este caso, responda a alternativa correta:","options":{"A":"Hematêmese (vômitos com sangue), melena (sangue digerido) e hematoquezia são formas de\napresentação de hemorragia digestiva, sendo esta última exclusiva de quadros baixos, originados\ndistalmente à papila duodenal","B":"Uso de vitamina K, ácido tranexâmico e lavagem gástrica são recomendadas na abordagem\ninicial das HDAs","C":"Em casos de sangramento profuso, com instabilidade hemodinâmica, o balão de\n\nSengstaken-Blakemore é uma ferramenta que pode ser utilizada, independentemente da etiologia","D":"Na hemorragia varicosa, é necessário administração de antibiótico profilaxia para PBE mesmo\nem pacientes sem ascite"},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-315965","number":"315965","sourceNumber":"315965","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Um homem de 46 anos de idade com cirrose de etiologia alcoólica teve um aumento da\ndistensão abdominal no último mês. Seus sinais vitais estão estáveis e ele se encontra afebril. O\nexame físico revela um abdome distendido com Sinal do Piparote positivo. Qual dentre as\nalternativas abaixo é a errada no manejo terapêutico inicial da ascite deste paciente?","options":{"A":"Restrição de sódio","B":"Shunt portocaval Intra-hepático transjugular (TIPS)","C":"Paracentese diagnóstica","D":"Administração de diuréticos"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-266325","number":"266325","sourceNumber":"266325","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 55 anos, etilista crônico, é trazido pelo SAMU com quadro de rebaixamento\nde nível de consciência, icterícia, ascite e\nedema de MMII. É morador de rua, sem acompanhantes\ne a anamnese é prejudicada pela falta de informações adequadas. Sobre este caso, é correto:","options":{"A":"A cirrose hepática é responsável pela maior parte das ascites, que implica em bom prognóstico\npara o doente.","B":"A tuberculose também é causa comum de ascite e está relacionada a gradiente soro-ascite de\nalbumina maior que 1,1.","C":"Diuréticos de alça, tiazídicos e poupadores de potássio são os de primeira escolha no\ntratamento.","D":"A paracentese diagnóstica é mandatória em todos os casos de ascite que sejam admitidos no\nhospital."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-264529","number":"264529","sourceNumber":"264529","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Em relação ao manejo de pacientes cirróticos, assinale a alternativa CORRETA:","options":{"A":"A perda de peso diária segura em ascíticos sob diureticoterapia não depende da presença de\nedema periférico.","B":"Betabloqueadores são contraindicados na vigência de peritonite bacteriana espontânea.","C":"Escleroterapia é a modalidade endoscópica de escolha para profilaxia primária de sangramento\nvaricoso.","D":"O rastreio de hepatocarcinoma deverá ser realizado a cada dois anos.","E":"Propranolol, carvedilol e metoprolol são liberados para profilaxia primária e secundária de\nsangramento varicoso."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-264535","number":"264535","sourceNumber":"264535","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Qual das seguintes alterações clínico-laboratoriais é esperada em um paciente com\nSíndrome Hepatorrenal tipo I?","options":{"A":"Pressão arterial elevada.","B":"Fração excretória de sódio elevada.","C":"Cilindros leucocitários no sumário de urina.","D":"Hiperreninemia.","E":"Poliúria."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252168","number":"252168","sourceNumber":"252168","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Ascite, que corresponde ao acúmulo de líquido na cavidade peritoneal, é um sinal\nclínico relativamente frequente na prática clínica,\ne pode se desenvolver através de diferentes\nmecanismos fisiopatológicos. Na enfermaria de clínica médica de um hospital, durante a visita\nmédica, o Sr. Rubens, 67 anos, etilista de longa data, informou aumento do volume abdominal nas\núltimas semanas. Há dois dias, Rubens passou a apresentar dor abdominal, náuseas e episódios\nde desorientação temporal. Sobre o quadro acima, assinale a alternativa CORRETA:","options":{"A":"Uma vez confirmada a presença de ascite através de ultrassonografia ou outro método de\nimagem, torna-se desnecessária a determinação de sua etiologia por meio de paracentese.","B":"O Gradiente de Albumina Soro-Ascite (GASA) é útil para distinguir a ascite causada por\nhipertensão portal daquela sem hipertensão\nportal. O GASA ? 1,1g/dl indica que a ascite não está\nrelacionada com hipertensão portal, como ocorre na peritonite tuberculosa, carcinomatose\nperitoneal ou ascite pancreática.","C":"O tratamento inicial da ascite causada por cirrose é feito com restrição da ingestão de sódio\npara\n2 g/dia. Quando a restrição de sódio é\ninsuficiente para controlar a ascite, utilizam-se diuréticos por\nvia oral, normalmente a combinação de espironolactona e furosemida.","D":"Define-se que há Peritonite Bacteriana Espontânea (PBE) quando a contagem de linfócitos no\nlíquido ascítico é > 250/mm3."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-252184","number":"252184","sourceNumber":"252184","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente da entrada na unidade de terapia intensiva com quadro de choque\nhipovolêmico, devido a hemorragia digestiva\nalta, decorrente a sangramento de varizes\nesofagogástricas secundárias a hipertensão portal - cirrose hepática. Atualmente, ainda não existe\ntratamento eficaz para os cirróticos, como resultado, o tratamento tem sido focado no controle da\nhipertensão portal e suas complicações. Com relação a hipertensão portal e varizes\nesofagogástricas assinale a correta. I. A hipertensão portal é definida por uma pressão portal maior\ndo que 5 mmHG, entretanto, pressões mais elevadas são necessárias para estimular o\ndesenvolvimento da circulação colateral portossistêmica. II. A hipertensão portal geralmente ocorre\ndevido a maior resistência no afluxo venoso portal de localização pré-hepática, intra ou pós\nhepática. III. O sangramento das varizes esofagogástricas é a única complicação da hipertensão\nportal mais ameaçadora a vida, responsável por 1/3 dos óbitos em pacientes com cirrose. IV. Após\num sangramento de varizes esofagogástricas, a probabilidade de um episódio subsequente\nultrapassa os 70%, sendo que o desafio a longo prazo é a prevenção de hemorragia e manutenção\nde função hepática satisfatória.","options":{"A":"Todas estão corretas.","B":"Apenas I e II estão corretas.","C":"Apenas III e IV estão corretas.","D":"Apenas II e IV estão corretas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-225845","number":"225845","sourceNumber":"225845","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a ascite, é CORRETO afirmar:","options":{"A":"A terminologia barriga d'água é atribuída às consequências da doença hepática da\nesquistossomose, em que a maioria dos casos cursa com ascite.","B":"A descompensação da insuficiência cardíaca direita cursa com congestão pulmonar e ascite.","C":"A síndrome de Arnold-Chiari cursa com ascite, cujo gradiente de albumina (GASA) é maior que\n1,1.","D":"Um paciente com uma dosagem de albumina na ascite de 3,0 mg/dl e uma albumina sérica de\n3,9 mg/dl tem a possibilidade diagnóstica de uma tuberculose peritoneal.","E":"O surgimento da peritonite bacteriana espontânea não tem correlação com o sangramento de\nvarizes de esôfago."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-240942","number":"240942","sourceNumber":"240942","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, 48 anos, internado para investigação de ascite de\nsurgimento recente. É hipertenso, diabético e etilista de grande monta. Na admissão, realizado\nparacentese diagnóstica. A análise do líquido revelou: pH=8,0; Glicose=75 mg/dl; Proteínas\ntotais=3,2 g/dl e albumina=2,4 d/dl. A dosagem da albumina sérica é 3,7 d/dl. Qual o diagnóstico\nmais provável deste paciente?","options":{"A":"Cirrose hepática.","B":"Carcinomatose peritoneal.","C":"Tuberculose peritoneal.","D":"Pericardite constrictiva.","E":"Síndrome nefrótica."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-254124","number":"254124","sourceNumber":"254124","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 16 anos é trazido por familiares por quadro de tremores de extremidades,\nalteração da grafia, dificuldade em\ndeambular, com movimentos incoordenados e alterações\nemocionais, com irritabilidade de Agressividade, há aproximadamente 4 meses. Acompanhado há\num ano por alterações de sangue (possível anemia hemolítica) e provas de função hepáticas\nalteradas. Nega-se consumo de álcool ou drogas ilícitas. Histórico familiar positivo para Alzheimer.\nDiante desses dados, assinale a alternativa que apresenta o diagnóstico MAIS PROVÁVEL.","options":{"A":"Degeneração hepatolenticular.","B":"Doença de Alzheimer hereditária.","C":"Porfiria.","D":"Doença de Parkinson.","E":"Doença de Huntington."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-208031","number":"208031","sourceNumber":"208031","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a Síndrome Hepatorrenal (SHR), assinale a alternativa ERRADA:","options":{"A":"É diagnosticada por exclusão de outras causas de insuficiência renal.","B":"Embora de natureza funcional, a SHR está associada ao mau prognóstico, sendo o transplante\nhepático o único tratamento eficaz. O\nemprego de vasoconstritores, como terlipressina e\nnorepinefrina, tem mostrado melhora na função renal em aproximadamente 2/3 dos pacientes com\nSHR.","C":"Em fases mais avançadas da doença, os pacientes ficam incapazes de excretar água livre,\ndesenvolvendo sua retenção, hiponatremia dilucional e hipo-osmolaridade.","D":"O tratamento clínico da SHR é eficaz e o prognóstico é bom.","E":"A síndrome hepatorrenal tipo 1 é tipicamente associada, pelo menos, à duplicação da creatinina\nsérica, para um nível superior a 2,5 mg/dl\nou pela redução da depuração da creatinina para menos\nde 20 ml/min em menos de duas semanas."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212542","number":"212542","sourceNumber":"212542","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Quais as duas principais causas de Lesão Hepática Induzidas por drogas na população\ngeral (DILI ? Drug Induced Liver Injury)?","options":{"A":"Anti-hipertensivos e hipolipemiantes.","B":"Hipoglicemiantes orais e contraceptivos combinados.","C":"Inibidores de bomba de prótons e bifosfonatos.","D":"Antibióticos e anticonvulsivantes.","E":"Anti-inflamatórios e opióides sintéticos."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-208016","number":"208016","sourceNumber":"208016","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Segundo a legislação brasileira de transplantes, são indicações de transplante hepático\ncom doador cadavérico, EXCETO:","options":{"A":"Hemocromatose.","B":"Cirrose secundária à hepatite viral B.","C":"Doença de Budd-Chiari.","D":"Carcinoma hepatocelular de 7 cm.","E":"Hepatite fulminante por paracetamol."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-212523","number":"212523","sourceNumber":"212523","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Para pacientes com hepatopatia crônica, utiliza-se a classificação de Child- Pugh para\navaliar o grau de insuciência hepática. Sobre esta classificação, um paciente com Icterícia (BT 5,0\ne\nBD-3,5), encefalopatia ausente, com ascite pequena (de fácil controle), Albumina de 3,0, INR 2.\n\nQuantos pontos são atribuídos e qual a classe?","options":{"A":"8 - Classe B de Child Pugh","B":"10 - Classe B de Child Pugh","C":"6 - Classe A de Child Pugh","D":"11 - Classe C de Child Pugh","E":"9 - Classe B de Child Pugh"},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-185328","number":"185328","sourceNumber":"185328","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O objetivo do escore APRI é:","options":{"A":"Estimar risco de ressangramento em pacientes com HDA varicosa.","B":"Estimar risco de fratura por osteoporose em 10 anos.","C":"Estimar grau de fibrose hepática.","D":"Estimar risco de quedas em idosos.","E":"Estimar grau de disfunção cognitiva em idosos."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-177206","number":"177206","sourceNumber":"177206","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino com 55 anos, portador de cirrose por vírus c, performance status 1,\nChild B, varizes de esôfago de médio calibre, apresenta-se como nódulo único de 4 cm no\nsegmento 2 do fígado. Qual a melhor conduta para o caso?","options":{"A":"Transplante Hepático com doador cadáver.","B":"Quimioembolização isolada.","C":"Radiofrequência.","D":"Usar sorafenib.","E":"Segmentectomia Hepática."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-187659","number":"187659","sourceNumber":"187659","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A Peritonite Bacteriana Espontânea (PBE) é uma das complicações da cirrose que\nhabitualmente ocorre em pacientes com doença avançada e com impacto significativo no\nprognóstico dos pacientes. Assinale a combinação mais adequada: ( ) Pacientes com episódio\nprévio de PBE devem fazer profilaxia secundária se as proteínas totais no líquido ascítico forem\ninferiores a 1,5g/dl.; ( ) É definida pela presença de mais de 250 leucocitos no líquido ascítico.;\n( )\nDeve ser feita profilaxia antiniótica após hemorragia digestiva alta em pacientes cirróticos mesmo\nassintomáticos.; ( ) A expansão do intravascular com albumina não é mandatória, exceto se ocorrer\ndisfunção renal no momento do diagnóstico.; ( ) A PBE aumenta a chance de ocorrência de\nSíndrome Hepatorrenal.","options":{"A":"VFVFV","B":"FVVFV","C":"FFVFV","D":"FFFVV","E":"VVVFF"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-161837","number":"161837","sourceNumber":"161837","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Pacientes com hepatite alcoólica aguda representam um desafio terapêutico. Acerca\ndas assertivas abaixo, assinale V ou F\n(Verdadeiro ou Falso) e escolha a opção compatível. ( )\nPacientes com função discriminante de Maddrey acima de 32 se beneficiam do uso de\nprednisolona, com redução de mortalidade.; ( ) A pentoxifilina reduz a incidência de síndrome\nhepatorrenal e sua mortalidade, sendo superior a prednisolona em pacientes com formas graves da\ndoença.; ( ) O período de uma semana de tratamento com prednisolona sem resposta clínica e/ou\nlaboratorial significativa autoriza a interrupção de seu uso; ( ) A N-acetilcisteína tem-se\nmostrado a\nmelhor opção em doses elevadas (superiores a 50 mg/kg de peso cada 12 horas), com resultados\nsuperiores aos corticoides na redução da mortalidade, notadamente por menos complicações\ninfecciosas e propriedades antioxidantes.; ( ) Apesar dos resultados superiores a tratamento\nconservador nos casos graves, o transplante hepático é controverso nesses casos, e não permitido\npela normatização vigente no país (requer mínimo de seis meses de abstinência alcóolica)","options":{"A":"V V F F V","B":"V F V F V","C":"F F V F V","D":"V F V V V","E":"V V V F V"},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-161956","number":"161956","sourceNumber":"161956","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente feminina, 32 anos, recebeu diagnóstico de doença de Graves há quatro\nmeses, foi iniciado propanolol e\npropiltiouracil há 2 meses. Refere náuseas, dor abdominal leve,\nadinamia há cerca de um mês e há 7 dias aparecimento de icterícia e há 2 dias começou a\napresentar agitação psicomotora e alteração do sono vigília. Nega comorbidades e uso de outras\nmedicações. Ao exame: desorientação, icterícia ++/4, normocorada, hepatomegalia dolorosa,\ndescompressão brusca (-), flapping (+), Laboratório: Hb 11.6 g/dl; HCT: 30, Leucócitos\n13.460/mm3; Plaquetas 221.000/mm3; TGO 2500 U/I, TGP 3.500 U/I; GGT: Bilirrubina total 17\nmg/dl; Bilirrubina Direta 14 mg/dl; GGT 560 U/I; Albumina 2.9 g/dl; (RNI) 4.5; Creatinina 1.1 g/dl.\nAssinale a alternativa INCORRETA:","options":{"A":"O propiltiouracil pode ser a causa da hepatite da paciente e deve ser suspenso imediatamente.","B":"Os níveis das transaminases se correlacionam com a gravidade da doença e demonstram\npossível necrose hepatocelular","C":"A paciente apresenta falência hepática aguda e pode evoluir para a necessidade de transplante\nhepático.","D":"Vários fatores extra-hepáticos podem contribuir para a encefalopatia como hipoglicemia,\nhiponatremia, uremia, hipóxia e sepse.","E":"Vírus D pode causar falência hepática aguda quando associado com VHB."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-71567","number":"71567","sourceNumber":"71567","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre a patologia biliar litiásica, analise as assertivas abaixo e responda a alternativa\nCORRETA: I) a colecistite aguda alitiásica é mais frequente em diabéticos e sua etiopatogenia é\npor disseminação hematogênica de bactérias; II) o cálculo de pigmento preto são pequenos e\nfirmes, são associados com esferocitose, anemia falciforme e cirrose; III) A síndrome de Mirizzi\npode ser encontrada em associação com a colecistite aguda alitiásica; IV) Para os pacientes idosos\ncom colecistite aguda, deveremos iniciar tratamento clínico com analgesia e antibioticoperapia,\nfazendo uma colecistectomia por VDL, quando ?esfriar? o processo.","options":{"A":"Todas estão corretas.","B":"II e III estão corretas.","C":"Apenas a II está correta.","D":"II e IV estão corretas.","E":"II, III e IV estão corretas."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-68201","number":"68201","sourceNumber":"68201","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Sobre as manifestações hepáticas da hemocromatose hereditária, assinale a assertiva\nFALSA:","options":{"A":"A hepatomegalia é o sinal clínico do aparelho digestório mais frequente, estando presente em\nmais de 90% dos pacientes sintomáticos.","B":"Hepatomegalia pode ser encontrada em 50 a 90% dos pacientes, mesmo na ausência de\nsintomas ou anormalidades nas provas de função hepática.","C":"Cirrose hepática é um fator de risco importante para o desenvolvimento de carcinoma hepático\nprimário em pacientes com hemocromatose hereditária.","D":"Dor abdominal é mais comum em pacientes com cirrose hepática.","E":"A fibrose ou cirrose hepática é encontrada na quase totalidade dos casos, caracteristicamente\ncom comprometimento pré-sinusoidal e lesão micronodular."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-10587","number":"10587","sourceNumber":"10587","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Assinale os dois parâmetros principais para avaliar a gravidade na hepatite alcoólica:","options":{"A":"Tempo e Atividade de Protrombina (TAP) e creatinina","B":"Albumina e gamaglobulina","C":"TAP e bilirrubinas","D":"Creatinina e albumina","E":"Bilirrubina e albumina"},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-351058","number":"351058","sourceNumber":"351058","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Homem de 62 anos, admitido no pronto socorro trazido pelo SAMU, apresenta história\nde vômitos com sangue e fezes enegrecidas há 2\ndias. Sem relato de etilismo. Diagnóstico de\nhepatite no passado, sem acompanhamento. À admissão, paciente sonolento, confuso, pouco\ncolaborativo, com presença de sangue em grande quantidade em orofaringe, abertura ocular ao\nestímulo doloroso e localizando a dor. Abdome globoso, indolor à palpação, com macicez móvel\npresente à percussão e sinal do piparote positivo. Dados vitais: FC 98 bpm, PA 88x53 mmHg,\nsaturando 97% em ar ambiente. Em relação a este caso clínico, analise as assertivas abaixo. I) O\npaciente deve ter uma via aérea definitiva assegurada de forma precoce. II) Na forte suspeita de\nhemorragia digestiva varicosa, os vasoconstrictores esplâncnicos devem ser instituídos\nprecocemente, antes mesmo do tratamento endoscópico. III) A endoscopia digestiva alta deve ser\nrealizada na primeira hora da admissão, em caráter de urgência, como tratamento inicial. IV) A\npresença de sangue no tubo digestivo favorece a translocação bacteriana, que pode resultar em\nperitonite bacteriana espontânea, estando então indicado uso de antibiótico para este paciente.\n\nEstão corretas as assertivas:","options":{"A":"Apenas a I.","B":"Apenas a II e III.","C":"Apenas as III e IV.","D":"Apenas as I, II e IV.","E":"Todas estão corretas."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-350985","number":"350985","sourceNumber":"350985","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Dentre as principais causa de hemorragia digestiva alta, as varizes esofágicas e\ngástricas são comumente encontradas como fonte\ndo sangramento em pacientes com hipertensão\nportal, em especial portadores de cirrose hepática. Sobre o tema, analise as alternativas abaixo e\nassinale a correta.","options":{"A":"Na vigência de sangramento alto proveniente de varizes esofágicas, a endoscopia digestiva alta\ndeve ser realizada, porém sem necessidade de ligadura elástica se o paciente preferir o uso de\nbeta bloqueadores via oral.","B":"A profilaxia primária de sangramento por varizes de esôfago deve ser feita de forma combinada,\nou seja, terapia endoscópica associada a beta\nbloqueadores via oral.","C":"A hemorragia digestiva proveniente de varizes gástricas apresenta manejo endoscópico similar\nao das varizes esofágicas, com a primeira\nlinha de tratamento sendo a ligadura elástica.","D":"A profilaxia secundária de hemorragia digestiva por varizes esofágicas é na maioria das vezes\nrealizada ou com terapia endoscópica ou com tratamento clínico, de forma não combinada.","E":"Em vigência de sangramento ativo por varizes esofágicas é imprescindível a realização de\nendoscopia digestiva alta para terapia endoscópica com associação posterior de fármaco\nendovenoso vasoativo, por exemplo, a terlipressina."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-322034","number":"322034","sourceNumber":"322034","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente de 58 anos de idade, do sexo masculino, com história de etilismo (1 a 1,5\nlitros de destilado/dia) por 30 anos,\napresenta-se para avaliação de aumento de volume abdominal\nde início há 1 ano e piora progressiva. Ao exame, o paciente apresenta icterícia de escleras,\nasterixe, eritema palmar, angiomas aracneiformes no tronco, abdome globoso com macicez móvel\ne piparote positivo. Considerando a explicação mais provável para o caso apresentado, analise as\nassertivas abaixo. I. Está indicada a paracentese diagnóstica. II. Na condição, há vasoconstrição\nesplâncnica, ocasionada por depleção do óxido nítrico. III. Na condição, há ativação de fatores\nantinatriuréticos, com consequente retenção de sódio. IV. A redução de função hepática sintética,\nevidenciada pela icterícia, não tem implicação na gênese do aumento de volume abdominal. Estão\nCORRETAS as assertivas:","options":{"A":"I e II apenas.","B":"I e III apenas.","C":"II e III apenas.","D":"II e IV apenas.","E":"III e IV apenas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-257535","number":"257535","sourceNumber":"257535","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Masculino, 31 anos, é admitido no pronto-socorro com história de vômitos com sangue\ne fezes enegrecidas com uma semana de evolução.\nNega etilismo ou uso de medicamentos.\n\nApendicectomia há 8 anos. Ao exame observa-se um paciente consciente, confuso, com abertura\nocular ao chamado, obedecendo a comandos\nsimples e icterícia de escleras (++/IV+). Abdome\ndistendido com macicez móvel e discreto edema de membros inferiores. Dados vitais: FC 78 bpm,\nPA 90 x 56 mmHg, saturando 97% em ar ambiente. Realiza exames laboratoriais que mostram\nhemoglobina 8,5 g/dl, 51.000 plaquetas, RNI 2,48, BT 3,7 mg/dl com BD 3,2 mg/dl, TGO 29, TGP\n32 e albumina sérica 2,5 g/dl. Em relação a este caso clínico, analise as assertivas abaixo: I) O\natendimento inicial deste paciente deve incluir reposição volêmica vigorosa objetivando\nnormalização da pressão arterial para melhora do nível de consciência. II) A presença de sangue\nno tubo digestivo favorece a translocação bacteriana, o que pode resultar em peritonite bacteriana\nespontânea. III) A endoscopia digestiva alta deve ser realizada em até 1 hora após a admissão\nhospitalar, principalmente em pacientes instáveis e com sangramento ativo. IV) A fisiopatologia que\njustifica o sangramento é de uma contração forçada da parede abdominal contra uma cárdia não\nrelaxada, resultando em laceração da mucosa. Estão CORRETAS as assertivas:","options":{"A":"II apenas.","B":"I e II apenas.","C":"III e IV apenas.","D":"II, III e IV apenas.","E":"Todas assertivas estão corretas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-232699","number":"232699","sourceNumber":"232699","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino de 40 anos chega ao pronto atendimento com queixa de melena e\nhematêmese iniciados hoje. Relata ser etilista crônico, com ingesta de um litro de destilado ao dia\nhá 20 anos. Apresenta-se normocárdico e hipotenso. Em relação a este caso clínico, analise as\nassertivas abaixo e classifique-as em Verdadeira ou Falsa. ( ) No sangramento agudo, a estimativa\nda reserva funcional hepática e as complicações associadas não interferem no tratamento. ( ) O\ntratamento endoscópico de eleição é a escleroterapia e isoladamente produz melhores resultados\nque a terapia farmacológica. ( ) Este paciente se beneficiaria com um série empírica de antibiótico\nde largo espectro por diminuir o risco de ressangramento. ( ) A diminuição da pressão portal se faz\nà custa de terapia farmacológica com drogas imunossupressoras. ( ) O tratamento deste paciente\ndeve ser focado no controle da hipertensão portal e nas suas complicações.","options":{"A":"F ? V ? F ? V ? F.","B":"F ? V ? V ? F ? V.","C":"V ? V ? F ? V ? F.","D":"F ? F ? V ? F ? V.","E":"V ? F ? V ? F ? F."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-202824","number":"202824","sourceNumber":"202824","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Avalie as asserções a seguir e a relação causal proposta entre elas: I - Medicamentos\ncomo o midazolam podem ter suas doses\nnecessárias, orais e intravenosas, reduzidas quando do\nuso em hepatopatas PORQUE: II - a disfunção de hepatócitos, alteração da arquitetura hepática e\nderivações portocava nos pacientes hepatopatas reduzem o metabolismo de primeira passagem.","options":{"A":"As asserções I e II são proposições verdadeiras, e a segunda é uma justificativa da primeira.","B":"As asserções I e II são proposições verdadeiras, mas a segunda não é uma justificativa da\nprimeira.","C":"A asserção I é uma proposição verdadeira e a asserção II é uma proposição falsa.","D":"A asserção I é uma proposição falsa e a asserção II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"B","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174216","number":"174216","sourceNumber":"174216","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo feminino, de 48 anos de idade, procura atendimento por fadiga e\nprurido de evolução de 4 meses. Nega história de tabagismo ou etilismo. Nega comorbidades.\nNega abuso de substâncias ou medicamentos. Ao exame apresenta-se hipocorada, ictérica,\nabdome apresentando macicez móvel e hepatimetria de 14 cm. Análise laboratorial demonstrou\naumento de imunoglobulinas, anticorpo antimitocôndria positivo, bilirrubina total = 4.2 mg/dl,\nbilirrubina direta = 3.8 mg/dl. Considerando o caso descrito, avalie as asserções a seguir e a\nrelação causal proposta entre elas: I. A colestiramina, que é um agente sequestrante dos sais\nbiliares, tem indicação neste caso PORQUE; II. Reduz a progressão da doença quando iniciada\nprecocemente.","options":{"A":"As asserções I e II são proposições verdadeiras, e a segunda é uma justificativa da primeira.","B":"As asserções I e II são proposições verdadeiras, mas a segunda não é uma justificativa da\nprimeira.","C":"A asserção I é uma proposição verdadeira e a asserção II é uma proposição falsa.","D":"A asserção I é uma proposição falsa e a asserção II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-174217","number":"174217","sourceNumber":"174217","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente masculino, 45 anos, dá entrada no pronto-socorro com quadro de melena e\nhematêmese com início hoje pela manhã. Familiares relatam ser o segundo episódio de\nsangramento digestivo em 30 dias. História de etilismo, estando sem uso de álcool desde o\nepisódio anterior de sangramento. Apresenta-se taquicárdico, hipotenso e ictérico (I+/IV), com um\nnível de consciência rebaixado (Glasgow = 10). Em relação a esse caso clínico, assinale a\nassertiva CORRETA:","options":{"A":"O parâmetro para reanimação volêmica inicial é a normalização da pressão arterial e da\nfrequência cardíaca.","B":"O tamponamento com balão de Sengstaken-Blakemore pode ser considerado como conduta\ninicial neste paciente.","C":"O uso de inibidor de bomba de prótons para este paciente só estaria indicado se houvesse\nhistória de uso de antiagregantes plaquetários.","D":"O objetivo da terapia farmacológica neste paciente é promover uma redução da hipertensão\nportal a partir da indução de uma vasoconstrição\nesplâncnica.","E":"Uma reposição volêmica vigorosa adequada com cristaloides melhora a perfusão cerebral e,\nconsequentemente, o nível de consciência, descartando a necessidade de uma via aérea definitiva."},"answer":"D","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-148984","number":"148984","sourceNumber":"148984","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Avalie as asserções a seguir e a relação proposta entre elas. A hemorragia digestiva\nrelacionada com a hipertensão portal é mais\ncomumente resultante de sangramento de varizes, que\nse desenvolvem em resposta ao aumento da pressão no sistema porta, produzindo uma via\ncolateral para a descompressão do sistema porta na circulação venosa sistêmica, PORTANTO, a\nrealização de endoscopia digestiva alta com escleroterapia das varizes esofágicas é o tratamento\ninicial de escolha nestes pacientes.","options":{"A":"As duas assertivas são proposições verdadeiras e a segunda é uma justificativa correta da\nprimeira.","B":"As duas assertivas são proposições verdadeiras, mas a segunda não é uma justificativa correta\nda primeira.","C":"A primeira assertiva é uma proposição verdadeira e a segunda é falsa.","D":"A primeira assertiva é uma proposição falsa e a segunda é verdadeira.","E":"As duas assertivas são proposições falsas."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-148994","number":"148994","sourceNumber":"148994","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"As manifestações clínicas, assim como complicações da cirrose hepática, são\ndecorrentes de duas grandes síndromes\nassociadas à doença: a hipertensão portal e a disfunção\nhepatocelular. Qual das manifestações abaixo está relacionada à disfunção hepatocelular?","options":{"A":"Ascite.","B":"Hiperesplenismo.","C":"Hipoalbuminemia.","D":"Varizes de esôfago.","E":"Circulação colateral abdominal."},"answer":"C","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-126770","number":"126770","sourceNumber":"126770","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"O manejo de uma hemorragia digestiva de origem varicosa possui algumas diferenças\nimportantes em relação à não varicosa. Em relação à hemorragia varicosa, analise as assertivas\nabaixo: I) Uma rápida correção da deficiência de fluidos e da pressão arterial aumenta o risco de\nnovo sangramento das varizes; II) Os defeitos na coagulação são frequentes nesses pacientes e\nprecisam ser corrigidos rigorosamente; III) Esses pacientes devem receber um curso empírico de\nantibiótico de largo espectro e esta terapia deve ser iniciada no momento da alta hospitalar; IV)\nAgentes vasoativos que induzem a vasoconstrição esplâncnica resultam em controle temporário do\nsangramento e seu uso deve ser continuado após a alta hospitalar. Estão CORRETAS as\nafirmativas:","options":{"A":"I e II apenas.","B":"II e IV apenas.","C":"I, III e IV apenas.","D":"I, II e III apenas.","E":"Todas estão corretas."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-103157","number":"103157","sourceNumber":"103157","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"<p>Paciente de 54 anos apresenta 2 semanas de evolução de dor em hipocôndrio\ndireito, icterícia, colúria e mal-estar geral.\nHistória de tabagismo e etilismo pesados. Ao exame,\napresenta-se confuso, com <i>flapping</i>, dor à palpação de hipocôndrio direito, hepatomegalia e\nmacicez móvel. Bilirrubinas totais = 15,2 mg/dl, bilirrubina direta = 11,3 mg/dl, AST = 245 U/L,\nALT\n\n= 102 U/L, gama GT = 142 U/L. Realizou ultrassonografia de abdome que não evidenciou sinais de\nobstrução extra-hepática. Considerando a hipótese diagnóstica mais provável, é CORRETO afirmar\nque:</p>","options":{"A":"O uso de inibidor do TNF como a pentoxifilina pode ser útil em casos severos da doença.","B":"O paciente apresenta falência hepática fulminante e é candidato a transplante imediato do\nfígado.","C":"Anticorpos monoclonais que neutralizam o TNF podem ser utilizados como tratamento de\nsegunda linha.","D":"O uso de corticosteroides deve ser evitado em casos severos da doença pelo risco aumentado\nde morte.","E":"Mesmo casos severos têm baixa mortalidade com abstinência alcoólica."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-103159","number":"103159","sourceNumber":"103159","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Paciente do sexo masculino, de 47 anos de idade, relata aumento abdominal difuso,\nprogressivo, há dois meses. Nega dor abdominal associada. Nega comorbidades. História de\ntabagismo 43 anos/maço e etilismo de um litro de destilado ao dia por 23 anos. Ao exame,\napresenta FC = 100 bpm; FR = 24 irpm; PA = 98 x 64 mmHg; telangiectasias em tronco e\nginecomastia bilateral, ausência de alteração neurológica e abdome difusamente aumentado com\npiparote positivo e macicez móvel. Levando em consideração o diagnóstico mais provável, o\ntratamento mais indicado neste momento é:","options":{"A":"Restrição de sal, seguida de furosemida e espironolactona via oral.","B":"Restrição de sal e diuréticos de alça por via intravenosa.","C":"Restrição de água e diuréticos por via oral.","D":"Paracentese seriada de grande volume.","E":"Shunt porto-cava."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-8376","number":"8376","sourceNumber":"8376","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"Com respeito ao etilismo, assinale a alternativa CORRETA:","options":{"A":"O etilismo é a principal causa de pancreatite aguda.","B":"O etilismo é protetor para o coração, por causar diminuição de pressão arterial dose dependente.","C":"A dosagem sérica de gama-glutamil-transferase é\n\numa ferramenta útil na triagem de etilismo severo, embora parcela significativa deste grupo de\npacientes não eleve esta enzima.","D":"O Delirium tremens é uma complicação que acontece na maioria dos etilistas severos, quando\nsubmetidos a uma abstinência aguda do etanol.","E":"O dissulfiram é um inibidor enzimático que provoca aumento dos níveis de acetaldeído no\nsangue quando do consumo de álcool, gerando\nsintomas bastantes desconfortáveis. Seu uso,\ncomo coadjuvante no tratamento do etilismo é isento de riscos ao paciente."},"answer":"E","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-2-17340","number":"17340","sourceNumber":"17340","collectionBlock":"medcurso:medcurso-hepato-hep-2","collectionLabel":"Medcurso · HEP 2","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 2","subtopic":"","stem":"A ingesta crônica e exagerada de álcool pode causar doença hepática. A patologia da\nlesão hepática causada pelo álcool inclui três mecanismos que coexistem; esteatose, hepatite e\ncirrose. Levando em consideração os dados apresentados acima, escolha a alternativa CORRETA:","options":{"A":"Betabloqueador é o medicamento utilizado para hepatite alcoólica.","B":"A marca da hepatite alcoólica é a injuria do hepatócito, onde se observa aumento dos\npolimorfonucleares.","C":"A histamina produzida na hepatite alcoólica é a responsável pelas manifestações sistêmicas.","D":"As anormalidades laboratoriais observadas na esteatose são específicas e incluem aumento da\naminotransferase aspartato e aminotransferase alanina.","E":"Entre os fatores de risco para o desenvolvimento de doença hepática alcoólica, incluem\ndiabetes."},"answer":"A","source":"Hepato/HEP 2/HEP 2.txt","sourceLabel":"Medcurso · HEP 2","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 2","Medcurso"],"answerSource":"inferred","commentDeferred":true}]};
